export const QUESTION_BANK: Question[] = [
  {"id": "econ-basic-1", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Business cycles", "stem": "The generally recognized phases of the business cycle, in order, are:", "choices": ["Trough, contraction, expansion, peak", "Expansion, contraction, peak, trough", "Peak, expansion, trough, contraction", "Expansion, peak, contraction, trough"], "answerIndex": 3, "explanation": "The recognized sequence is expansion (growth), a peak (top), contraction/recession (falling output and rising unemployment), then a trough (bottom) before the next recovery. A peak follows expansion and a trough follows contraction, so the choices that place a trough before contraction or a peak after contraction scramble the order and are wrong.", "difficulty": "easy", "source": "bank"},
  {"id": "econ-basic-2", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Monetary and fiscal policies", "stem": "The Federal Open Market Committee directs the sale of Treasury securities in the open market. The most direct effect of this action is that it:", "choices": ["increases commercial-bank reserves and encourages new lending", "lowers the discount rate to stimulate borrowing", "is fiscal policy set by Congress and the President", "drains reserves from the banking system and tends to raise short-term interest rates"], "answerIndex": 3, "explanation": "Selling securities removes reserves from the banking system, shrinking the money supply and pushing short-term rates up (a contractionary move), so the last choice is correct. Increasing reserves describes the opposite action (buying), and the discount-rate choice confuses open market operations with a separate Fed tool. Open market operations are monetary policy conducted by the Fed, not fiscal policy set by Congress.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-basic-3", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Inflation/deflation", "stem": "An unexpected and sustained rise in the inflation rate is generally MOST beneficial to which of the following?", "choices": ["A bank holding fixed-rate loans it originated", "A retiree living on a fixed monthly pension", "A homeowner repaying a long-term fixed-rate mortgage", "An investor holding long-term fixed-coupon bonds"], "answerIndex": 2, "explanation": "Surprise inflation lets a fixed-rate borrower repay debt with dollars worth less than expected, so the homeowner benefits - the classic 'borrower wins, lender loses' result. The retiree on a fixed pension, the bank holding fixed-rate loans, and the fixed-coupon bondholder all receive a stream of dollars whose purchasing power has eroded, so each is hurt rather than helped.", "difficulty": "easy", "source": "bank"},
  {"id": "econ-basic-4", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Interest rates, yield curves, credit spreads", "stem": "Yields on 2-year Treasury notes have risen above yields on 10-year Treasury notes, producing an inverted yield curve. This condition is most commonly interpreted as:", "choices": ["a signal that market participants expect slower growth or a possible recession ahead", "a sign of a strengthening expansion with rising long-term inflation expectations", "the normal, upward-sloping shape that prevails in a healthy economy", "proof that credit spreads between corporate bonds and Treasuries have widened"], "answerIndex": 0, "explanation": "An inverted curve (short-term yields above long-term) has historically preceded recessions because investors expect future rate cuts and slower growth, so the first choice is correct. A strengthening expansion is associated with a normal, upward-sloping curve, not an inverted one, and the 'normal shape' choice describes the opposite of inversion. The credit-spread choice confuses the shape of the Treasury curve with a separate concept, the yield premium on corporate bonds.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-basic-5", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Economic indicators (GDP, employment indicators, trade deficit, balance of payments, CPI)", "stem": "Which of the following is classified as a LEADING economic indicator?", "choices": ["Gross domestic product", "The Consumer Price Index", "The civilian unemployment rate", "The index of new private housing building permits"], "answerIndex": 3, "explanation": "Building permits are a classic leading indicator because construction is planned and approved before activity actually occurs, so they tend to turn ahead of the broader economy. The unemployment rate and the CPI are lagging indicators that confirm trends after the fact, and GDP measures current aggregate output rather than anticipating it. (Note that initial jobless claims lead, but the unemployment rate lags.)", "difficulty": "medium", "source": "bank"},
  {"id": "econ-basic-6", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Global and geopolitical factors (currency valuation, exchange-rate effects on returns, sovereign debt)", "stem": "A US investor holds a bond denominated in euros. Which development would MOST likely reduce the investor's total return when measured in US dollars?", "choices": ["The European Central Bank raises rates, drawing capital into the euro", "The euro appreciates relative to the US dollar", "The US dollar weakens against most major currencies", "The US dollar strengthens relative to the euro"], "answerIndex": 3, "explanation": "When the dollar strengthens against the euro, the euros the investor earns convert into fewer dollars, reducing the dollar-denominated return - so that choice is correct. Euro appreciation and a broadly weaker dollar both increase the dollar value of the foreign holding and therefore help the investor. An ECB rate hike tends to attract capital and support the euro, which would boost, not reduce, the dollar-based return.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-basic-7", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Interest rates, yield curves, credit spreads", "stem": "An investor earns a nominal yield of 3% on a bond during a year in which the Consumer Price Index rises 4%. Using the approximate Fisher relationship, the investor's real rate of return is closest to:", "choices": ["-1%", "-4%", "+3%", "+7%"], "answerIndex": 0, "explanation": "Real return is approximately the nominal yield minus inflation: 3% - 4% = -1%. Because prices rose faster than the investment grew, the investor's purchasing power actually fell about 1%, illustrating that real returns can be negative. The +7% choice adds the two figures, the +3% choice ignores inflation entirely, and the -4% choice ignores the nominal yield.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-basic-8", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Global and geopolitical factors (currency valuation, exchange-rate effects on returns, sovereign debt)", "stem": "A US investor's holding of Japanese equities returns 8% measured in yen. Over the same period the yen appreciates 5% against the US dollar. Using compounding, the investor's approximate total return in US-dollar terms is closest to:", "choices": ["13.4%", "3.0%", "8.0%", "5.0%"], "answerIndex": 0, "explanation": "The dollar return combines the local gain and the currency gain: (1.08 x 1.05) - 1 = 0.134, or about 13.4%. Because the yen appreciated (the dollar weakened), the currency move added to the local return rather than subtracting from it. The 8.0% choice ignores the currency effect, the 5.0% choice captures only the currency move, and the 3.0% choice wrongly subtracts the two figures instead of compounding them.", "difficulty": "hard", "source": "bank"},
  {"id": "econ-reporting-1", "subjectId": "econ", "componentId": "econ-reporting", "subtopic": "Financial reports (income statement, balance sheet, statement of cash flows, auditor disclosures, corporate SEC filings, annual reports)", "stem": "Which financial statement is best described as a snapshot of a company's financial position at a single point in time?", "choices": ["The statement of cash flows", "The income statement", "The statement of retained earnings", "The balance sheet"], "answerIndex": 3, "explanation": "The balance sheet reports assets, liabilities, and equity as of one specific date, making it a point-in-time snapshot. The income statement and statement of cash flows both cover a period of time (a movie, not a photo). The statement of retained earnings also describes changes over a period, not a single moment.", "difficulty": "easy", "source": "bank"},
  {"id": "econ-reporting-2", "subjectId": "econ", "componentId": "econ-reporting", "subtopic": "Financial reports (income statement, balance sheet, statement of cash flows, auditor disclosures, corporate SEC filings, annual reports)", "stem": "A company reports total assets of $8 million and total liabilities of $5 million. According to the fundamental accounting equation, what is its shareholders' equity?", "choices": ["$3 million", "$5 million", "$13 million", "$8 million"], "answerIndex": 0, "explanation": "The accounting equation is Assets = Liabilities + Shareholders' Equity, so equity equals assets minus liabilities: $8M - $5M = $3M. $13M incorrectly adds assets and liabilities, $5M restates liabilities, and $8M restates total assets. Shareholders' equity is also called net worth or book value.", "difficulty": "easy", "source": "bank"},
  {"id": "econ-reporting-3", "subjectId": "econ", "componentId": "econ-reporting", "subtopic": "Accounting fundamentals (audited vs. unaudited financials, cash vs. accrual accounting)", "stem": "An IAR is reviewing the most recent quarterly financial statements a public company filed with the SEC on Form 10-Q. Which statement about these figures is correct?", "choices": ["They are unaudited, though typically reviewed by the company's independent accountants", "They are audited and carry an independent auditor's opinion", "They must include a full audit only if the company reported a loss", "They are exempt from SEC filing because they are interim figures"], "answerIndex": 0, "explanation": "Quarterly Form 10-Q financials are unaudited; they are subject to a lighter review by the independent accountants but not a full audit. Only the annual Form 10-K carries a complete audit opinion. Whether the company reported a profit or loss does not trigger an audit, and the 10-Q is itself a required SEC filing, not exempt.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-reporting-4", "subjectId": "econ", "componentId": "econ-reporting", "subtopic": "Financial reports (income statement, balance sheet, statement of cash flows, auditor disclosures, corporate SEC filings, annual reports)", "stem": "An independent auditor concludes that a company's financial statements are NOT presented fairly in accordance with GAAP. Which type of opinion should the auditor issue?", "choices": ["A disclaimer of opinion", "An unqualified opinion", "A qualified opinion", "An adverse opinion"], "answerIndex": 3, "explanation": "An adverse opinion states that the financial statements as a whole are not fairly presented, the most negative substantive conclusion an auditor can reach. An unqualified (clean) opinion is the best result, a qualified opinion flags a specific exception while the rest is fair, and a disclaimer means the auditor could not gather enough evidence to form any opinion at all.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-reporting-5", "subjectId": "econ", "componentId": "econ-reporting", "subtopic": "Accounting fundamentals (audited vs. unaudited financials, cash vs. accrual accounting)", "stem": "Under the accrual method of accounting, when is revenue recognized?", "choices": ["Only at the end of the fiscal year when the books are closed", "When the board of directors formally approves the financial statements", "When the revenue is earned, regardless of when cash is received", "When the cash payment is actually received from the customer"], "answerIndex": 2, "explanation": "Accrual accounting recognizes revenue when it is earned and expenses when they are incurred, independent of cash timing; this is why accounts receivable and deferred revenue exist. Recognizing revenue only when cash is received describes cash-basis accounting. Revenue recognition is tied to the earning event, not to year-end closing or board approval of statements.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-reporting-6", "subjectId": "econ", "componentId": "econ-reporting", "subtopic": "Financial reports (income statement, balance sheet, statement of cash flows, auditor disclosures, corporate SEC filings, annual reports)", "stem": "A company reports positive net income for the year but a decline in its cash balance. An IAR examining the statement of cash flows would most likely explain this by noting that", "choices": ["net income is calculated on a cash basis, so the two figures should always match", "accrual accounting recognizes revenues and expenses independently of cash movement, so profit and cash flow can diverge", "the auditor must have issued an adverse opinion for this to occur", "depreciation increases cash flow above net income, which is impossible with positive earnings"], "answerIndex": 1, "explanation": "Because public-company statements use accrual accounting, timing differences (such as sales booked as accounts receivable that have not yet been collected, or cash outlays that do not line up with when expenses are recognized) can push net income and cash flow apart, so a profitable firm can still see its cash balance fall. Net income is accrual-based, not cash-based, so the two need not match. This divergence is normal and does not imply an adverse opinion. Depreciation is a non-cash charge added back in the operating section, so it does not reduce cash the way it reduces net income; the fourth choice is simply a garbled, false statement.", "difficulty": "hard", "source": "bank"},
  {"id": "econ-reporting-7", "subjectId": "econ", "componentId": "econ-reporting", "subtopic": "Accounting fundamentals (audited vs. unaudited financials, cash vs. accrual accounting)", "stem": "A small business switches from cash-basis to accrual-basis accounting. Which item would newly appear on its financial statements as a direct result of adopting the accrual method?", "choices": ["Cash held in the company's checking account", "Accounts receivable for sales made but not yet collected", "Common stock issued to founders", "Cash proceeds received from a bank loan"], "answerIndex": 1, "explanation": "Accounts receivable arises only under accrual accounting, which records revenue when earned even though the cash has not yet been collected; a pure cash-basis system would not recognize the sale until payment arrives. Cash in the checking account, common stock, and cash loan proceeds are all recorded under either method because they reflect actual cash or equity events, not accrual timing differences.", "difficulty": "hard", "source": "bank"},
  {"id": "econ-analytical-1", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Time value of money (internal rate of return, net present value)", "stem": "An analyst calculates that a proposed investment has an internal rate of return (IRR) of 9%. The firm requires a 12% rate of return on projects of this risk level. Based on this information alone, what is true about the project's net present value (NPV)?", "choices": ["The NPV is negative, so the project should be rejected", "The NPV is positive, so the project should be accepted", "The NPV is exactly zero", "The NPV cannot be determined without the payback period"], "answerIndex": 0, "explanation": "IRR is the discount rate that makes NPV equal zero. When the required rate (12%) exceeds the IRR (9%), discounting the cash flows at the higher required rate produces a negative NPV, so the project should be rejected. The NPV would be positive only if IRR exceeded the required rate, and zero only if they were equal. Payback period is unrelated to the NPV sign.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-analytical-2", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Time value of money (internal rate of return, net present value)", "stem": "Which statement best describes the relationship between net present value (NPV) and internal rate of return (IRR) for a single conventional investment (an initial outflow followed by inflows)?", "choices": ["NPV and IRR always produce opposite accept/reject decisions", "The IRR is the discount rate at which the NPV equals zero", "NPV measures return as a percentage while IRR measures it in dollars", "IRR assumes cash flows are not reinvested, while NPV assumes they are spent"], "answerIndex": 1, "explanation": "By definition, IRR is the discount rate that sets NPV to zero. For a single conventional cash-flow pattern, NPV and IRR agree: NPV is positive precisely when IRR exceeds the discount rate. NPV is expressed in dollars and IRR as a percentage (the third choice reverses this), and the reinvestment description is fabricated.", "difficulty": "easy", "source": "bank"},
  {"id": "econ-analytical-3", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Descriptive statistics (mean, median, mode, range, standard deviation, alpha, beta, Sharpe ratio, correlation)", "stem": "A portfolio returned 11% over a period when the risk-free rate was 3% and the portfolio's standard deviation was 16%. What is the portfolio's Sharpe ratio?", "choices": ["0.50", "0.69", "0.19", "1.38"], "answerIndex": 0, "explanation": "The Sharpe ratio equals (portfolio return - risk-free rate) / standard deviation = (11% - 3%) / 16% = 8 / 16 = 0.50. The 0.69 figure incorrectly divides the full 11% return by 16% (about 0.69), and 0.19 comes from dividing the risk-free rate by the standard deviation (3 / 16). Sharpe uses standard deviation (total risk) in the denominator, not beta.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-analytical-4", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Descriptive statistics (mean, median, mode, range, standard deviation, alpha, beta, Sharpe ratio, correlation)", "stem": "An investment adviser wants to measure a fund manager's return in excess of what would be expected given the fund's exposure to systematic market risk. Which statistic is designed for this purpose?", "choices": ["Correlation coefficient", "Standard deviation", "Current ratio", "Alpha"], "answerIndex": 3, "explanation": "Alpha measures the return earned above or below the level predicted by the fund's beta (its CAPM-expected return); positive alpha indicates the manager added value beyond compensation for market risk. Standard deviation measures total volatility, not excess return. Correlation measures co-movement between two assets, and the current ratio is a liquidity measure unrelated to portfolio performance.", "difficulty": "easy", "source": "bank"},
  {"id": "econ-analytical-5", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Descriptive statistics (mean, median, mode, range, standard deviation, alpha, beta, Sharpe ratio, correlation)", "stem": "An IAR is constructing a portfolio and wants to maximize diversification benefits by combining two asset classes. All else equal, which correlation coefficient between the two assets provides the GREATEST reduction in portfolio risk?", "choices": ["0.0", "+0.4", "-0.7", "+1.0"], "answerIndex": 2, "explanation": "Correlation ranges from -1 to +1, and the lower (more negative) the correlation, the greater the diversification benefit because the assets tend to move in opposite directions, dampening portfolio volatility. Of the choices, -0.7 is the most negative and provides the greatest risk reduction. A correlation of +1.0 provides no diversification benefit at all, and 0.0 (uncorrelated) offers less benefit than a strongly negative value.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-analytical-6", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Descriptive statistics (mean, median, mode, range, standard deviation, alpha, beta, Sharpe ratio, correlation)", "stem": "A fund's monthly returns for five months are 2%, 3%, 3%, 4%, and 18%. Which measure of central tendency is LEAST distorted by the unusually large 18% return and therefore most representative of a typical month?", "choices": ["The mean", "The median", "The standard deviation", "The range"], "answerIndex": 1, "explanation": "The median (the middle value, 3%) is resistant to outliers, making it the most representative typical value in a skewed dataset. The mean is pulled upward to 6% by the single large 18% observation. The range and standard deviation measure dispersion, not central tendency, so they do not describe a 'typical' value.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-analytical-7", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Financial ratios and their uses (current ratio, quick ratio, debt-to-equity ratio)", "stem": "A company reports current assets of $600,000, of which $250,000 is inventory, and current liabilities of $300,000. What are the company's current ratio and quick (acid-test) ratio, respectively?", "choices": ["2.0 and 0.83", "1.17 and 2.0", "2.0 and 1.17", "0.83 and 2.0"], "answerIndex": 2, "explanation": "The current ratio = current assets / current liabilities = 600,000 / 300,000 = 2.0. The quick (acid-test) ratio excludes inventory: (600,000 - 250,000) / 300,000 = 350,000 / 300,000 = 1.17. The correct pairing is therefore 2.0 and 1.17. Choices that reverse the two figures, or that produce 0.83 by subtracting the wrong amount, are incorrect.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-analytical-8", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Financial ratios and their uses (current ratio, quick ratio, debt-to-equity ratio)", "stem": "Which of the following would generally be the strongest signal that a corporation is highly leveraged and may face elevated financial risk?", "choices": ["A current ratio of 2.5", "A price-to-earnings ratio of 15", "A debt-to-equity ratio of 3.0", "A quick ratio of 1.2"], "answerIndex": 2, "explanation": "The debt-to-equity ratio (total debt / total equity) measures leverage; a ratio of 3.0 means the firm has three dollars of debt for every dollar of equity, indicating heavy reliance on borrowed capital and higher financial risk. A current ratio of 2.5 and quick ratio of 1.2 both indicate healthy short-term liquidity, and a P/E of 15 is a valuation measure that says nothing directly about leverage.", "difficulty": "easy", "source": "bank"},
  {"id": "econ-analytical-9", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Valuation ratios (price-to-earnings, price-to-book)", "stem": "Two companies operate in the same mature industry. Company A trades at a price-to-book (P/B) ratio of 0.7, and Company B trades at a P/B ratio of 3.5. Which conclusion is MOST supportable from these figures alone?", "choices": ["Company A has stronger earnings growth than Company B", "Company A's market price is below its net book value per share, which may indicate a value or distressed situation warranting further analysis", "Company A has a higher debt-to-equity ratio than Company B", "Company B is definitively overpriced and should be sold short"], "answerIndex": 1, "explanation": "A P/B below 1.0 means the market price is less than the accounting book value per share, which can flag either an undervalued 'value' opportunity or a distressed company - either way it warrants deeper analysis. P/B alone cannot confirm that Company B is overpriced, nor does it reveal earnings growth or leverage; those require additional data. P/B is a relative valuation tool, not a standalone buy/sell verdict.", "difficulty": "hard", "source": "bank"},
  {"id": "econ-risk-1", "subjectId": "econ", "componentId": "econ-risk", "subtopic": "Systematic risks", "stem": "An investment adviser explains to a client that a particular category of risk affects the entire securities market and cannot be eliminated by adding more securities to a portfolio. Which term best describes this type of risk?", "choices": ["Unsystematic risk", "Business risk", "Systematic risk", "Financial risk"], "answerIndex": 2, "explanation": "Systematic risk (market risk) affects the whole market and cannot be diversified away, which is why it is also called non-diversifiable risk. Unsystematic, business, and financial risks are all company- or issuer-specific and CAN be reduced through diversification, so they do not fit the description of a market-wide, non-diversifiable risk.", "difficulty": "easy", "source": "bank"},
  {"id": "econ-risk-2", "subjectId": "econ", "componentId": "econ-risk", "subtopic": "Systematic risks", "stem": "Which of the following risks is a systematic risk that a well-diversified stock portfolio CANNOT eliminate?", "choices": ["The risk that a single issuer defaults on its bonds", "The risk that a firm's management commits fraud", "The risk that a company's new product line fails", "The risk that rising inflation erodes the purchasing power of returns"], "answerIndex": 3, "explanation": "Purchasing-power (inflation) risk is systematic—it affects the entire market and cannot be diversified away. The other three—single-issuer default, product-line failure, and management fraud—are all unsystematic, company-specific risks that diversification across many holdings can substantially reduce.", "difficulty": "easy", "source": "bank"},
  {"id": "econ-risk-3", "subjectId": "econ", "componentId": "econ-risk", "subtopic": "Unsystematic risks", "stem": "A client holds a portfolio of 40 different corporate bonds spread across many industries. Which risk has this diversification MOST effectively reduced, and which risk remains largely unaddressed?", "choices": ["It reduced both interest-rate and default risk equally", "It reduced default (credit) risk but not interest-rate risk", "It reduced interest-rate risk but not default risk", "It reduced market risk but not reinvestment risk"], "answerIndex": 1, "explanation": "Default (credit) risk is unsystematic and issuer-specific, so spreading holdings across 40 issuers meaningfully diversifies it away. Interest-rate risk is systematic—a rise in rates depresses the prices of virtually all bonds regardless of issuer—so it remains largely unaddressed. The option pairing interest-rate reduction with default is backwards, and the claim that both are reduced equally ignores that interest-rate risk is non-diversifiable.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-risk-4", "subjectId": "econ", "componentId": "econ-risk", "subtopic": "Systematic risks", "stem": "An IAR is comparing two 20-year bonds of identical credit quality: Bond A is a 5% coupon bond and Bond B is a zero-coupon bond. Which statement is correct regarding the risks these bonds carry?", "choices": ["Both bonds have identical interest-rate risk because they share the same maturity", "Bond A has no reinvestment risk because its coupon is fixed", "Bond B has greater reinvestment risk because it pays no periodic coupons", "Bond B has no reinvestment risk but greater interest-rate (price) risk than Bond A"], "answerIndex": 3, "explanation": "A zero-coupon bond makes no interim payments, so there are no coupons to reinvest—eliminating reinvestment risk—but its longer effective duration gives it greater interest-rate (price) sensitivity than an otherwise comparable coupon bond. Saying the zero has greater reinvestment risk is backwards; the coupon bond is the one exposed to reinvestment risk. Equal maturities do not mean equal interest-rate risk, because the zero's higher duration makes it more price-sensitive.", "difficulty": "hard", "source": "bank"},
  {"id": "econ-risk-5", "subjectId": "econ", "componentId": "econ-risk", "subtopic": "Opportunity cost", "stem": "A client is deciding between investing $50,000 in a project expected to return 6% and leaving the money in a Treasury bill yielding 4%. In evaluating the project using the concept of opportunity cost, the 4% Treasury yield represents which of the following?", "choices": ["The project's unsystematic risk premium", "The out-of-pocket expense of undertaking the project", "The baseline return forgone by not choosing the next-best alternative", "A sunk cost that should be ignored in the decision"], "answerIndex": 2, "explanation": "Opportunity cost is the return on the next-best alternative given up when a choice is made; here the 4% risk-free T-bill yield is the baseline the client forgoes by investing in the project instead. It is not an out-of-pocket cash expense, and it is not a sunk cost (sunk costs are already incurred and irrelevant going forward). It is a required-return benchmark, not a risk premium.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-risk-6", "subjectId": "econ", "componentId": "econ-risk", "subtopic": "Opportunity cost", "stem": "An investor's savings currently earn 2% in a money market fund. She is considering an investment with comparable liquidity and risk that yields 5%. From the standpoint of opportunity cost, which statement best describes the situation if she leaves her money in the money market fund?", "choices": ["Opportunity cost does not apply because both options are cash-equivalent", "She incurs no opportunity cost because the money market fund has no risk", "Her opportunity cost equals the full 5% offered by the alternative", "She forgoes an opportunity cost of roughly 3 percentage points of additional return"], "answerIndex": 3, "explanation": "Opportunity cost is the difference between the return of the chosen option and the next-best forgone alternative; by staying at 2% instead of a comparable 5% investment, she gives up about 3 percentage points. It is not the full 5%, because she still earns 2% on the chosen option. Opportunity cost applies to every choice among alternatives, including low-risk cash-equivalents.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-risk-7", "subjectId": "econ", "componentId": "econ-risk", "subtopic": "Capital structure including liquidation priority", "stem": "A corporation is being liquidated in bankruptcy. Rank the following claimants from FIRST to LAST in priority to receive proceeds: (1) common stockholders, (2) holders of subordinated debentures, (3) holders of senior secured bonds, (4) preferred stockholders.", "choices": ["3, 2, 4, 1", "1, 4, 2, 3", "3, 4, 2, 1", "2, 3, 1, 4"], "answerIndex": 0, "explanation": "In liquidation, all debt is paid before any equity. Senior secured bondholders (3) rank first, followed by subordinated debenture holders (2), then equity holders in order of preferred stockholders (4) and finally common stockholders (1), who are residual owners paid last. The other orderings incorrectly place equity ahead of debt or reverse the debt seniority, both of which violate the standard liquidation waterfall.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-risk-8", "subjectId": "econ", "componentId": "econ-risk", "subtopic": "Capital structure including liquidation priority", "stem": "In a corporate liquidation, after secured creditors have been satisfied, which of the following claimants has priority over the others listed?", "choices": ["The board of directors' deferred compensation as equity units", "Preferred stockholders", "Common stockholders", "Holders of unsecured debentures"], "answerIndex": 3, "explanation": "Unsecured debenture holders are creditors, and all creditors (secured and unsecured) are paid before any equity holders. Preferred and common stockholders are equity and rank behind all debt; preferred ranks above common, but both come after debentures. Equity-based compensation units are equity claims and are subordinate to all debt as well.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-cash-1", "subjectId": "vehicles", "componentId": "veh-cash", "subtopic": "Insured deposits (demand deposits, certificates of deposit)", "stem": "Which of the following held at an FDIC-insured commercial bank is covered by FDIC deposit insurance up to the applicable limit?", "choices": ["The full $1,000,000 principal of a single negotiable jumbo CD", "Shares of a money market mutual fund purchased through the bank", "A demand deposit (checking) account and a retail certificate of deposit", "A Treasury bill bought through the bank's brokerage desk"], "answerIndex": 2, "explanation": "FDIC insurance covers bank deposit products — demand deposits (checking), savings, money market deposit accounts, and CDs — up to $250,000 per depositor, per bank, per ownership category. A $1,000,000 negotiable CD is insured only to $250,000, not its full face, so choice A is wrong. Money market mutual fund shares and T-bills are securities, not deposits, and carry no FDIC coverage (a T-bill is instead backed by the US Treasury).", "difficulty": "easy", "source": "bank"},
  {"id": "veh-cash-2", "subjectId": "vehicles", "componentId": "veh-cash", "subtopic": "Insured deposits (demand deposits, certificates of deposit)", "stem": "A negotiable (jumbo) certificate of deposit differs from a traditional retail CD primarily because it:", "choices": ["Can be sold in the secondary market before maturity instead of incurring an early-withdrawal penalty", "Is fully insured by the FDIC regardless of its denomination", "Pays no interest because it is classified as a demand deposit", "Always carries a maturity longer than five years"], "answerIndex": 0, "explanation": "Negotiable CDs (typically $1,000,000 or more) trade in an active secondary market, so a holder needing cash sells the instrument rather than paying the early-withdrawal penalty that applies to non-negotiable retail CDs. FDIC coverage is capped at $250,000, so a jumbo CD is not fully insured (A wrong). Negotiable CDs are money market instruments with maturities of one year or less, not 5+ years (C wrong). CDs are interest-bearing time deposits, not demand deposits (D wrong).", "difficulty": "medium", "source": "bank"},
  {"id": "veh-cash-3", "subjectId": "vehicles", "componentId": "veh-cash", "subtopic": "Money market instruments (commercial paper, Treasury bills)", "stem": "Under the Securities Act of 1933, commercial paper is treated as an exempt security (and thus generally does not require registration) provided that it:", "choices": ["Has a maturity of 270 days or less and is issued to fund current transactions", "Is secured by a first lien on the issuer's real property", "May be issued only by commercial banks and thrift institutions", "Carries a stated maturity of at least one year"], "answerIndex": 0, "explanation": "Section 3(a)(3) exempts prime-quality negotiable commercial paper with a maturity of 270 days or less whose proceeds fund current operations (working capital). Commercial paper is unsecured corporate debt, so it is not backed by real property (B wrong), and it is issued by corporations such as finance companies and industrials, not only banks (C wrong). Its defining feature is a short maturity of 270 days or less, not one year or more (D wrong).", "difficulty": "medium", "source": "bank"},
  {"id": "veh-cash-4", "subjectId": "vehicles", "componentId": "veh-cash", "subtopic": "Money market instruments (commercial paper, Treasury bills)", "stem": "Which statement about US Treasury bills is CORRECT?", "choices": ["They pay a fixed semiannual coupon and are redeemed at a discount to par", "They are issued at a discount, and the interest earned is exempt from state and local income tax", "Their interest is exempt from federal income tax but is taxable by the states", "They are backed by the general taxing power of the issuing municipality"], "answerIndex": 1, "explanation": "T-bills are sold at a discount to par and redeemed at face value; the resulting gain is treated as interest that is exempt from state and local tax but subject to federal income tax, like all Treasury securities. They have no stated coupon — the discount is the return — so A is wrong. Choice C reverses the correct tax treatment. T-bills are direct obligations of the US Treasury (federal full faith and credit), not a municipality (D wrong).", "difficulty": "easy", "source": "bank"},
  {"id": "veh-cash-5", "subjectId": "vehicles", "componentId": "veh-cash", "subtopic": "Money market instruments (commercial paper, Treasury bills)", "stem": "An investor buys a 26-week (182-day) US Treasury bill with a $100,000 face value at a price of $98,200 and holds it to maturity. What is the investor's dollar return, and how is that return characterized for tax purposes?", "choices": ["$2,000, treated as a short-term capital gain", "$1,800, treated as interest income — federally taxable but exempt from state and local tax", "$1,800, treated as a long-term capital gain", "$1,800, fully exempt from federal, state, and local income tax"], "answerIndex": 1, "explanation": "The return is the maturity value minus the purchase price: $100,000 - $98,200 = $1,800. For a T-bill held to maturity, that discount is treated as interest income, which is subject to federal income tax but exempt from state and local tax. It is not a capital gain (A and C wrong), and the $2,000 figure in C is also arithmetically incorrect. The return is federally taxable, so it is not fully tax-exempt (D wrong).", "difficulty": "hard", "source": "bank"},
  {"id": "veh-fixed-types-1", "subjectId": "vehicles", "componentId": "veh-fixed-types", "subtopic": "U.S. government and agency securities (Treasuries, MBS from Fannie Mae/Freddie Mac, TIPS)", "stem": "Which characteristic best distinguishes Treasury Inflation-Protected Securities (TIPS) from conventional fixed-rate Treasury bonds?", "choices": ["TIPS pay no interest and are always sold at a deep discount to par", "TIPS interest is exempt from federal income tax", "The principal value of TIPS is adjusted based on changes in the Consumer Price Index", "TIPS are backed by a pool of residential mortgages rather than the U.S. Treasury"], "answerIndex": 2, "explanation": "TIPS protect against inflation by adjusting their principal to the CPI; the fixed coupon rate is then applied to the adjusted principal, so the dollar interest payment rises with inflation. Choice A describes zero-coupon instruments such as T-bills or STRIPS, not TIPS. Choice B is wrong because Treasury interest - including TIPS - is taxable at the federal level (only state and local tax is exempt). Choice D describes agency mortgage-backed securities, not Treasury-issued TIPS.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-fixed-types-2", "subjectId": "vehicles", "componentId": "veh-fixed-types", "subtopic": "Municipal bonds (general obligation, revenue, insured vs. uninsured)", "stem": "A municipality wants to finance construction of a toll bridge and intends to repay bondholders solely from the tolls the bridge collects. Which statement about the bonds it will most likely issue is correct?", "choices": ["They are general obligation bonds backed by the municipality's full taxing power", "Interest paid to bondholders is fully taxable at the federal level", "They must be secured by ad valorem (property) taxes before they can be issued", "They are revenue bonds, and they generally do not require voter approval"], "answerIndex": 3, "explanation": "Bonds repaid only from a specific project's income (bridge tolls) are revenue bonds; because they are not backed by the issuer's taxing power, they typically do not require voter approval or count against statutory debt limits. Choices A and C describe general obligation bonds, which are backed by full faith, credit, and ad valorem taxing power. Choice B is wrong because municipal bond interest is generally exempt from federal income tax.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-fixed-types-3", "subjectId": "vehicles", "componentId": "veh-fixed-types", "subtopic": "Corporate bonds", "stem": "In a corporate liquidation, which of the following claims would be satisfied LAST among the choices listed?", "choices": ["First mortgage bondholders", "Equipment trust certificate holders", "Subordinated debenture holders", "Debenture holders"], "answerIndex": 2, "explanation": "Subordinated debentures rank below both secured debt and senior unsecured debt, so among the choices they are paid last. First mortgage bonds (A) and equipment trust certificates (B) are secured obligations with the highest priority. Ordinary debentures (D) are unsecured general creditors but still rank ahead of subordinated debentures. The general order is secured creditors, then senior debentures, then subordinated debentures, then preferred and common stock.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-fixed-types-4", "subjectId": "vehicles", "componentId": "veh-fixed-types", "subtopic": "Asset-backed securities", "stem": "An IAR is explaining asset-backed securities (ABS) to a client. Which statement is most accurate?", "choices": ["ABS are typically collateralized by pools of non-mortgage receivables such as auto loans and credit card balances and are issued through a special purpose entity", "ABS are always backed by the full faith and credit of the U.S. government", "Because ABS are secured by real property, they carry essentially no prepayment risk", "Interest earned on ABS is exempt from federal income tax, similar to municipal bonds"], "answerIndex": 0, "explanation": "ABS are created by securitizing pools of non-mortgage receivables - auto loans, credit card balances, student loans, equipment leases - through a special purpose entity, usually with credit enhancement. Choice B is false: ABS are private-sector securities with no government guarantee. Choice C is wrong because ABS backed by prepayable consumer loans do carry prepayment risk, and they are generally not secured by real property. Choice D is incorrect because ABS interest is fully taxable.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-fixed-types-5", "subjectId": "vehicles", "componentId": "veh-fixed-types", "subtopic": "Foreign bonds (government debt, corporate debt)", "stem": "A U.S. investor buys bonds issued by a foreign government and denominated in that country's local currency. If that currency depreciates significantly against the U.S. dollar before the bonds mature, what is the most likely effect on the investor's return?", "choices": ["The return will rise because a weaker currency forces the issuer to pay a higher coupon", "There is no effect, because sovereign government bonds eliminate currency risk", "The bonds automatically convert to U.S. dollars at the original exchange rate at maturity", "The return will decrease when the foreign-currency interest and principal are converted back into U.S. dollars"], "answerIndex": 3, "explanation": "A bond denominated in a foreign currency exposes a U.S. investor to currency (exchange-rate) risk. If the foreign currency weakens against the dollar, the foreign-currency cash flows convert into fewer dollars, reducing the total return. Choice A confuses a fixed coupon with currency movements. Choices B and C are false - sovereign status does not remove currency risk, and there is no automatic conversion at a fixed original rate.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-fixed-types-6", "subjectId": "vehicles", "componentId": "veh-fixed-types", "subtopic": "U.S. government and agency securities (Treasuries, MBS from Fannie Mae/Freddie Mac, TIPS)", "stem": "Which statement correctly compares U.S. agency and mortgage-backed securities?", "choices": ["Interest on all Treasury and agency securities is exempt from state and local income tax", "Ginnie Mae (GNMA) pass-throughs are backed by the full faith and credit of the U.S. government, whereas Fannie Mae (FNMA) and Freddie Mac (FHLMC) securities are not explicitly guaranteed", "Mortgage-backed pass-through securities are free of prepayment risk because homeowners rarely refinance", "Fannie Mae is a federal agency whose securities carry an explicit U.S. government guarantee"], "answerIndex": 1, "explanation": "Ginnie Mae is a government-owned corporation, so its MBS carry the full faith and credit of the U.S.; Fannie Mae and Freddie Mac are government-sponsored enterprises whose securities are not explicitly guaranteed. Choice A is wrong because agency mortgage-backed securities (including Ginnie, Fannie, and Freddie pass-throughs) are taxable at the state and local level, unlike Treasury interest. Choice C is false, as pass-throughs carry significant prepayment (and extension) risk. Choice D is wrong because Fannie Mae is a GSE, not a federal agency, and its securities lack an explicit government guarantee.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-fixed-char-1", "subjectId": "vehicles", "componentId": "veh-fixed-char", "subtopic": "Characteristics (tax implications, liquidity, liquidation preference, call features, coupon vs. zero coupon, duration, premium)", "stem": "An investor in the 35% federal tax bracket is comparing two bonds of equal credit quality and maturity: a corporate bond yielding 6.0% and an in-state municipal bond yielding 4.2%. Ignoring state taxes, which statement is most accurate?", "choices": ["The municipal bond is superior because its tax-equivalent yield of about 6.46% exceeds the corporate yield.", "The corporate bond is superior because 6.0% is greater than 4.2% on a nominal basis.", "The two bonds offer identical after-tax returns because yields already reflect taxes.", "The municipal bond's interest is taxable at the federal level, making the corporate bond superior."], "answerIndex": 0, "explanation": "The tax-equivalent yield converts the tax-free municipal yield to a taxable-equivalent: 4.2% / (1 - 0.35) = 6.46%, which exceeds the corporate's 6.0%, so the muni wins for this high-bracket investor. Choice B ignores the tax exemption. Choice C is false because muni yields are stated tax-free, not net of an assumed tax. Choice D is wrong because municipal bond interest is federally tax-exempt.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-fixed-char-2", "subjectId": "vehicles", "componentId": "veh-fixed-char", "subtopic": "Characteristics (tax implications, liquidity, liquidation preference, call features, coupon vs. zero coupon, duration, premium)", "stem": "A corporation files for bankruptcy and is liquidated. Which of the following claimants has the HIGHEST priority to the firm's assets?", "choices": ["Preferred stockholders", "Holders of the company's subordinated debentures", "Holders of unsecured debentures", "Holders of secured mortgage bonds"], "answerIndex": 3, "explanation": "Liquidation priority runs from secured creditors, to general/unsecured creditors, to subordinated debt, then preferred stock, then common stock. Secured mortgage bondholders are backed by specific pledged assets and stand first among these choices. Unsecured debentures and subordinated debentures rank below secured debt, and preferred stockholders (equity owners) are paid only after all creditors.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-fixed-char-3", "subjectId": "vehicles", "componentId": "veh-fixed-char", "subtopic": "Characteristics (tax implications, liquidity, liquidation preference, call features, coupon vs. zero coupon, duration, premium)", "stem": "Which pair of bonds, all else equal, would have the GREATEST price sensitivity to a change in market interest rates?", "choices": ["A 20-year zero-coupon bond", "A 20-year, 8% coupon bond", "A 5-year zero-coupon bond", "A 5-year, 8% coupon bond"], "answerIndex": 0, "explanation": "Price sensitivity is measured by duration, which increases with longer maturity and lower coupon. A zero-coupon bond has duration equal to its maturity, so the 20-year zero has the longest duration of these choices and the greatest volatility. The 20-year 8% coupon bond has a shorter duration than the 20-year zero because its interim coupons return capital sooner, and both 5-year bonds have much shorter durations.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-fixed-char-4", "subjectId": "vehicles", "componentId": "veh-fixed-char", "subtopic": "Valuation factors (maturity, yield-to-call, yield-to-maturity, conversion valuation, bond ratings, credit spread, discounted cash flow)", "stem": "An IAR is reviewing a callable corporate bond currently trading at a premium. To assess the least favorable realistic return an investor might earn, which measure should the IAR emphasize, and why?", "choices": ["Yield-to-maturity, because premium bonds are almost never called", "Yield-to-call, because a premium bond is likely to be called and YTC is lower than YTM", "Current yield, because it reflects the annual coupon relative to the premium price", "Nominal yield, because the coupon is fixed for the life of the bond"], "answerIndex": 1, "explanation": "For a premium (high-coupon) bond, the issuer has a strong incentive to call and refinance at lower rates, and the yield-to-call is lower than the yield-to-maturity, making YTC the yield-to-worst the IAR should highlight. Current yield and nominal yield ignore the capital loss as the premium amortizes toward the call/par price. YTM overstates the likely return because it assumes the bond survives to maturity despite being callable at a premium.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-fixed-char-5", "subjectId": "vehicles", "componentId": "veh-fixed-char", "subtopic": "Valuation factors (maturity, yield-to-call, yield-to-maturity, conversion valuation, bond ratings, credit spread, discounted cash flow)", "stem": "A convertible bond has a par value of $1,000 and a conversion price of $40. If the underlying common stock is currently trading at $52 per share, what is the bond's conversion (parity) value?", "choices": ["$1,000", "$1,300", "$1,250", "$1,040"], "answerIndex": 1, "explanation": "The conversion ratio equals par divided by the conversion price: $1,000 / $40 = 25 shares. The conversion (parity) value equals the conversion ratio times the current stock price: 25 x $52 = $1,300. Choice A ($1,000) is merely par and ignores the stock price. $1,250 would result only if the stock were $50 (25 x $50). $1,040 does not follow from the correct 25-share ratio applied to the $52 stock price.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-fixed-char-6", "subjectId": "vehicles", "componentId": "veh-fixed-char", "subtopic": "Valuation factors (maturity, yield-to-call, yield-to-maturity, conversion valuation, bond ratings, credit spread, discounted cash flow)", "stem": "During a period of rising economic uncertainty, the yield spread between BBB-rated corporate bonds and comparable-maturity U.S. Treasuries widens from 150 basis points to 275 basis points. What does this most directly indicate?", "choices": ["The duration of the corporate bonds has decreased relative to the Treasuries", "The credit rating of U.S. Treasuries has been downgraded relative to corporates", "Investors are demanding more compensation for the perceived credit risk of the corporate bonds", "The corporate bonds have been upgraded to a higher investment-grade rating"], "answerIndex": 2, "explanation": "The credit spread is the additional yield investors require over a risk-free Treasury to hold a riskier bond; a widening spread signals that investors perceive greater default risk and demand more compensation, typical in economic stress. It does not imply Treasuries were downgraded (they remain the benchmark), nor that the corporates were upgraded (an upgrade would narrow the spread). Spread reflects credit risk, not a direct measure of relative duration.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-fixed-char-7", "subjectId": "vehicles", "componentId": "veh-fixed-char", "subtopic": "Characteristics (tax implications, liquidity, liquidation preference, call features, coupon vs. zero coupon, duration, premium)", "stem": "A client wants to fund a child's college tuition due in exactly 12 years and is concerned about reinvestment risk on interest payments. An IAR notes that the recommended instrument will generate taxable 'phantom income' each year. Which security is the IAR most likely describing, and in what account is it best held?", "choices": ["An in-state municipal bond, best held in a traditional IRA", "A high-coupon premium corporate bond, best held in a taxable brokerage account", "A floating-rate note, best held in a municipal bond fund", "A zero-coupon bond, best held in a tax-advantaged account such as a 529 plan"], "answerIndex": 3, "explanation": "A zero-coupon bond is bought at a deep discount and pays no periodic interest, so it eliminates reinvestment risk and provides a known lump sum at a target date, ideal for funding a future goal. However, its annual accreted original issue discount is taxed as phantom income even though no cash is received, so it is best held in a tax-advantaged account such as a 529 plan. A premium coupon bond creates reinvestment risk and no phantom income; a floating-rate note does not lock in a maturity value; and placing a tax-exempt municipal bond in an IRA wastes its exemption.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-equity-types-1", "subjectId": "vehicles", "componentId": "veh-equity-types", "subtopic": "Common stock, domestic and foreign", "stem": "In a corporate liquidation, which class of investor has the LOWEST priority claim on the company's remaining assets?", "choices": ["Common stockholders", "General (unsecured) creditors", "Secured bondholders", "Preferred stockholders"], "answerIndex": 0, "explanation": "Common stockholders have only a residual claim, so they are paid last in liquidation — after secured creditors, general creditors/bondholders, and preferred stockholders. Bondholders and general creditors are creditors and rank ahead of all equity. Preferred stockholders rank ahead of common but behind all creditors, so they are not last. Only common stock sits at the bottom of the priority ladder.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-equity-types-2", "subjectId": "vehicles", "componentId": "veh-equity-types", "subtopic": "Common stock, domestic and foreign", "stem": "A U.S. investor purchases American Depositary Receipts (ADRs) of a Japanese manufacturer. Which statement about this position is CORRECT?", "choices": ["The ADRs trade and pay dividends in U.S. dollars, but the investor still bears currency (exchange-rate) risk", "Holding ADRs eliminates currency risk because settlement occurs in U.S. dollars", "ADR holders receive full voting rights identical to holders of the underlying ordinary shares", "ADRs are exempt from any foreign dividend withholding tax"], "answerIndex": 0, "explanation": "ADRs are U.S.-dollar-denominated receipts for foreign shares on deposit at a bank; they trade and pay dividends in dollars, yet the underlying foreign value must be converted to USD, so exchange-rate risk remains. Settling in dollars does not remove that currency risk, so the second choice is wrong. Voting rights are typically held by the depositary bank, not passed through identically to ADR holders, making the third choice wrong. Foreign governments often withhold tax on the dividends, so ADRs are not exempt from withholding.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-types-3", "subjectId": "vehicles", "componentId": "veh-equity-types", "subtopic": "Preferred and convertible preferred stock", "stem": "A corporation has issued 6% cumulative preferred stock (par $100). Because of poor earnings, the board omitted the preferred dividend for two full years and now wishes to resume paying a dividend to common shareholders. Before any common dividend may be paid, how much per share must the company pay the cumulative preferred holders?", "choices": ["$6, representing only the current year's dividend", "$0, because omitted dividends on preferred stock are permanently lost", "$18, representing the two omitted years plus the current year", "$12, representing the two omitted years in arrears"], "answerIndex": 2, "explanation": "Cumulative preferred requires that all dividends in arrears PLUS the current dividend be paid in full before common shareholders receive anything. At $6 per year, two omitted years ($12) plus the current year ($6) totals $18 per share. Paying only $6 or only $12 ignores part of what has accumulated. The dividends are not lost — that would describe straight (noncumulative) preferred, not cumulative.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-types-4", "subjectId": "vehicles", "componentId": "veh-equity-types", "subtopic": "Preferred and convertible preferred stock", "stem": "A convertible preferred stock has a par value of $100 and is convertible into common at a conversion price of $25. The common stock currently trades at $30 per share. Which statement best describes the position?", "choices": ["The conversion ratio is 3.33 shares, and the parity price of the preferred is $100", "The conversion ratio is 25 shares, and the preferred is trading below parity", "The conversion ratio is 4 shares, and the parity price of the preferred is $120", "The conversion ratio is 4 shares, and the investor should convert only if the common falls below $25"], "answerIndex": 2, "explanation": "Conversion ratio = par / conversion price = $100 / $25 = 4 shares. Parity value of the preferred = market price of common x ratio = $30 x 4 = $120, so the preferred is worth at least $120 based on conversion. The 25-share and 3.33-share figures use the wrong formula. Converting makes sense when the common rises above the conversion price (as here at $30), not when it falls below $25, so that choice reverses the logic.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-equity-char-1", "subjectId": "vehicles", "componentId": "veh-equity-char", "subtopic": "Shareholder rights (voting rights, antidilution, liquidation preferences)", "stem": "Which right is normally held by common stockholders but generally NOT by holders of a corporation's typical (nonconvertible, noncumulative) preferred stock?", "choices": ["Priority over common stockholders in a liquidation", "A stated par value printed on the certificate", "The right to vote for the board of directors and on major corporate matters", "A fixed, stated annual dividend rate"], "answerIndex": 2, "explanation": "Common stock's defining right is voting control (electing directors and approving major actions); typical preferred is nonvoting in exchange for its economic preferences. A fixed dividend rate and liquidation priority are preferred-stock features, not common-stock features, and both classes may carry a stated par value, so those choices do not distinguish the two.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-equity-char-2", "subjectId": "vehicles", "componentId": "veh-equity-char", "subtopic": "Restricted stock and resale restrictions", "stem": "An affiliate (control person) plans to sell restricted stock under SEC Rule 144. The issuer has 4,000,000 shares outstanding, and the average weekly trading volume over the most recent four weeks is 30,000 shares. What is the greatest number of shares the affiliate may sell during any 90-day period?", "choices": ["30,000 shares", "34,000 shares", "40,000 shares", "70,000 shares"], "answerIndex": 2, "explanation": "Rule 144 limits an affiliate's sales to the greater of 1% of shares outstanding (1% x 4,000,000 = 40,000) or the average weekly trading volume over the preceding four weeks (30,000). The greater amount is 40,000. Choosing 30,000 ignores the 1% test, 70,000 wrongly adds the two figures together, and 34,000 is not a measure the rule uses.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-equity-char-3", "subjectId": "vehicles", "componentId": "veh-equity-char", "subtopic": "Dividends", "stem": "A corporation has outstanding 6% cumulative preferred stock with a $100 par value. The company paid no preferred dividends during the previous two years. Before any dividend may be paid to common stockholders this year, how much must each preferred share receive?", "choices": ["$18", "$24", "$12", "$6"], "answerIndex": 0, "explanation": "The annual dividend is 6% x $100 = $6. Because the preferred is cumulative, the two missed years ($6 x 2 = $12) accumulate in arrears and must be paid along with the current year's $6, totaling $18 per share before common stockholders receive anything. $6 counts only the current year, $12 counts only the arrears, and $24 overstates the obligation by one year.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-char-4", "subjectId": "vehicles", "componentId": "veh-equity-char", "subtopic": "Employee stock options (incentive, nonqualified)", "stem": "An employee is granted incentive stock options (ISOs) and later exercises them at a time when the stock's fair market value exceeds the exercise price. Which statement about the federal income tax treatment is correct?", "choices": ["The employee must sell the shares within 12 months of exercise to obtain long-term capital gains treatment.", "The employer may deduct the bargain element as a compensation expense in the year of exercise.", "There is no regular income tax at grant or exercise, but the bargain element at exercise is a positive adjustment for alternative minimum tax (AMT) purposes.", "The bargain element at exercise is taxed to the employee as ordinary compensation income."], "answerIndex": 2, "explanation": "With ISOs there is no regular income tax at grant or exercise, but the bargain element (FMV minus exercise price) is an AMT adjustment in the year of exercise. Ordinary-income treatment at exercise and a matching employer deduction describe nonqualified options (NSOs), not ISOs. Favorable long-term treatment actually requires holding the stock at least one year after exercise and two years after grant - the opposite of selling within 12 months.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-equity-char-5", "subjectId": "vehicles", "componentId": "veh-equity-char", "subtopic": "Shareholder rights (voting rights, antidilution, liquidation preferences)", "stem": "Which statement best describes the liquidation preference attached to a share of preferred stock?", "choices": ["It permits preferred holders to convert their shares into common stock upon dissolution.", "It guarantees that the stated preferred dividend will be paid in every year the company operates.", "It gives preferred holders a claim on the firm's assets ahead of common stockholders, though still behind the company's creditors, if the firm is dissolved.", "It gives preferred holders the first claim on corporate assets, ahead of secured creditors."], "answerIndex": 2, "explanation": "A liquidation preference ranks preferred stock ahead of common stock but behind all creditors when a company is dissolved. It does not guarantee ongoing dividends (dividends must be declared and are a separate right), it is not a conversion feature, and it never leapfrogs creditors, who are always paid before any stockholder receives a distribution.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-value-1", "subjectId": "vehicles", "componentId": "veh-equity-value", "subtopic": "Technical analysis", "stem": "An analyst reviews a stock's price chart, notes a level around $50 where the price has repeatedly stopped falling and buyers have stepped in, and watches trading volume to time a purchase. This approach is best described as which type of analysis, and $50 represents what?", "choices": ["Fundamental analysis; the intrinsic value", "Technical analysis; a resistance level", "Fundamental analysis; the book value", "Technical analysis; a support level"], "answerIndex": 3, "explanation": "Studying price charts and volume to time trades is technical analysis, not fundamental analysis (which examines financial statements and intrinsic value). A price floor where buying repeatedly emerges is a support level; a resistance level is the opposite - a ceiling where selling emerges. Book value and intrinsic value are fundamental concepts and are not read off a price chart.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-equity-value-2", "subjectId": "vehicles", "componentId": "veh-equity-value", "subtopic": "Fundamental analysis", "stem": "A fundamental analyst estimates that a company's stock has an intrinsic value of $80 per share, while the stock currently trades at $62. Based solely on this analysis, the stock is considered:", "choices": ["Overbought, based on momentum signals", "Fairly valued, warranting no action", "Overvalued, and a candidate to sell or avoid", "Undervalued, and a candidate to buy"], "answerIndex": 3, "explanation": "Fundamental analysis compares estimated intrinsic value to market price. Because the intrinsic value ($80) exceeds the market price ($62), the stock is trading below what it is worth and is therefore undervalued - a potential buy. It is not overvalued (that would require the price to exceed intrinsic value). 'Overbought' is a technical/momentum term, not a fundamental conclusion.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-equity-value-3", "subjectId": "vehicles", "componentId": "veh-equity-value", "subtopic": "Dividend discount model", "stem": "A company just paid an annual dividend of $2.00 per share. Dividends are expected to grow at a constant 5% per year, and an investor requires a 9% rate of return. Using the constant-growth dividend discount model, the estimated value of the stock is closest to:", "choices": ["$40.00", "$25.00", "$50.00", "$52.50"], "answerIndex": 3, "explanation": "The Gordon Growth model uses next year's dividend: D1 = D0 x (1 + g) = $2.00 x 1.05 = $2.10. Value = D1 / (k - g) = $2.10 / (0.09 - 0.05) = $2.10 / 0.04 = $52.50. The $50.00 answer is the trap from incorrectly using the current dividend D0 = $2.00 in the numerator ($2.00 / 0.04). The other figures come from mismatching the growth or return inputs.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-value-4", "subjectId": "vehicles", "componentId": "veh-equity-value", "subtopic": "Discounted cash flow", "stem": "An IAR is valuing a stock using a discounted cash flow model. If the analyst decides the investment is riskier than first assumed and therefore raises the required rate of return (discount rate) used in the model, while holding all projected cash flows unchanged, the estimated present value of the stock will:", "choices": ["Increase, because higher required returns raise expected cash flows", "Increase, because the discount rate and value move together", "Remain unchanged, because cash flows were not revised", "Decrease, because future cash flows are discounted more heavily"], "answerIndex": 3, "explanation": "In any DCF, present value and the discount rate move inversely. Raising the required rate of return discounts each future cash flow more heavily, lowering their present value and thus the estimated stock value. The discount rate does not change the projected cash flows themselves (so 'unchanged' is wrong), and value falls rather than rises, so the two 'increase' options misstate the inverse relationship.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-value-5", "subjectId": "vehicles", "componentId": "veh-equity-value", "subtopic": "Technical analysis", "stem": "An IAR tells a client that because markets are weak-form efficient, one particular research method cannot be expected to consistently produce excess returns, since the information it relies on is already fully reflected in current prices. The method the IAR is most directly describing as ineffective under weak-form efficiency is:", "choices": ["Fundamental analysis, which relies on public financial statements", "Analysis of private, non-public inside information", "Technical analysis, which relies on historical price and volume data", "Discounted cash flow analysis of future dividends"], "answerIndex": 2, "explanation": "Weak-form efficiency holds that current prices already reflect all past price and volume information, which specifically undercuts technical analysis - the method built on historical price and volume patterns. Fundamental analysis (including DCF/DDM) relies on public financial data and is only undercut at the semi-strong form, while analysis of non-public information relates to strong-form efficiency and insider trading concerns, not weak-form.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-offering-1", "subjectId": "vehicles", "componentId": "veh-offering", "subtopic": "Initial public offering (IPO)", "stem": "A privately held technology company sells shares of its common stock to public investors for the first time, after which its stock begins trading on a national exchange. This transaction is best described as a:", "choices": ["Private placement under Regulation D", "Secondary offering", "Initial public offering", "Secondary market transaction"], "answerIndex": 2, "explanation": "When a company sells stock to the public for the first time and becomes publicly traded, that is an initial public offering (IPO) — a primary offering in which the issuer receives the proceeds. A secondary offering is a registered resale of already-outstanding shares by existing holders, not a company's first sale. A private placement (Reg D) is an exempt, non-public sale, which contradicts 'sells to public investors.' A secondary market transaction is ordinary investor-to-investor trading, not the issuer's initial distribution.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-offering-2", "subjectId": "vehicles", "componentId": "veh-offering", "subtopic": "Secondary offering", "stem": "Founders and early venture investors of an established public company register and sell 4 million of their personally owned, already-outstanding shares to the public. Which statement about this offering is CORRECT?", "choices": ["The issuing company receives the sale proceeds and can use them for operations", "Existing shareholders are diluted because 4 million new shares are created", "It is a secondary offering, and the selling shareholders — not the issuer — receive the proceeds", "It must be conducted as an exempt private placement because insiders are selling"], "answerIndex": 2, "explanation": "A sale of already-outstanding shares by existing large holders is a true secondary offering, and the proceeds go to those selling shareholders, not to the issuer. Because no new shares are created, total shares outstanding are unchanged, so there is no dilution — eliminating the first two choices. The transaction is a registered public distribution requiring a prospectus, not a private placement, so the last choice is wrong.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-offering-3", "subjectId": "vehicles", "componentId": "veh-offering", "subtopic": "SPAC / blind pools / blank check", "stem": "An IAR is reviewing a newly IPO'd company that has no operations or revenue; it exists solely to raise cash into a trust account and acquire an as-yet-unidentified private business within roughly 24 months, returning investors' money if no acquisition is completed. This entity is most accurately characterized as a:", "choices": ["Real estate investment trust (REIT)", "Closed-end management investment company", "Follow-on primary offering by an operating company", "Special purpose acquisition company (blank-check / blind pool)"], "answerIndex": 3, "explanation": "A shell that IPOs with no operations, holds cash in trust, and seeks an unidentified target within a set window is a SPAC — a blank-check, blind-pool company. A REIT owns income-producing real estate, and a closed-end fund invests in a portfolio of securities; neither is a shell hunting for a single acquisition. A follow-on primary offering is a sale of new shares by an existing OPERATING company, which contradicts 'no operations.'", "difficulty": "easy", "source": "bank"},
  {"id": "veh-offering-4", "subjectId": "vehicles", "componentId": "veh-offering", "subtopic": "Initial public offering (IPO)", "stem": "A company completed its IPO two years ago at $20 per share. It now conducts a registered offering of 5 million newly issued shares at a public offering price of $30, from which the underwriters retain a spread and remit $27.90 per share to the company. Which statement is TRUE?", "choices": ["Because the SEC declared the registration effective, it has approved the offering as a suitable investment", "The $2.10 per-share underwriting spread is paid by the company in addition to the offering proceeds it keeps", "This is a secondary offering, so the selling shareholders receive the $27.90 per share", "This is a follow-on primary offering; the issuer receives about $139.5 million and existing shareholders are diluted"], "answerIndex": 3, "explanation": "Selling NEW shares after the IPO is a follow-on PRIMARY offering: the issuer receives the proceeds (5,000,000 x $27.90 = $139.5 million) and, because the share count rises, existing shareholders are diluted. It is not a secondary offering, which involves resale of outstanding shares by existing holders. The $2.10 spread is the difference between the $30 POP and the $27.90 net — it is deducted from the POP, not an extra charge on top of proceeds. And SEC effectiveness means the disclosure was cleared, never that the SEC approved or endorsed the security.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-pooled-types-1", "subjectId": "vehicles", "componentId": "veh-pooled-types", "subtopic": "Mutual funds (open-end vs. closed-end)", "stem": "Which type of investment company continuously issues new shares that are redeemable at net asset value and does not trade on a secondary exchange?", "choices": ["A closed-end management company", "An exchange-traded fund", "A unit investment trust", "An open-end management company (mutual fund)"], "answerIndex": 3, "explanation": "An open-end management company (mutual fund) continuously offers new shares and redeems them at NAV; it does not trade on an exchange. A closed-end fund issues a fixed number of shares that trade on an exchange at a market price. A UIT issues redeemable units but holds a fixed portfolio and is not a management company. An ETF, though often organized as an open-end fund, is defined here by exchange trading, which the stem excludes.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-pooled-types-2", "subjectId": "vehicles", "componentId": "veh-pooled-types", "subtopic": "Mutual funds (open-end vs. closed-end)", "stem": "A closed-end fund has a net asset value of $20.00 per share, but its shares are currently trading at $18.00 on the exchange. This situation is best described as the fund trading at a:", "choices": ["Redemption fee of $2.00", "Premium of 10%", "Front-end load of 10%", "Discount of 10%"], "answerIndex": 3, "explanation": "Because the market price ($18) is below NAV ($20), the fund trades at a discount; the discount is ($20 - $18)/$20 = 10%. A premium would require the price to exceed NAV. Closed-end funds trade at market-determined prices, so the gap is not a sales load or redemption fee - those concepts apply to load mutual funds, not to secondary-market pricing of closed-end shares.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-pooled-types-3", "subjectId": "vehicles", "componentId": "veh-pooled-types", "subtopic": "Unit investment trusts (UITs)", "stem": "Which statement accurately distinguishes a unit investment trust (UIT) from an open-end mutual fund?", "choices": ["A UIT is actively managed by a portfolio manager, while a mutual fund is not", "A UIT has a fixed, largely unmanaged portfolio and a stated termination date, and it has no board of directors or investment adviser", "A UIT trades intraday on a national exchange, while a mutual fund is priced only once per day", "A UIT may not issue redeemable securities, while a mutual fund must"], "answerIndex": 1, "explanation": "A UIT holds a fixed portfolio that is generally not actively managed, has a set termination date, and operates without a board of directors or an investment adviser - key contrasts with an actively managed mutual fund. The first choice reverses the facts. UITs do not trade intraday on an exchange like ETFs. Both UITs and mutual funds issue redeemable securities, so the last choice is wrong.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-pooled-types-4", "subjectId": "vehicles", "componentId": "veh-pooled-types", "subtopic": "Exchange-traded funds (ETFs)", "stem": "An IAR is explaining exchange-traded funds to a client. Which feature is characteristic of a typical ETF but NOT of a traditional open-end mutual fund?", "choices": ["Its portfolio may include a diversified basket of equity securities", "It distributes at least 90% of its taxable income to avoid entity-level tax", "Its shares are redeemed directly with the fund at the next computed NAV", "It can be bought and sold at market prices throughout the trading day and may be sold short or bought on margin"], "answerIndex": 3, "explanation": "ETFs trade intraday on an exchange at market prices and, like stocks, can generally be sold short and bought on margin - features a mutual fund lacks, since mutual fund shares transact only at the once-daily forward-priced NAV. A diversified equity basket is common to both. Direct redemption at next-computed NAV describes a mutual fund (retail ETF investors sell in the market; only authorized participants redeem creation units). The 90% distribution test describes REITs, not ETFs generally.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-pooled-types-5", "subjectId": "vehicles", "componentId": "veh-pooled-types", "subtopic": "Real estate investment trusts (REITs, listed and non-traded)", "stem": "An IAR is comparing a listed equity REIT with a non-traded REIT for an income-oriented client. Which statement is most accurate?", "choices": ["Both are registered investment companies under the Investment Company Act of 1940 and pass through operating losses to shareholders", "The non-traded REIT is generally more liquid because investors can redeem shares daily at a market price", "The non-traded REIT typically carries higher upfront fees, is illiquid with limited redemption programs, and relies on periodic appraisal-based valuations rather than continuous market pricing", "Dividends from both REITs are automatically treated as qualified dividends taxed at long-term capital gains rates"], "answerIndex": 2, "explanation": "Non-traded REITs are illiquid, impose high upfront sales loads and fees, offer only limited redemption programs, and are valued using periodic appraisals rather than daily market prices - unlike a liquid, exchange-listed REIT. REITs are not registered investment companies and do not pass through losses (that describes limited partnerships), so the first choice is wrong. The second reverses the liquidity facts. Most REIT income distributions are ordinary income, not qualified dividends, making the last choice wrong.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-pooled-types-6", "subjectId": "vehicles", "componentId": "veh-pooled-types", "subtopic": "Private funds (hedge funds, private equity, venture capital)", "stem": "A hedge fund is organized to rely on the Section 3(c)(7) exclusion from the Investment Company Act of 1940 and charges a '2 and 20' fee. Which combination of features is consistent with this fund?", "choices": ["It may sell to an unlimited number of qualified purchasers, charges a 2% management fee plus 20% of profits, and typically imposes lock-up periods", "It is limited to 100 accredited investors, charges a 2% front-end load, and offers daily redemption at NAV", "It must register its shares under the Securities Act of 1933 and distribute a statutory prospectus to all retail investors", "It is prohibited from using leverage or short selling and must maintain the diversification required of registered funds"], "answerIndex": 0, "explanation": "A 3(c)(7) fund may sell to an unlimited number of qualified purchasers (generally $5M+ in investments) while remaining excluded from Investment Company Act registration; '2 and 20' means a 2% management fee plus a 20% performance fee (carried interest), and lock-ups are common. The 100-owner limit and accredited-investor standard describe the 3(c)(1) exclusion, not 3(c)(7), and hedge funds do not offer daily NAV redemption. Private funds sell via Regulation D private placements, so no registered public prospectus is required, and they may use leverage and short selling and are not bound by registered-fund diversification rules.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-pooled-char-1", "subjectId": "vehicles", "componentId": "veh-pooled-char", "subtopic": "Pricing (NAV, discount/premium)", "stem": "An investor places an order at 11:00 a.m. to redeem shares of an open-end mutual fund. At what price will the redemption be executed?", "choices": ["The net asset value calculated at the close of the previous business day", "The next net asset value calculated after the order is received", "The market price at the moment the order is entered", "The average of the bid and ask price quoted on the exchange"], "answerIndex": 1, "explanation": "Mutual funds use forward pricing: an order receives the next NAV computed after the order is received, which for a fund that prices once daily is that day's closing NAV. The previous day's NAV (choice A) is stale and never used for execution. Open-end funds do not trade intraday on an exchange, so there is no live market price or bid/ask spread (choices C and D) - those apply to closed-end funds and ETFs.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-pooled-char-2", "subjectId": "vehicles", "componentId": "veh-pooled-char", "subtopic": "Pricing (NAV, discount/premium)", "stem": "Which statement best describes why a closed-end fund can trade at a price different from its net asset value while an open-end fund cannot?", "choices": ["Closed-end funds do not calculate NAV, so any market price is arbitrary", "Open-end funds are prohibited by the SEC from disclosing their NAV to the public", "Closed-end funds are not required to hold marketable securities, making NAV impossible to determine", "Closed-end fund shares trade on an exchange at prices set by supply and demand, whereas open-end shares are issued and redeemed directly with the fund at NAV"], "answerIndex": 3, "explanation": "A closed-end fund issues a fixed number of shares that then trade in the secondary market, so supply and demand can push the price to a premium or discount versus NAV. An open-end fund continuously issues and redeems its own shares directly at NAV, so it always transacts at NAV (plus any load). Closed-end funds do calculate NAV (A is false), open-end funds publish NAV daily (C is false), and closed-end funds do hold marketable securities with a determinable NAV (D is false).", "difficulty": "medium", "source": "bank"},
  {"id": "veh-pooled-char-3", "subjectId": "vehicles", "componentId": "veh-pooled-char", "subtopic": "Share classes", "stem": "A client intends to invest a large sum in a mutual fund and hold it for at least 15 years. An IAR is comparing share classes. Which recommendation is generally most cost-effective, and why?", "choices": ["Class C shares, because the absence of a front-end load maximizes the amount invested immediately", "Class B shares, because the contingent deferred sales charge will have declined to zero by the time the client sells", "Class A shares, because breakpoint discounts on the front-end load and lower ongoing 12b-1 fees reduce total cost over a long horizon", "Class A shares, because they are the only class that pays dividends to shareholders"], "answerIndex": 2, "explanation": "For a large, long-term investment, Class A shares are usually cheapest: the sizable purchase qualifies for breakpoint discounts on the front-end load, and Class A carries the lowest ongoing 12b-1 fees, which compound favorably over 15 years. Class C's high level 12b-1 fee (A) makes it expensive over long holding periods despite no front-end load. Class B (B) also carries higher 12b-1 fees than A and typically converts to A anyway. All share classes pay the same distributions (D is false).", "difficulty": "medium", "source": "bank"},
  {"id": "veh-pooled-char-4", "subjectId": "vehicles", "componentId": "veh-pooled-char", "subtopic": "Fee structures (load vs. no-load, CDSC, 12b-1 fees, breakpoints)", "stem": "Under FINRA rules, what is the maximum annual asset-based 12b-1 distribution fee a fund may charge, and how does it affect the fund's ability to call itself 'no-load'?", "choices": ["0.25%; and a fund may call itself no-load only if it charges no 12b-1 fee at all", "0.75% for distribution plus up to 0.25% for service; a fund may not be called 'no-load' if its combined 12b-1 and service fees exceed 0.25%", "1.00% for distribution alone; the no-load designation depends only on the absence of a front-end load", "There is no cap on 12b-1 fees; the no-load label depends solely on the absence of a CDSC"], "answerIndex": 1, "explanation": "FINRA caps the asset-based 12b-1 distribution fee at 0.75% of average net assets per year, plus a separate service fee of up to 0.25% (1.00% combined). A fund may only be marketed as 'no-load' if its 12b-1 plus service fees do not exceed 0.25% - the label is not solely about the absence of a front-end load (C) or CDSC (D). Choice A understates the distribution cap and wrongly requires a zero 12b-1 fee for the no-load label.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-pooled-char-5", "subjectId": "vehicles", "componentId": "veh-pooled-char", "subtopic": "Tax implications", "stem": "A mutual fund distributes a long-term capital gains distribution to an investor who purchased the fund shares only two months ago and has elected to reinvest all distributions. How is this distribution treated for tax purposes?", "choices": ["It is tax-deferred because the investor reinvested rather than received cash", "It is taxed as a short-term gain because the investor has held the fund shares for only two months", "It is taxable in the current year at long-term capital gains rates, based on the fund's holding period of the underlying securities", "It is not taxable until the investor eventually sells the fund shares"], "answerIndex": 2, "explanation": "A capital gains distribution retains its character (long-term) based on how long the FUND held the underlying securities, not how long the investor held the fund shares, so it is taxed at long-term rates even though the investor bought only two months ago. It is taxable in the year received; reinvesting does not defer the tax (choices A and D are wrong). The investor's short two-month holding period does not convert it to a short-term gain (choice B is wrong).", "difficulty": "hard", "source": "bank"},
  {"id": "veh-pooled-char-6", "subjectId": "vehicles", "componentId": "veh-pooled-char", "subtopic": "Liquidity", "stem": "An investor needs a pooled investment from which shares can be sold back for cash at a known price every business day. Which vehicle and feature best meet this liquidity need?", "choices": ["A closed-end fund, because its exchange listing guarantees a buyer at NAV at any time", "An open-end mutual fund, because it redeems its redeemable shares daily at net asset value", "A unit investment trust, because its fixed portfolio is continuously repriced intraday", "A hedge fund, because private placements offer immediate redemption on demand"], "answerIndex": 1, "explanation": "An open-end mutual fund provides daily liquidity by redeeming its redeemable shares directly at that day's NAV, meeting the need to sell back at a known (forward-priced) value each business day. A closed-end fund's exchange price is set by supply and demand and may be at a discount - it does not guarantee redemption at NAV (A). UITs redeem units with the trust but do not offer continuous intraday NAV repricing as described (C), and hedge funds are illiquid, typically with lock-ups and limited redemption windows (D).", "difficulty": "easy", "source": "bank"},
  {"id": "veh-deriv-types-1", "subjectId": "vehicles", "componentId": "veh-deriv-types", "subtopic": "Options and warrants (definitions)", "stem": "Which statement best describes the fundamental difference between an option and a futures contract?", "choices": ["An option obligates both parties to transact, while a futures contract obligates only the seller", "The holder of an option has the right but not the obligation to transact, whereas a futures contract obligates both parties to perform", "Both options and futures give the holder a right but no obligation to transact", "A futures contract gives the buyer a right to walk away, while an option binds the buyer to purchase"], "answerIndex": 1, "explanation": "The defining distinction is right versus obligation: an option holder may choose whether to exercise (a right), while a futures contract legally binds BOTH the buyer and the seller to transact at the agreed price. Choice A reverses the concept and misstates the option; choice C is wrong because futures do not confer an optional right; choice D inverts the mechanics entirely, since it is the option buyer, not the futures buyer, who can walk away by letting the contract lapse.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-deriv-types-2", "subjectId": "vehicles", "componentId": "veh-deriv-types", "subtopic": "Options and warrants (definitions)", "stem": "An IAR is explaining warrants to a client who already understands listed call options. Which of the following is an accurate distinction between a warrant and a listed call option?", "choices": ["A warrant is exercised against another investor and creates no new shares, while a call option is issued by the corporation", "A warrant is a short-term instrument typically expiring within nine months, while a call option commonly lasts several years", "A warrant is issued by the corporation and, when exercised, results in newly issued shares that dilute existing shareholders, while a listed call option does not create new shares", "A warrant gives the holder voting rights and dividends immediately upon purchase, while a call option does not"], "answerIndex": 2, "explanation": "Warrants are issued by the corporation itself, usually with a long life and often attached to bonds or preferred stock as a sweetener; exercising them causes the company to issue new shares, diluting existing owners. A listed call option is written by another market participant and does not create new shares. Choice A reverses the issuer and dilution facts; choice B swaps the typical maturities (warrants are long-term, options short-term); choice D is wrong because a warrant holder gets no dividends or voting rights until the warrant is exercised into stock.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-deriv-types-3", "subjectId": "vehicles", "componentId": "veh-deriv-types", "subtopic": "Options and warrants (definitions)", "stem": "A client purchases one call option on XYZ stock with a strike price of $50, paying a premium of $3 per share. At expiration, XYZ is trading at $58. Ignoring commissions, what is the client's intrinsic value per share and net profit per share at expiration?", "choices": ["Intrinsic value of $8 and net profit of $5 per share", "Intrinsic value of $5 and net profit of $8 per share", "Intrinsic value of $8 and net profit of $8 per share", "Intrinsic value of $3 and net profit of $5 per share"], "answerIndex": 0, "explanation": "A call's intrinsic value equals market price minus strike, so $58 - $50 = $8 per share. The net profit subtracts the $3 premium paid: $8 - $3 = $5 per share. Choice B swaps the two figures; choice C ignores the premium cost entirely; choice D incorrectly uses the premium as the intrinsic value.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-deriv-types-4", "subjectId": "vehicles", "componentId": "veh-deriv-types", "subtopic": "Futures and forward contracts (definitions)", "stem": "A commodities producer enters a privately negotiated agreement directly with a buyer to deliver a specific, non-standard quantity of product at a set price in nine months, with no exchange or clearinghouse involved. Compared with an exchange-traded futures contract, this arrangement is best characterized as having which set of features?", "choices": ["Standardized terms, daily mark-to-market, and minimal counterparty risk", "Customized terms, no daily mark-to-market, and greater counterparty (credit) risk", "Customized terms, guaranteed by a clearinghouse, and high liquidity", "Standardized terms, exchange listing, and an optional right to decline delivery"], "answerIndex": 1, "explanation": "This describes a forward contract: a private, customizable OTC agreement settled at maturity with no clearinghouse, which means it lacks daily mark-to-market and carries greater counterparty (default) risk than a futures contract. Choice A describes a futures contract, not a forward; choice C wrongly attaches a clearinghouse guarantee and high liquidity to a private forward; choice D is wrong because forwards are neither standardized nor optional, since both parties are obligated to perform.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-deriv-char-1", "subjectId": "vehicles", "componentId": "veh-deriv-char", "subtopic": "Costs, benefits, and risks of derivative securities", "stem": "An investor writes (sells) one uncovered (naked) call option on a stock and receives a premium. Which statement best describes this investor's risk and reward profile?", "choices": ["Maximum gain is the premium received and maximum loss is theoretically unlimited", "Maximum loss is limited to the premium received and gain is unlimited", "Maximum gain is unlimited and maximum loss is the premium received", "Both maximum gain and maximum loss are limited to the strike price"], "answerIndex": 0, "explanation": "A naked call writer's maximum gain is the premium collected, which happens if the option expires worthless. Because a stock's price has no ceiling, the writer may have to deliver shares bought at ever-higher prices, so the maximum loss is theoretically unlimited. Choices describing limited loss confuse the writer with the option BUYER, whose loss is capped at the premium; the writer's position is the mirror image, with limited gain and open-ended loss.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-deriv-char-2", "subjectId": "vehicles", "componentId": "veh-deriv-char", "subtopic": "Costs, benefits, and risks of derivative securities", "stem": "A client holds 500 shares of a stock she has owned for years and is worried about a possible short-term decline but does not want to sell. An IAR wants to hedge this downside while keeping the client's upside participation. Which derivative strategy most directly accomplishes this, and what is its primary cost?", "choices": ["Selling the stock short; the cost is margin interest on the borrowed shares", "Buying call options; the cost is the obligation to purchase additional shares", "Buying protective puts; the cost is the premium paid, which reduces net return if the stock does not fall", "Writing covered calls; the cost is unlimited downside risk if the stock falls"], "answerIndex": 2, "explanation": "Buying protective (long) puts insures the existing long stock position: the put gains value if the stock falls, capping downside, while the client keeps unlimited upside on the shares. The trade-off is the premium paid, a drag on returns if the stock stays flat or rises. Covered calls generate income but cap upside and do not protect much downside; shorting the stock would offset the very position she wants to keep; buying calls adds upside exposure rather than hedging a decline.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-deriv-char-3", "subjectId": "vehicles", "componentId": "veh-deriv-char", "subtopic": "Costs, benefits, and risks of derivative securities", "stem": "An IAR is comparing an exchange-traded (listed) index option with a customized over-the-counter (OTC) forward contract for a client. Which statement correctly identifies a key risk difference between the two instruments?", "choices": ["The listed option carries greater counterparty risk because exchanges do not guarantee performance", "Both instruments are guaranteed by the OCC, so counterparty risk is identical", "The OTC forward eliminates market risk because its price is fixed in advance", "The OTC forward carries greater counterparty (credit) risk because it is privately negotiated and not clearinghouse-guaranteed"], "answerIndex": 3, "explanation": "OTC forwards are privately negotiated between two parties and are not backstopped by a clearinghouse, so each side bears the credit risk that the other may default. Listed options are standardized and guaranteed by the Options Clearing Corporation (OCC), which sharply reduces counterparty risk, so the first and third choices are backwards or false. Fixing a forward's price locks in a delivery price but does not eliminate market risk — the party is still exposed if the market moves against the agreed price.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-alts-1", "subjectId": "vehicles", "componentId": "veh-alts", "subtopic": "Limited partnerships", "stem": "In a typical real estate limited partnership, which statement best describes the liability of the participants?", "choices": ["Both the general partner and the limited partners have liability limited to their capital contributions", "The general partner has unlimited personal liability, while limited partners can lose no more than their invested capital", "Limited partners have unlimited liability because they receive flow-through losses, while the general partner's liability is capped", "All partners share joint and several unlimited liability for partnership debts"], "answerIndex": 1, "explanation": "In a limited partnership, the general partner actively manages the venture and bears unlimited personal liability, while limited partners are passive investors whose potential loss is limited to the amount they invested (plus any recourse debt they agreed to assume). The first choice wrongly extends limited liability to the GP. The third choice inverts the structure — receiving flow-through losses does not create unlimited liability for limited partners. The fourth choice ignores the defining feature that limits the limited partners' exposure.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-alts-2", "subjectId": "vehicles", "componentId": "veh-alts", "subtopic": "Exchange-traded notes (ETNs)", "stem": "An investor is comparing an exchange-traded note (ETN) with an exchange-traded fund (ETF) that track the same index. Which statement about the ETN is correct?", "choices": ["The ETN holds a portfolio of the index's underlying securities, eliminating issuer credit risk", "The ETN is an unsecured debt obligation of the issuer, so the investor bears the issuer's credit risk", "The ETN guarantees return of principal at maturity regardless of index performance", "The ETN cannot be sold until its stated maturity date because it does not trade on an exchange"], "answerIndex": 1, "explanation": "An ETN is a senior unsecured debt obligation of the issuing bank whose return is linked to an index; if the issuer becomes insolvent, the investor can lose value regardless of how the index performed, so credit risk is the key distinction from an ETF. The first choice describes an ETF, which actually holds securities — an ETN holds none. The third choice is wrong because ETNs are not principal-protected and follow the (possibly declining) index. The fourth choice is false because ETNs trade intraday on an exchange, like stocks.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-alts-3", "subjectId": "vehicles", "componentId": "veh-alts", "subtopic": "Leveraged funds", "stem": "A broad market index rises 10% on Monday and then falls 10% on Tuesday (from Monday's closing level). Ignoring fees, what is the approximate two-day cumulative return of a 2x daily leveraged fund tracking that index, and what does the result illustrate?", "choices": ["−4%, illustrating that daily resetting and compounding cause deviation from twice the index's cumulative return", "−2%, matching exactly twice the index's two-day cumulative return", "−20%, illustrating that leverage doubles every daily loss with no offsetting gains", "+0%, showing that leveraged funds exactly track twice the index over any period"], "answerIndex": 0, "explanation": "The 2x fund gains 20% Monday (1.00 → 1.20) and loses 20% Tuesday (1.20 × 0.80 = 0.96), a −4% cumulative result. The index itself moved 1.10 × 0.90 = 0.99, or −1%, so twice the index's cumulative move would be roughly −2% — but the fund lost more because of daily rebalancing and compounding (volatility decay). The +0% choice ignores compounding, the −2% choice wrongly assumes the 2x multiple applies to the cumulative return, and −20% miscounts by ignoring Monday's gain.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-alts-4", "subjectId": "vehicles", "componentId": "veh-alts", "subtopic": "Inverse funds", "stem": "An IAR is meeting with a risk-averse client who wants a simple, low-maintenance holding to mirror the long-term downward trend the client expects in a stock index over the next several years. The client asks about buying and holding a -2x daily inverse ETF. What is the most appropriate response?", "choices": ["The inverse ETF is well suited to this goal because it will deliver twice the index's inverse return over the multi-year period", "The inverse ETF is designed to achieve its stated objective on a daily basis; because of daily resetting and compounding, holding it for years can produce results very different from twice the index's inverse move, making it generally unsuitable for a long-term, buy-and-hold objective", "The inverse ETF eliminates market risk entirely and is therefore ideal for a risk-averse client", "The inverse ETF carries the issuer's credit risk like an ETN, so it should be avoided only for that reason"], "answerIndex": 1, "explanation": "Inverse (and leveraged) funds reset daily, so their stated multiple applies to one-day returns; over long horizons, compounding and volatility decay cause returns to diverge substantially from the simple multiple of the index's cumulative move, making them poor buy-and-hold instruments. The first choice repeats the common misconception that the daily multiple holds over long periods. The third overstates their safety — they are volatile trading tools, not risk-free. The fourth is inaccurate because a fund holding assets/derivatives is not primarily an issuer-credit instrument the way an unsecured ETN is.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-alts-5", "subjectId": "vehicles", "componentId": "veh-alts", "subtopic": "Structured products", "stem": "A client is considering a 'principal-protected' structured note issued by a large bank, linked to the performance of an equity index. Which of the following is the most important risk the IAR should disclose?", "choices": ["The note is federally insured, so the only risk is that returns may lag inflation", "Because the note combines a debt component with an embedded derivative, the 'principal protection' depends on the issuing bank's solvency — the client bears issuer credit risk and the note may be illiquid", "Structured notes trade on national exchanges with deep liquidity, so the client can always exit at net asset value", "The embedded option guarantees the client will outperform the underlying index in all market conditions"], "answerIndex": 1, "explanation": "A structured note is typically a zero-coupon/debt component plus an embedded derivative, all issued by a financial institution; the 'protection' is only a contractual promise backed by that issuer, so credit risk is paramount and these products are usually illiquid with thin or no secondary markets. The first choice is wrong because structured notes are not FDIC-insured. The third choice misstates their liquidity — secondary markets are limited. The fourth choice is false because embedded options usually cap or condition the upside rather than guaranteeing outperformance.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-insurance-1", "subjectId": "vehicles", "componentId": "veh-insurance", "subtopic": "Annuities (fixed, variable, equity indexed)", "stem": "An IAR is reviewing a client's insurance-based holdings and must identify which products are legally considered securities requiring prospectus delivery. Which of the following is a security under federal law?", "choices": ["A fixed annuity guaranteeing a 3% minimum credited rate", "A whole life insurance policy with a guaranteed cash value", "An equity indexed annuity crediting interest tied to the S&P 500 with a 1% floor", "A variable annuity whose value depends on separate-account subaccounts"], "answerIndex": 3, "explanation": "A variable annuity places premiums in a separate account of securities and shifts investment risk to the owner, so it is defined as a security and must be sold with a prospectus and a securities license. Fixed annuities and whole life are backed by the insurer's general account with guarantees, making them insurance products. Equity indexed annuities, despite their index linkage, retain a guaranteed floor in the general account and are treated as insurance products, not securities.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-insurance-2", "subjectId": "vehicles", "componentId": "veh-insurance", "subtopic": "Annuities (fixed, variable, equity indexed)", "stem": "A 55-year-old client contributed $60,000 of after-tax money to a non-qualified variable annuity that has grown to $95,000. She takes a $20,000 withdrawal. Ignoring any surrender charges, how is this withdrawal taxed?", "choices": ["$20,000 is taxed as ordinary income plus a 10% penalty on that amount", "$5,000 is taxed as ordinary income and $15,000 is a tax-free return of principal", "$20,000 is taxed as long-term capital gains with no penalty", "The entire $20,000 is a tax-free return of principal"], "answerIndex": 0, "explanation": "Non-qualified annuities use LIFO, so earnings are deemed withdrawn first. The contract has $35,000 of earnings ($95,000 - $60,000), so the entire $20,000 comes from earnings and is fully taxed as ordinary income; because she is under 59 1/2, a 10% penalty also applies to that taxable amount. Annuity gains never receive capital-gains treatment, and principal is not reached until all earnings are exhausted, so the partial-return and tax-free answers are wrong.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-insurance-3", "subjectId": "vehicles", "componentId": "veh-insurance", "subtopic": "Annuities (fixed, variable, equity indexed)", "stem": "A client purchases an equity indexed annuity with an 80% participation rate, an 8% cap, and a 2% guaranteed minimum floor. In a year when the linked index returns 15%, approximately what interest will be credited to the contract for that year?", "choices": ["12%, the participation-adjusted return", "2%, the guaranteed minimum floor", "8%, the cap", "15%, the full index return"], "answerIndex": 2, "explanation": "The participation rate is applied first: 80% of 15% equals 12%. However, the cap limits credited interest to a maximum of 8%, so the credited rate is 8%. The floor of 2% only matters when the index performs poorly, and the full 15% is never credited because both the participation rate and cap reduce it. This illustrates how caps and participation rates constrain an indexed annuity's upside.", "difficulty": "hard", "source": "bank"},
  {"id": "veh-insurance-4", "subjectId": "vehicles", "componentId": "veh-insurance", "subtopic": "Life insurance (whole, term, universal, variable)", "stem": "A 30-year-old with a growing family wants the maximum immediate death-benefit coverage for the lowest initial premium, and has no interest in building cash value inside the policy. Which policy best fits this objective?", "choices": ["Term life insurance", "Variable life insurance", "Universal life insurance", "Whole life insurance"], "answerIndex": 0, "explanation": "Term life is pure insurance protection with no cash value and the lowest initial premium, providing the most death benefit per dollar for a stated period, matching the client's goal. Whole and universal life cost more because they build cash value, and variable life is a security whose cash value is invested in subaccounts. Because the client explicitly does not want cash value and wants the lowest initial cost, term is the clear fit.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-insurance-5", "subjectId": "vehicles", "componentId": "veh-insurance", "subtopic": "Life insurance (whole, term, universal, variable)", "stem": "An IAR is explaining variable life insurance to a client. Which statement most accurately describes how a variable life policy works?", "choices": ["It provides temporary coverage for a set term with no cash value component", "Premiums and the death benefit are flexible, and cash value earns a current interest rate set by the insurer", "The death benefit and cash value are both fully guaranteed by the insurer's general account", "Cash value is invested in separate-account subaccounts, so cash value and death benefit fluctuate, though a guaranteed minimum death benefit typically applies"], "answerIndex": 3, "explanation": "Variable life invests cash value in separate-account subaccounts, so both cash value and death benefit vary with investment performance, though policies usually guarantee a minimum death benefit; because value depends on securities, it is a security requiring a prospectus and securities license. The flexible-premium/current-interest description fits universal life, the fully-guaranteed description fits whole life, and the temporary/no-cash-value description fits term life.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-other-1", "subjectId": "vehicles", "componentId": "veh-other", "subtopic": "Commodities and precious metals", "stem": "A client asks her investment adviser representative about adding gold and silver bullion to her portfolio as a long-term holding. Which of the following is the MOST accurate statement the IAR could make about direct ownership of physical precious metals?", "choices": ["They generate a modest but steady stream of dividend income that rises with inflation", "They produce no income and incur storage and insurance costs, but can serve as an inflation hedge and diversifier", "They are securities regulated by the SEC under the Uniform Securities Act", "They are guaranteed against loss of principal because metals have intrinsic value"], "answerIndex": 1, "explanation": "Physical precious metals produce no income (no dividends or interest) and carry ongoing storage and insurance costs; their appeal is inflation hedging and low correlation with financial assets, which aids diversification. They pay no dividends, so the first choice is wrong. Physical bullion held directly is not a security and is not SEC/Uniform Securities Act regulated, eliminating the third choice. Metals are volatile with no principal guarantee, so the last choice is false.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-other-2", "subjectId": "vehicles", "componentId": "veh-other", "subtopic": "Commodities and precious metals", "stem": "Which regulatory body has primary jurisdiction over standard exchange-traded commodity futures contracts, and how are such contracts generally treated under the Uniform Securities Act?", "choices": ["The Federal Reserve has jurisdiction, and futures contracts are treated as securities", "The SEC has jurisdiction, and futures contracts are treated as securities", "The CFTC (with the NFA) has jurisdiction, and standard futures contracts are generally NOT securities", "FINRA has jurisdiction, and futures contracts are treated as exempt securities"], "answerIndex": 2, "explanation": "Commodity futures are regulated primarily by the Commodity Futures Trading Commission (CFTC), with the National Futures Association (NFA) as the self-regulatory organization; standard futures contracts are generally not 'securities' under the Uniform Securities Act. The SEC and FINRA regulate securities markets, not standard commodity futures, so those choices are wrong. The Federal Reserve conducts monetary policy and bank supervision, not futures regulation. Because futures are not securities, treating them as 'exempt securities' is also incorrect.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-other-3", "subjectId": "vehicles", "componentId": "veh-other", "subtopic": "Digital assets", "stem": "A startup sells digital tokens to the public to raise capital for a platform it promises to build, telling buyers they can expect profits as the company develops and markets the network. Under the Howey test, this token offering is MOST likely to be characterized as:", "choices": ["A security, because investors provide money in a common enterprise expecting profits from the efforts of others", "A commodity, because all digital assets are treated the same as Bitcoin", "A currency exempt from securities regulation because it can be used to make payments", "A collectible, because tokens have no issuer standing behind them"], "answerIndex": 0, "explanation": "The Howey test finds an investment contract (a security) when there is an investment of money in a common enterprise with an expectation of profits derived predominantly from the efforts of others - exactly the fact pattern of a token sold to fund a venture the promoters will build. Not all digital assets are commodities; Bitcoin is generally viewed as a commodity, but the Howey analysis is applied token-by-token, so the second choice is wrong. Labeling it a 'currency' or 'collectible' does not exempt an offering that meets Howey, making the remaining choices incorrect.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-other-4", "subjectId": "vehicles", "componentId": "veh-other", "subtopic": "Digital assets", "stem": "An IAR is evaluating a recommendation to place a meaningful portion of a risk-averse, income-focused retiree's assets into a cryptocurrency held at an online crypto exchange. Which statement reflects the BEST application of the IAR's obligations?", "choices": ["Because cryptocurrency may not be a security, the IAR owes no suitability or disclosure duties for the recommendation", "The recommendation is appropriate because crypto held at an exchange is protected by SIPC up to applicable limits", "The IAR remains a fiduciary and must weigh the asset's volatility, illiquidity, lack of FDIC/SIPC coverage, and the client's low risk tolerance and income needs", "Crypto is guaranteed to hedge inflation, so a large allocation is suitable for any retiree"], "answerIndex": 2, "explanation": "An investment adviser is a fiduciary and owes suitability, reasonable-basis, and full disclosure duties even when the recommended asset is not itself a security; the adviser must weigh crypto's extreme volatility, illiquidity, custody risk, and absence of FDIC/SIPC coverage against a conservative retiree's low risk tolerance and income needs - so a meaningful allocation here is generally unsuitable. The first choice wrongly abandons fiduciary duty; the second is false because crypto at an exchange is not SIPC-protected; the fourth overstates crypto as a 'guaranteed' inflation hedge, which it is not.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-client-type-1", "subjectId": "recommendations", "componentId": "rec-client-type", "subtopic": "Individual, natural person, sole proprietorship", "stem": "An investment adviser representative is opening an account for a client who operates a landscaping business as a sole proprietorship. Which statement best describes the legal and tax status of this client?", "choices": ["The business is a separate legal entity, and the adviser must obtain a corporate resolution before trading", "The owner and the business are the same legal person, and business income is reported on the owner's individual tax return", "The business is a pass-through entity distinct from the owner, filing its own partnership return", "The owner has limited liability for business debts because the account is titled in the business name"], "answerIndex": 1, "explanation": "A sole proprietorship is not a separate legal entity; the owner and the business are one and the same legal person, and business income flows onto the owner's individual return (Schedule C). No corporate resolution exists because there is no corporation, so the first choice is wrong. It does not file a separate partnership return (there is only one owner), and a sole proprietor has unlimited personal liability, so the third and fourth choices are wrong.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-client-type-2", "subjectId": "recommendations", "componentId": "rec-client-type", "subtopic": "Individual, natural person, sole proprietorship", "stem": "Which of the following clients is a natural person rather than a legal person?", "choices": ["An individual investor opening a personal brokerage account in her own name", "An S corporation with one shareholder", "A single-member limited liability company", "A revocable living trust"], "answerIndex": 0, "explanation": "A natural person is a human being; an individual opening an account in her own name is a natural person. A single-member LLC, a trust, and an S corporation are all legal persons or legal arrangements created by law -- they are not natural persons even when only one human is behind them. The exam distinguishes the human individual from entities and arrangements that the law treats as separate.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-client-type-3", "subjectId": "recommendations", "componentId": "rec-client-type", "subtopic": "Business entities (general partnership, limited partnership, LLC, C and S corporations)", "stem": "An IAR is opening an account for a newly formed limited partnership. To determine who is authorized to direct trades and what the account's investment objectives are, the adviser should primarily rely on which of the following?", "choices": ["The partnership agreement, which identifies the general partner's authority and the entity's objectives", "The individual tax returns of each limited partner", "The personal financial profile and risk tolerance of the largest limited partner", "A corporate resolution adopted by the board of directors"], "answerIndex": 0, "explanation": "For a partnership, the partnership agreement is the governing document; it identifies the general partner (who has management authority and unlimited liability) and establishes the entity's authority and objectives. Limited partners generally cannot direct management without risking their limited-liability protection, so relying on a limited partner's personal profile is wrong. A limited partnership has no board of directors and thus no corporate resolution, and individual partners' tax returns do not establish trading authority for the entity account.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-client-type-4", "subjectId": "recommendations", "componentId": "rec-client-type", "subtopic": "Business entities (general partnership, limited partnership, LLC, C and S corporations)", "stem": "A client is deciding whether to structure a new operating business as a C corporation or an S corporation, and asks about the tax consequences. Which statement is correct?", "choices": ["Both C and S corporations pay tax only at the shareholder level, avoiding entity-level tax", "A C corporation is taxed at the entity level and again when dividends are paid, while an S corporation generally passes income through to shareholders", "An S corporation faces double taxation, whereas a C corporation is always a pass-through entity", "Neither entity type may have shareholders who are natural persons"], "answerIndex": 1, "explanation": "A C corporation is taxed at the corporate level, and shareholders are taxed again on dividends -- the classic double taxation. An S corporation is a pass-through: income and losses flow to shareholders and are taxed once on their individual returns. The first choice wrongly denies C-corp entity-level tax, the third choice reverses the two, and the fourth is false because both types are commonly owned by natural persons (indeed S corps must generally have individual U.S. shareholders).", "difficulty": "medium", "source": "bank"},
  {"id": "rec-client-type-5", "subjectId": "recommendations", "componentId": "rec-client-type", "subtopic": "Trusts and estates", "stem": "A trustee engages an investment adviser to manage assets held in an irrevocable trust that pays income to the grantor's spouse for life, with the remainder passing to the grantor's children. Under the Uniform Prudent Investor Act, how should the adviser and trustee approach the portfolio?", "choices": ["Manage the total portfolio prudently, diversify, and balance the interests of the income beneficiary and the remaindermen", "Invest solely to maximize current income, because the income beneficiary's needs always take priority over the remaindermen", "Follow the trustee's personal risk tolerance, since the trustee bears legal responsibility for the account", "Judge each asset in isolation and avoid any holding that is individually volatile"], "answerIndex": 0, "explanation": "UPIA requires prudence measured at the total-portfolio level, presumes diversification, and obligates the fiduciary to balance the competing interests of income beneficiaries and remaindermen (impartiality). Maximizing current income would unfairly favor the life beneficiary over the remaindermen, and evaluating each asset in isolation contradicts UPIA's portfolio-level standard. The trustee's personal risk tolerance is irrelevant -- the trust instrument and applicable law, not the fiduciary's preferences, govern the objectives.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-client-type-6", "subjectId": "recommendations", "componentId": "rec-client-type", "subtopic": "Foundations and charities", "stem": "The board of a tax-exempt private foundation with a perpetual time horizon and a 5% annual grant-making requirement asks an adviser to set an investment objective. Assuming long-run inflation of about 3%, which objective and approach is most appropriate?", "choices": ["Target a total return sufficient to fund roughly 5% annual spending plus preserve purchasing power against ~3% inflation, using a diversified growth-oriented portfolio", "Concentrate in a single high-dividend stock to meet the 5% payout from income alone", "Hold primarily short-term Treasury bills to eliminate volatility, accepting a low nominal return", "Emphasize municipal bonds to shelter the foundation's investment income from taxes"], "answerIndex": 0, "explanation": "A perpetual foundation must fund its spending (about 5%) while preserving inflation-adjusted (real) purchasing power, implying a gross total-return target near 8% achieved through a diversified, growth-oriented portfolio consistent with UPMIFA. Municipal bonds are inappropriate because the foundation is already tax-exempt, so their tax advantage is wasted and typically comes with lower yields. All-T-bills would fail to keep pace with inflation over a perpetual horizon, and concentrating in one stock violates prudent diversification and creates excessive risk.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-profile-1", "subjectId": "recommendations", "componentId": "rec-profile", "subtopic": "Risk tolerance", "stem": "An investment adviser representative is meeting a new client for the first time. Which of the following BEST distinguishes a client's risk tolerance from their risk capacity?", "choices": ["Risk tolerance is the objective financial ability to absorb losses, while risk capacity is the client's emotional willingness to accept volatility", "Risk tolerance is the client's willingness and emotional ability to endure volatility and loss, while risk capacity is the objective financial ability to absorb loss", "Risk tolerance and risk capacity are two terms for the same concept and are used interchangeably", "Risk tolerance applies only to equity investments, while risk capacity applies only to fixed-income investments"], "answerIndex": 1, "explanation": "Risk tolerance is the psychological/emotional willingness to endure volatility and potential loss, whereas risk capacity is the objective financial ability to absorb loss (a function of time horizon, income, net worth, and liquidity). Choice A reverses the two definitions. They are distinct concepts that can conflict, so they are not interchangeable (C), and neither is limited to a single asset class (D).", "difficulty": "easy", "source": "bank"},
  {"id": "rec-profile-2", "subjectId": "recommendations", "componentId": "rec-profile", "subtopic": "Risk tolerance", "stem": "A 34-year-old client tells her IAR that she wants to invest for retirement in about 30 years but becomes extremely anxious and wants to sell whenever her account drops even a few percent. Which statement is MOST accurate about her profile?", "choices": ["Her long time horizon gives her high risk capacity, but her emotional reaction indicates low risk tolerance", "Her anxiety proves she has both low risk capacity and low risk tolerance", "Because she is young, she automatically has high risk tolerance and should be placed in aggressive growth funds", "Her time horizon is irrelevant because risk tolerance alone determines the allocation"], "answerIndex": 0, "explanation": "A 30-year horizon gives her a high capacity to absorb short-term volatility, but her emotional reaction to small declines signals low risk tolerance - the two diverge, which is exactly the reconciliation an adviser must perform. Age alone does not confer high tolerance (C), her financial capacity is actually high not low (B), and time horizon is a critical input that cannot be ignored (D).", "difficulty": "medium", "source": "bank"},
  {"id": "rec-profile-3", "subjectId": "recommendations", "componentId": "rec-profile", "subtopic": "Current and future financial situation (cash flow, balance sheet, existing investments, tax situation, Social Security, pensions)", "stem": "A client in the 35% federal marginal tax bracket is comparing a taxable corporate bond yielding 6.0% with a comparable-quality municipal bond yielding 4.2%. On an after-tax basis, which bond is more attractive and by approximately how much?", "choices": ["The corporate bond, because 6.0% is higher than 4.2%", "The municipal bond; the corporate bond's after-tax yield is only about 3.9%", "They are identical on an after-tax basis", "The corporate bond; its after-tax yield is about 4.2%, equal to the municipal"], "answerIndex": 1, "explanation": "The corporate bond's after-tax yield is 6.0% x (1 - 0.35) = 3.9%, which is below the municipal bond's 4.2% tax-free yield, so the muni is better after tax. Choice A ignores taxes entirely. Choice D miscalculates the after-tax yield (it would be 3.9%, not 4.2%), and the two are not equal (C). This illustrates why the client's tax situation drives suitable fixed-income recommendations.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-profile-4", "subjectId": "recommendations", "componentId": "rec-profile", "subtopic": "Current and future financial situation (cash flow, balance sheet, existing investments, tax situation, Social Security, pensions)", "stem": "An IAR is documenting a client's financial situation. Which statement correctly describes the difference between a balance sheet and a cash flow statement?", "choices": ["A balance sheet measures income versus expenses over a period, while a cash flow statement shows net worth at a point in time", "A balance sheet shows assets minus liabilities at a point in time, while a cash flow statement shows income minus expenses over a period", "Both documents measure the same thing but a balance sheet uses monthly figures", "A cash flow statement lists the client's investment holdings, while a balance sheet lists only the client's goals"], "answerIndex": 1, "explanation": "A balance sheet is a point-in-time snapshot of assets minus liabilities (net worth), while a cash flow statement measures income minus expenses over a period (the surplus available to invest). Choice A reverses the definitions. They do not measure the same thing (C), and neither is simply a list of goals (D). Both are needed to assess capacity to invest.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-profile-5", "subjectId": "recommendations", "componentId": "rec-profile", "subtopic": "Current and future financial situation (cash flow, balance sheet, existing investments, tax situation, Social Security, pensions)", "stem": "A recently retired couple has a substantial defined-benefit pension and Social Security benefits that fully cover their essential living expenses. When constructing their portfolio, how should the adviser MOST appropriately treat these guaranteed income streams?", "choices": ["Ignore them, because only investable assets appear in an asset allocation", "Treat them as bond-like income that reduces the portfolio's need for additional fixed income and may support a higher equity allocation for the remainder", "Treat them as speculative assets requiring an offsetting conservative allocation", "Recommend the couple purchase additional bonds to match the size of the pension"], "answerIndex": 1, "explanation": "Guaranteed, non-discretionary income from a pension and Social Security functions like a bond-like stream covering essential expenses, which reduces the need for fixed income within the investment portfolio and can justify a higher equity allocation on the remaining assets. Ignoring them (A) misstates the couple's true financial picture; they are guaranteed, not speculative (C); and duplicating them with more bonds (D) would be redundant and overly conservative.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-profile-6", "subjectId": "recommendations", "componentId": "rec-profile", "subtopic": "Nonfinancial considerations (values, attitudes, experience, demographics, life events, behavioral finance)", "stem": "A client insists on selling all his stocks after two consecutive down quarters and moving everything into whatever fund had the best return last year. This behavior is BEST described as which combination of behavioral finance biases?", "choices": ["Anchoring and mental accounting", "Loss aversion combined with recency bias (performance chasing)", "Confirmation bias and framing", "Overconfidence and diversification"], "answerIndex": 1, "explanation": "Selling in a panic after losses reflects loss aversion (feeling losses more intensely than gains), and jumping to last year's best performer reflects recency bias / performance chasing (over-weighting recent results). Anchoring and mental accounting (A) describe fixating on a reference price and compartmentalizing money, not this pattern. Confirmation bias and framing (C) involve interpreting information, and diversification (D) is a sound strategy, not a bias.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-profile-7", "subjectId": "recommendations", "componentId": "rec-profile", "subtopic": "Client data gathering (identification, questionnaires, interviews)", "stem": "During the client data-gathering process, an IAR is completing steps required before opening the account, including verifying the client's identity, collecting a written questionnaire, and conducting an interview. Which statement about this process is MOST accurate?", "choices": ["Once gathered, the client profile is fixed and need not be updated even after major life events", "A written questionnaire fully substitutes for identity verification, so a Customer Identification Program is unnecessary", "Identity verification (CIP/KYC), questionnaires, and interviews are complementary tools, and the profile should be updated when the client's circumstances materially change", "Personal interviews should be avoided because only written documentation is legally valid"], "answerIndex": 2, "explanation": "Client identification (CIP/KYC/AML), questionnaires, and interviews are complementary methods, and the resulting profile must be updated when circumstances change materially (e.g., marriage, inheritance, job loss). The profile is not static (A), a questionnaire does not replace mandatory identity verification (B), and interviews are a valuable and accepted data-gathering tool, not something to avoid (D).", "difficulty": "medium", "source": "bank"},
  {"id": "rec-cmt-1", "subjectId": "recommendations", "componentId": "rec-cmt", "subtopic": "Investment theories and models (CAPM, modern portfolio theory, efficient market hypothesis)", "stem": "According to the Efficient Market Hypothesis, which form asserts that security prices fully reflect ALL past price and trading-volume information, implying that technical analysis cannot consistently produce excess returns?", "choices": ["Fundamental form", "Strong form", "Semi-strong form", "Weak form"], "answerIndex": 3, "explanation": "The weak form states that current prices already reflect all historical price and volume data, so technical analysis (which relies on past price/volume patterns) cannot generate consistent excess returns. The semi-strong form adds all publicly available information (undermining fundamental analysis of public data), and the strong form adds material non-public information as well. 'Fundamental form' is not a recognized form of EMH.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-cmt-2", "subjectId": "recommendations", "componentId": "rec-cmt", "subtopic": "Investment theories and models (CAPM, modern portfolio theory, efficient market hypothesis)", "stem": "An IAR is using the Capital Asset Pricing Model to determine the required return on a stock. The risk-free rate is 4%, the expected return on the market is 10%, and the stock's beta is 1.5. What is the stock's required return?", "choices": ["15%", "13%", "21%", "9%"], "answerIndex": 1, "explanation": "CAPM: required return = Rf + beta x (Rm - Rf) = 4% + 1.5 x (10% - 4%) = 4% + 1.5 x 6% = 4% + 9% = 13%. The 15% answer wrongly multiplies beta by the full market return (1.5 x 10%). The 9% answer is just the risk premium portion (1.5 x 6%), and 21% results from other misapplications of the formula.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-cmt-3", "subjectId": "recommendations", "componentId": "rec-cmt", "subtopic": "Investment theories and models (CAPM, modern portfolio theory, efficient market hypothesis)", "stem": "Under Modern Portfolio Theory, which action would MOST effectively reduce the total risk of a portfolio without necessarily reducing its expected return?", "choices": ["Adding securities whose returns have low or negative correlation with the existing holdings", "Increasing the portfolio's average beta above 1.0", "Concentrating the portfolio in the single security with the highest expected return", "Adding securities whose returns are highly positively correlated with the existing holdings"], "answerIndex": 0, "explanation": "MPT holds that combining assets with low or negative correlation reduces portfolio risk (standard deviation) through diversification, ideally without sacrificing expected return. Highly positively correlated securities move together and provide little diversification benefit. Concentrating in one security increases unsystematic risk, and raising average beta increases exposure to systematic (market) risk rather than reducing risk.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-cmt-4", "subjectId": "recommendations", "componentId": "rec-cmt", "subtopic": "Investment theories and models (CAPM, modern portfolio theory, efficient market hypothesis)", "stem": "In the context of CAPM and the Security Market Line, why are investors compensated only for bearing systematic risk rather than total risk?", "choices": ["Unsystematic risk can be eliminated through diversification, so the market does not reward bearing it", "Systematic risk is easier to measure than unsystematic risk", "Unsystematic risk is always larger than systematic risk in a portfolio", "Systematic risk applies only to bonds, while unsystematic risk applies only to equities"], "answerIndex": 0, "explanation": "CAPM assumes rational investors hold diversified portfolios, which eliminates unsystematic (company-specific) risk; since that risk can be removed for free through diversification, the market offers no premium for bearing it. Investors are compensated only for systematic (market) risk, which cannot be diversified away, captured by beta on the SML. The other choices misstate the risk categories or their relative sizes; both types can affect any asset class, and neither is inherently larger.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-cmt-5", "subjectId": "recommendations", "componentId": "rec-cmt", "subtopic": "Investment theories and models (CAPM, modern portfolio theory, efficient market hypothesis)", "stem": "A stock has a beta of 0.8. Using CAPM inputs of a 3% risk-free rate and a 9% expected market return, the analyst estimates the stock will actually return 10% over the coming period. Which conclusion is most consistent with capital market theory?", "choices": ["The stock's CAPM required return is 10.2%, so it plots below the SML and is overvalued", "The stock's CAPM required return is 7.8%, so it plots above the SML and appears undervalued", "The stock's CAPM required return is 9%, so it is fairly valued and plots on the SML", "Because beta is below 1.0, the stock cannot be evaluated using the Security Market Line"], "answerIndex": 1, "explanation": "CAPM required return = 3% + 0.8 x (9% - 3%) = 3% + 0.8 x 6% = 3% + 4.8% = 7.8%. Because the estimated actual return (10%) exceeds the required return (7.8%), the stock offers more return than its systematic risk demands, so it plots ABOVE the SML and appears undervalued (a buy). The 10.2% figure incorrectly computes the required return, and the SML applies to securities of any beta, including those below 1.0.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-portfolio-1", "subjectId": "recommendations", "componentId": "rec-portfolio", "subtopic": "Strategies (strategic vs. tactical asset allocation)", "stem": "An investment adviser establishes a client's long-term target allocation of 60% equities and 40% bonds and rebalances the portfolio back to those weights once a year. After a strong equity rally pushes stocks to 70% of the portfolio, the adviser sells equities and buys bonds to restore 60/40. This approach is best described as:", "choices": ["Dollar-cost averaging", "Sector rotation", "Strategic asset allocation", "Tactical asset allocation"], "answerIndex": 2, "explanation": "Setting fixed long-term target weights and periodically rebalancing back to them is strategic asset allocation; note that rebalancing forces selling the outperforming asset and buying the underperformer. Tactical allocation is the opposite: intentional short-term deviations from targets to exploit market views, not a return to a fixed baseline. Sector rotation shifts among industry sectors, and dollar-cost averaging is a fixed-dollar periodic investing technique, neither of which describes rebalancing to target weights.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-portfolio-2", "subjectId": "recommendations", "componentId": "rec-portfolio", "subtopic": "Styles (active, passive, growth, value, income, capital appreciation)", "stem": "An IAR believes that markets are efficient and that consistently beating a broad benchmark after costs is unlikely. Which portfolio approach is most consistent with that belief?", "choices": ["Passive management using a low-cost index fund", "Frequent sector rotation based on economic forecasts", "Tactical asset allocation with active market timing", "Concentrating in a few high-conviction growth stocks"], "answerIndex": 0, "explanation": "A belief in efficient markets implies that active selection and timing add little value net of fees, so a passive, low-cost index approach that simply matches the benchmark is most consistent. Concentrated growth picking, sector rotation, and tactical timing are all forms of active management that assume the manager can exploit mispricings — the opposite of the efficient-market view.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-portfolio-3", "subjectId": "recommendations", "componentId": "rec-portfolio", "subtopic": "Techniques (diversification, sector rotation, dollar-cost averaging, options, leveraging, volatility management, inverse strategies, HFT)", "stem": "A client invests exactly $600 in a mutual fund on the first trading day of each month for three months. The share price is $20, $15, and $10 on those three dates, respectively. Using dollar-cost averaging, what is the client's approximate average cost per share?", "choices": ["$11.67 per share", "$12.86 per share", "$15.00 per share", "$13.85 per share"], "answerIndex": 3, "explanation": "Dollar-cost averaging invests a fixed dollar amount each period. Shares bought: $600/$20 = 30, $600/$15 = 40, $600/$10 = 60, totaling 130 shares for $1,800 invested. Average cost = $1,800 / 130 = approximately $13.85 per share. The $15.00 choice is the simple (arithmetic) average of the three prices — the classic trap — which always exceeds the dollar-cost-averaging cost when prices vary; the $12.86 and $11.67 choices result from incorrect share or dollar totals.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-portfolio-4", "subjectId": "recommendations", "componentId": "rec-portfolio", "subtopic": "Styles (active, passive, growth, value, income, capital appreciation)", "stem": "A growth-oriented investor is screening for stocks that fit a classic value style instead. Which combination of characteristics should the investor look for?", "choices": ["High price-to-earnings ratio, high price-to-book ratio, and little or no dividend", "Rapid revenue growth, high beta, and earnings reinvested rather than distributed", "Low price-to-earnings ratio, low price-to-book ratio, and a relatively high dividend yield", "High expected earnings growth combined with a premium market valuation"], "answerIndex": 2, "explanation": "Value stocks are those the market appears to have underpriced: they typically show low P/E and low price-to-book ratios and often pay relatively high dividend yields. The other choices describe growth stocks — high P/E, high price-to-book, rapid growth, high beta, reinvested earnings, and premium valuations — which is the style the investor is trying to avoid.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-portfolio-5", "subjectId": "recommendations", "componentId": "rec-portfolio", "subtopic": "Techniques (diversification, sector rotation, dollar-cost averaging, options, leveraging, volatility management, inverse strategies, HFT)", "stem": "A conservative retiree seeking stable current income and preservation of capital asks an IAR about holding a triple-leveraged inverse equity ETF as a long-term core position. Which statement is the most accurate basis for the IAR's response?", "choices": ["Because it resets its leverage daily, its long-term return can diverge substantially from three times the inverse of the index, making it unsuitable as a long-term holding", "Leveraged inverse ETFs eliminate systematic risk and therefore reduce the portfolio's overall volatility", "The fund is well suited as a core holding because its inverse structure diversifies away market risk over time", "The product is appropriate because leverage guarantees higher income for retirees than an unleveraged fund"], "answerIndex": 0, "explanation": "Leveraged and inverse ETFs reset exposure daily, so compounding causes their multi-day returns to drift from a simple multiple of the index; they are short-term trading tools, not buy-and-hold core positions, and are unsuitable for a conservative retiree. Diversification and inverse exposure do not remove systematic (market) risk, and leverage magnifies risk while adding cost — it does not guarantee income. The product increases, rather than reduces, portfolio volatility.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-portfolio-6", "subjectId": "recommendations", "componentId": "rec-portfolio", "subtopic": "Techniques (diversification, sector rotation, dollar-cost averaging, options, leveraging, volatility management, inverse strategies, HFT)", "stem": "An adviser adds several securities with low correlations to an already-diversified equity portfolio, reducing its overall standard deviation. Which type of risk is being reduced, and what remains?", "choices": ["Systematic risk is reduced, while unsystematic risk remains and cannot be diversified away", "Unsystematic risk is reduced, while systematic (market) risk remains and cannot be diversified away", "Both systematic and unsystematic risk are fully eliminated once enough securities are added", "Interest-rate risk is reduced, while purchasing-power risk is eliminated entirely"], "answerIndex": 1, "explanation": "Diversification with low-correlation assets reduces unsystematic (company- and industry-specific) risk, which is why portfolio standard deviation falls, but it cannot remove systematic (market) risk that affects all securities. The first choice reverses which risk is diversifiable. No amount of diversification eliminates systematic risk entirely, and the interest-rate/purchasing-power option misidentifies the risks at work in broad equity diversification.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-tax-1", "subjectId": "recommendations", "componentId": "rec-tax", "subtopic": "Individual income tax (capital gains, qualified dividends, tax basis, marginal bracket, AMT)", "stem": "An investor sells stock she has held for exactly 11 months at a $6,000 gain. She is in the 32% marginal ordinary income tax bracket. How will this gain be taxed?", "choices": ["At the 0% rate because capital gains under $10,000 are exempt", "At the 15% long-term capital gains rate because she held it nearly a year", "As ordinary income at her 32% marginal rate because the holding period did not exceed one year", "At a blended 20% rate applied to all capital gains"], "answerIndex": 2, "explanation": "Long-term capital gains treatment requires a holding period of MORE than one year. An 11-month hold is short-term, so the gain is taxed as ordinary income at her marginal 32% rate. The 15% and 20% rates apply only to long-term gains, and there is no blanket exemption for gains under a dollar threshold.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-tax-2", "subjectId": "recommendations", "componentId": "rec-tax", "subtopic": "Individual income tax (capital gains, qualified dividends, tax basis, marginal bracket, AMT)", "stem": "An IAR is reviewing a client who received $4,000 in interest from private-activity municipal bonds and exercised incentive stock options with a large bargain element. For which federal tax calculation are these items specifically relevant as add-backs?", "choices": ["The Alternative Minimum Tax (AMT)", "The net investment income surtax basis adjustment", "The qualified dividend preferential rate", "The dividends-received deduction"], "answerIndex": 0, "explanation": "Private-activity municipal bond interest and the bargain element on exercised incentive stock options are classic AMT preference/adjustment items that are added back in the parallel AMT computation. The dividends-received deduction applies to corporations receiving dividends, and qualified dividend rates concern dividend taxation, not preference add-backs.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-tax-3", "subjectId": "recommendations", "componentId": "rec-tax", "subtopic": "Individual income tax (capital gains, qualified dividends, tax basis, marginal bracket, AMT)", "stem": "A client buys 100 shares at $50, pays a $40 commission, and over time reinvests $300 of dividends and receives a $200 return-of-capital distribution. What is the client's adjusted cost basis in the position?", "choices": ["$5,140", "$4,940", "$5,000", "$5,540"], "answerIndex": 0, "explanation": "Basis starts at the $5,000 purchase price, is increased by the $40 commission and the $300 of reinvested dividends (which were already taxed), and is reduced by the $200 return of capital: 5,000 + 40 + 300 - 200 = $5,140. Answers that ignore the commission or reinvested dividends, or that add the return of capital instead of subtracting it, are incorrect.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-tax-4", "subjectId": "recommendations", "componentId": "rec-tax", "subtopic": "Corporations, trusts, and estates income tax", "stem": "A complex trust earns $30,000 of taxable income and distributes $18,000 to its beneficiary during the year. Which statement best describes the federal income tax treatment?", "choices": ["The entire $30,000 is taxed to the beneficiary regardless of the amount distributed", "The beneficiary owes no tax because trust distributions are always tax-free gifts", "The beneficiary is taxed on the distributed income up to distributable net income, and the trust is taxed on income it retains, using compressed brackets", "The trust pays tax on all $30,000 because trusts are always taxed at the entity level"], "answerIndex": 2, "explanation": "A trust is a separate taxpayer that gets a deduction for income distributed to beneficiaries up to distributable net income (DNI); the beneficiary reports that income, while income the trust retains is taxed to the trust under its highly compressed brackets. Distributions are not tax-free gifts, and undistributed income is not shifted to the beneficiary.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-tax-5", "subjectId": "recommendations", "componentId": "rec-tax", "subtopic": "Corporations, trusts, and estates income tax", "stem": "Which statement correctly contrasts the federal income taxation of a C corporation with that of an S corporation?", "choices": ["A C corporation's income is subject to double taxation, while an S corporation is generally a pass-through entity whose income flows to shareholders via Schedule K-1", "Only C corporation shareholders report income on a Schedule K-1", "An S corporation pays a higher corporate tax rate than a C corporation", "Both are pass-through entities that avoid entity-level tax"], "answerIndex": 0, "explanation": "A C corporation pays corporate income tax and its shareholders are taxed again on dividends (double taxation), whereas an S corporation generally pays no entity-level tax and passes income through to shareholders on Schedule K-1. C corporations are not pass-throughs, and it is S corporation (and partnership) owners, not C corporation shareholders, who receive K-1s.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-tax-6", "subjectId": "recommendations", "componentId": "rec-tax", "subtopic": "Wealth transfer, estate tax, and gift tax fundamentals", "stem": "A widower wants to transfer a low-basis stock (basis $20,000, current value $200,000) to his adult daughter and asks his adviser about the basis consequences. Which statement is accurate?", "choices": ["A lifetime gift gives the daughter a stepped-up basis of $200,000, so gifting now is always best for taxes", "Inherited property always keeps the decedent's original basis regardless of value", "Both a lifetime gift and an inheritance give the daughter a $20,000 carryover basis", "If he gifts the stock during his life, the daughter takes his $20,000 carryover basis; if she inherits it at his death, her basis steps up to the $200,000 fair market value"], "answerIndex": 3, "explanation": "A lifetime gift carries over the donor's basis, so the daughter would take the $20,000 basis and face a large gain if she sells. Property transferred at death receives a stepped-up basis to date-of-death fair market value ($200,000), potentially eliminating the built-in gain. The other choices reverse or conflate these rules; gifting a low-basis asset is often the LESS tax-favorable option.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-retirement-1", "subjectId": "recommendations", "componentId": "rec-retirement", "subtopic": "Qualified retirement plans", "stem": "Which statement best distinguishes a qualified retirement plan from a nonqualified retirement plan?", "choices": ["A qualified plan may lawfully discriminate in favor of highly compensated executives, while a nonqualified plan may not", "Both plan types give the employer an immediate deduction, but only nonqualified plans grow tax-deferred", "A qualified plan must be nondiscriminatory and gives the employer a current tax deduction for contributions, while a nonqualified plan may discriminate but the employer's deduction is deferred until the employee is paid", "Distributions from a qualified plan are taxed as long-term capital gains, while nonqualified distributions are ordinary income"], "answerIndex": 2, "explanation": "Qualified plans must satisfy IRS Section 401(a) nondiscrimination rules and cannot favor highly compensated employees; in exchange the employer deducts contributions currently. Nonqualified plans MAY discriminate (rewarding select executives), but the employer's deduction is deferred until the employee actually receives the money. The option saying a qualified plan may discriminate while a nonqualified plan may not reverses the rule; capital-gains treatment is wrong because qualified distributions are ordinary income; and the 'both get an immediate deduction' option is wrong because a nonqualified employer's deduction is deferred.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-retirement-2", "subjectId": "recommendations", "componentId": "rec-retirement", "subtopic": "IRAs (traditional, Roth)", "stem": "A client, age 45, has held a Roth IRA for eight years and takes a distribution consisting of $12,000 of contributions and $6,000 of earnings to pay for a vacation. What is the federal tax treatment of this distribution?", "choices": ["The entire $18,000 is tax-free because the account has been open more than five years", "The entire $18,000 is taxable as ordinary income plus a 10% penalty", "The $6,000 of earnings is tax-free, but the $12,000 of contributions is taxable", "The $12,000 of contributions is tax-free, but the $6,000 of earnings is taxable and subject to a 10% penalty"], "answerIndex": 3, "explanation": "Roth contributions are made with after-tax dollars and can always be withdrawn tax- and penalty-free, and under the ordering rules contributions come out first. The earnings are only tax-free in a QUALIFIED distribution, which requires the 5-year period AND a qualifying event (age 59 1/2, death, disability, or first home). At 45 with a vacation as the purpose, no qualifying event exists, so the $6,000 of earnings is taxable and hit with the 10% early-withdrawal penalty. The five-year period alone is not enough, and returned contributions (the basis) are never taxed on withdrawal.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-retirement-3", "subjectId": "recommendations", "componentId": "rec-retirement", "subtopic": "Solo 401(k) (traditional, Roth)", "stem": "An IAR is advising a 52-year-old self-employed graphic designer who runs a profitable one-person business with no employees and wants to maximize tax-advantaged retirement savings well beyond the IRA limit. Which feature of a Solo 401(k) most directly supports that goal?", "choices": ["Its earnings are taxed as long-term capital gains rather than ordinary income when withdrawn", "It permits the owner to contribute both as an employee (elective deferral) and as an employer (profit-sharing), producing a much higher combined limit than an IRA", "It allows unlimited nondeductible contributions with no annual cap", "It is a nonqualified plan, so contributions avoid all ERISA and IRS limits"], "answerIndex": 1, "explanation": "The defining advantage of a Solo 401(k) is that the self-employed owner 'wears two hats,' making an employee elective deferral plus an employer profit-sharing contribution, yielding a far higher total than an IRA. Contributions are not unlimited - there are statutory dollar and percentage caps. It is a qualified plan (subject to IRS limits), and pre-tax distributions are ordinary income, not capital gains.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-retirement-4", "subjectId": "recommendations", "componentId": "rec-retirement", "subtopic": "Nonqualified retirement plans", "stem": "A company establishes a deferred compensation plan under which only three senior executives may defer part of their salary until retirement. The employer makes an unsecured promise to pay the deferred amounts later. Which statement about this arrangement is CORRECT?", "choices": ["Because it is nonqualified, the plan may cover only the three executives, the employer's deduction is deferred until the executives are paid, and the deferred funds generally remain subject to the employer's creditors", "The employer deducts the deferred amounts in the year they are earned, and the funds are protected from the employer's creditors", "The plan must satisfy ERISA nondiscrimination rules and therefore must be offered to all employees", "Executives are taxed on the deferred amounts in the year earned, and the employer receives no deduction at any time"], "answerIndex": 0, "explanation": "This is a nonqualified deferred compensation plan, which may lawfully cover a select group of key executives (a top-hat arrangement exempt from most ERISA nondiscrimination requirements). The employer's deduction is deferred until the employee actually receives payment, matching the employee's income recognition. Because the arrangement is typically an unfunded promise, the deferred amounts remain the employer's assets and are reachable by the employer's creditors. The options describing an immediate deduction with creditor protection or mandatory all-employee coverage describe qualified-plan features, and taxing the executives in the year earned is wrong because both the employee's taxation and the employer's deduction occur when the money is paid, not when earned.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-retirement-5", "subjectId": "recommendations", "componentId": "rec-retirement", "subtopic": "IRAs (traditional, Roth)", "stem": "Which statement comparing traditional and Roth IRA contribution rules is accurate?", "choices": ["A traditional IRA has no income limit on making a contribution, but the ability to contribute to a Roth IRA phases out at higher modified adjusted gross income", "Both traditional and Roth IRA contributions are tax-deductible in the year made", "A Roth IRA requires the original owner to take required minimum distributions beginning at the same age as a traditional IRA", "High earners are barred from contributing to a traditional IRA but face no income limit on Roth contributions"], "answerIndex": 0, "explanation": "Anyone with earned income can contribute to a traditional IRA regardless of income (income only affects DEDUCTIBILITY), whereas the ability to contribute to a Roth IRA is phased out above certain MAGI thresholds. Roth contributions are never deductible, so the 'both are deductible' option is wrong. Roth IRAs impose no lifetime RMDs on the original owner, so the RMD-parity option is wrong. The remaining option reverses the actual income-limit rules.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-retirement-6", "subjectId": "recommendations", "componentId": "rec-retirement", "subtopic": "Solo 401(k) (traditional, Roth)", "stem": "A 40-year-old self-employed consultant makes only Roth elective deferrals into her Solo 401(k) and separately makes the employer profit-sharing contribution. Three years later, before age 59 1/2, she withdraws a portion of the account. Which statement about the tax character of her account and this early withdrawal is CORRECT?", "choices": ["Because all elective deferrals were Roth, the entire account including the employer contribution comes out completely tax-free", "The employer profit-sharing contribution is always Roth and therefore tax-free at any age", "The Roth deferrals were made with after-tax dollars, the employer profit-sharing portion is pre-tax, and earnings on the Roth deferrals are not yet qualified for tax-free treatment because neither the 5-year period nor a qualifying event is met", "The Roth deferrals were pre-tax and the employer profit-sharing contributions were after-tax"], "answerIndex": 2, "explanation": "Roth 401(k) elective deferrals are made with after-tax dollars, while the employer profit-sharing contribution is traditionally pre-tax and grows tax-deferred (taxed as ordinary income when distributed). A qualified tax-free Roth distribution requires both the 5-year period AND a qualifying event; here she is 40 with only three years elapsed, so the earnings are not yet qualified and would be taxable plus penalized if withdrawn. The options that reverse the tax character or claim the entire account is tax-free ignore that the employer portion is pre-tax.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-erisa-1", "subjectId": "recommendations", "componentId": "rec-erisa", "subtopic": "Fiduciary issues (investment choices, ERISA 404(c))", "stem": "Under ERISA, which standard of care applies to a fiduciary who manages the investments of a private-sector pension plan?", "choices": ["The suitability standard, requiring only that investments be suitable for the average participant", "The best-execution standard, requiring only that trades be executed at the lowest available commission", "The prudent layperson standard, requiring the care an ordinary person would use with their own money", "The prudent expert standard, requiring the care, skill, and diligence of a knowledgeable professional acting solely in participants' interest"], "answerIndex": 3, "explanation": "ERISA imposes the 'prudent expert' standard - a fiduciary must act with the care, skill, prudence, and diligence of a knowledgeable professional familiar with such matters, solely in the interest of participants and beneficiaries, and must diversify to minimize large losses. A prudent-layperson standard - the care an ordinary person would use with their own money - is a lower bar and is not what ERISA demands. Suitability and best-execution are broker-dealer/trade concepts, not the governing fiduciary standard for plan management.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-erisa-2", "subjectId": "recommendations", "componentId": "rec-erisa", "subtopic": "Fiduciary issues (investment choices, ERISA 404(c))", "stem": "A 401(k) plan sponsor wants the protection of ERISA Section 404(c) so that participants, rather than plan fiduciaries, bear responsibility for the results of their own investment selections. Which condition must the plan satisfy?", "choices": ["It must guarantee that no participant can lose principal in any offered option", "It must offer at least three diversified investment alternatives with materially different risk/return characteristics and allow changes at least quarterly", "It must be professionally managed by a single registered investment adviser with full discretion over participant accounts", "It must limit participants to selecting only from employer stock and a stable-value fund"], "answerIndex": 1, "explanation": "Section 404(c) relief applies only when participants have genuine control and a 'broad range' of options - generally at least three diversified alternatives with materially different risk/return characteristics, with the ability to change allocations at least quarterly. It does not require guaranteeing principal (choice A). Giving an adviser full discretion (choice C) would remove participant control, defeating 404(c). Limiting choices to employer stock and one fund (choice D) fails the diversified 'broad range' requirement.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-erisa-3", "subjectId": "recommendations", "componentId": "rec-erisa", "subtopic": "Investment policy statement", "stem": "An IAR is helping the trustees of a company retirement plan formalize how plan investments will be chosen, monitored, and replaced. Which statement about the plan's Investment Policy Statement (IPS) is CORRECT?", "choices": ["ERISA statutorily requires every plan to file its IPS with the Department of Labor before investing", "The IPS is legally binding on participants and overrides their individual investment elections", "ERISA does not mandate an IPS, but maintaining and following one is a best practice that evidences a prudent process", "Once adopted, the IPS may never be amended for the life of the plan"], "answerIndex": 2, "explanation": "An IPS is a fiduciary best practice, not a statutory ERISA requirement; maintaining and consistently following one demonstrates a prudent, documented process that the DOL and courts view favorably. There is no requirement to file it with the DOL (choice A). It guides fiduciary decisions rather than binding participants' elections (choice B), and it should be reviewed and updated periodically as circumstances change (choice D).", "difficulty": "medium", "source": "bank"},
  {"id": "rec-erisa-4", "subjectId": "recommendations", "componentId": "rec-erisa", "subtopic": "Prohibited transactions", "stem": "A plan fiduciary causes the pension plan to purchase an office building from the plan sponsor (a party in interest) for $2,000,000, a price equal to a current independent appraisal. No prohibited-transaction exemption applies, and the transaction is not corrected within the taxable period. Which statement is correct?", "choices": ["Because the price matched an independent appraisal, the transaction is permitted and no penalty applies", "The transaction is prohibited under ERISA Section 406, and the excise tax escalates to 100% of the amount involved because it was not corrected", "The transaction is permitted because purchasing real estate always satisfies ERISA's diversification duty", "The transaction is prohibited, but the only consequence is a fixed $10,000 civil fine regardless of the amount involved"], "answerIndex": 1, "explanation": "A sale or exchange of property between a plan and a party in interest is a prohibited transaction under ERISA Section 406 even when the price is fair - fairness does not cure the violation absent an exemption, so choice A is wrong. Under IRC Section 4975 the excise tax starts at 15% of the amount involved and rises to 100% if the transaction is not timely corrected, making choice B correct and choice D wrong. Buying real estate does not automatically satisfy diversification (choice C), and diversification is irrelevant to whether a 406 prohibited transaction occurred.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-accounts-1", "subjectId": "recommendations", "componentId": "rec-accounts", "subtopic": "Education accounts (529 plans, Coverdell)", "stem": "An investor wants to fund a newborn niece's future college costs. The investor insists on retaining the right to reclaim the money later or redirect it to a different relative if the niece does not attend college. Which vehicle best fits these requirements?", "choices": ["A health savings account funded for the niece", "A UTMA custodial account naming the niece as beneficiary", "A Coverdell ESA with the niece as designated beneficiary", "A 529 college savings plan with the investor as account owner"], "answerIndex": 3, "explanation": "A 529 plan lets the account OWNER retain control - the owner can change the beneficiary to another qualifying family member or even reclaim the funds (paying tax and a 10% penalty on earnings). A UTMA is an irrevocable gift, so the money legally belongs to the minor and cannot be reclaimed or redirected. A Coverdell also names a beneficiary but is capped at $2,000/year with income phase-outs, making it a poor fit for funding college; and an HSA is a medical-expense account tied to an HDHP, not an education vehicle.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-accounts-2", "subjectId": "recommendations", "componentId": "rec-accounts", "subtopic": "UTMA and UGMA", "stem": "A custodian opens an account for a 10-year-old under the Uniform Transfers to Minors Act (UTMA). Which statement is correct?", "choices": ["The gift is revocable, so the custodian may return the assets to the donor at any time", "The custodian is the legal owner of the assets and reports the income on the custodian's own return", "Multiple minors may be named as co-beneficiaries of a single UTMA account", "The minor is the beneficial owner, and control passes to the minor at the age of majority set by state law"], "answerIndex": 3, "explanation": "An UGMA/UTMA gift is irrevocable, and the minor - not the custodian - is the legal and beneficial owner; the custodian merely manages the assets for the minor's benefit until control transfers at the state's age of majority. The gift cannot be revoked or returned to the donor, and each custodial account has exactly one minor and one custodian, so co-beneficiaries are not permitted. Income is reported under the minor's Social Security number, potentially subject to the kiddie tax.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-accounts-3", "subjectId": "recommendations", "componentId": "rec-accounts", "subtopic": "Health savings accounts (HSA)", "stem": "A 58-year-old client with a high-deductible health plan has an HSA that has grown substantially. She takes a $5,000 distribution and uses it for a kitchen renovation, not a medical expense. What are the federal tax consequences?", "choices": ["The $5,000 is taxed as ordinary income plus a 20% penalty", "The $5,000 is tax-free because HSA distributions are always exempt", "The $5,000 is taxed as ordinary income plus a 10% penalty", "Only the earnings portion is taxed, with no penalty"], "answerIndex": 0, "explanation": "A nonqualified HSA distribution taken before age 65 is included in ordinary income AND hit with a 20% penalty on the full amount withdrawn. The 10% figure is the penalty for nonqualified 529/Coverdell (and early-IRA) distributions, not HSAs. The distribution is not tax-free because it was not used for qualified medical expenses, and unlike an education account the entire nonqualified HSA withdrawal - not just earnings - is taxed. Only after age 65 would the 20% penalty disappear.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-accounts-4", "subjectId": "recommendations", "componentId": "rec-accounts", "subtopic": "Education accounts (529 plans, Coverdell)", "stem": "A client contributed $12,000 total to a Coverdell ESA for her son over several years; the account is now worth $15,000. The son receives a $6,000 distribution that is NOT used for any qualified education expense. Approximately how much of that distribution is subject to income tax and the 10% penalty?", "choices": ["$1,200, the earnings portion of the distribution", "$0, because Coverdell principal and earnings are always tax-free", "The full $6,000, because no qualified expense was incurred", "$3,000, the total account earnings"], "answerIndex": 0, "explanation": "For a nonqualified education distribution, only the EARNINGS portion is taxed as ordinary income and hit with the 10% penalty; the return of contributions is never taxed. Earnings are $15,000 - $12,000 = $3,000, which is 20% of the $15,000 account. Applying that 20% ratio to the $6,000 withdrawal gives $1,200 of taxable/penalized earnings, while the remaining $4,800 is a tax-free return of principal. Taxing the full $6,000 or the entire $3,000 of account earnings overstates the taxable amount.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-ownership-1", "subjectId": "recommendations", "componentId": "rec-ownership", "subtopic": "Types of ownership (JTWROS, tenants in common, tenancy by the entirety)", "stem": "A brokerage account is titled joint tenants with right of survivorship (JTWROS) between two unrelated business partners. One partner dies leaving a will that directs his entire estate to his children. What happens to the deceased partner's interest in the account?", "choices": ["It is split equally between the surviving partner and the children", "It passes to the children as directed by the will after probate", "It is frozen until a court determines the rightful heirs", "It passes automatically to the surviving joint tenant, regardless of the will"], "answerIndex": 3, "explanation": "JTWROS carries a right of survivorship, so the deceased owner's interest passes automatically by operation of law to the surviving joint tenant, bypassing probate and overriding the will. The will controls only probate assets, so the children take nothing from this account. There is no equal split with the heirs and no need to freeze the account, because title determines disposition.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-ownership-2", "subjectId": "recommendations", "componentId": "rec-ownership", "subtopic": "Types of ownership (JTWROS, tenants in common, tenancy by the entirety)", "stem": "Which statement best distinguishes tenancy by the entirety from a standard joint tenancy with right of survivorship?", "choices": ["Tenancy by the entirety has no right of survivorship, while JTWROS does", "Tenancy by the entirety is available only to married couples and generally shields the property from one spouse's individual creditors", "Tenancy by the entirety allows each owner to sell his or her share unilaterally, while JTWROS does not", "Tenancy by the entirety requires the owners to hold unequal fractional interests"], "answerIndex": 1, "explanation": "Tenancy by the entirety is a survivorship form of ownership limited to married couples (in states that recognize it) and adds creditor protection because neither spouse can unilaterally sever, sell, or encumber the property to satisfy an individual debt. It DOES have survivorship, so the first choice is wrong. Neither spouse can act unilaterally, which contradicts the third choice, and entirety interests are undivided and equal, not unequal fractional shares (that describes tenants in common).", "difficulty": "medium", "source": "bank"},
  {"id": "rec-ownership-3", "subjectId": "recommendations", "componentId": "rec-ownership", "subtopic": "Pay on death and transfer on death", "stem": "A widowed client opens an individual brokerage account and adds a transfer-on-death (TOD) registration naming her nephew. Before her death, which of the following is TRUE?", "choices": ["The nephew must consent in writing before the client can sell any securities", "The account is removed from the client's taxable estate once the TOD is added", "The client retains full ownership and control, and the nephew has no rights until she dies", "The nephew becomes a co-owner and can trade or withdraw from the account"], "answerIndex": 2, "explanation": "A TOD registration lets a sole owner name a beneficiary who receives the securities at death without probate, but the owner retains complete control while alive and the named beneficiary has no ownership rights or account access until the owner dies. The nephew is therefore neither a co-owner nor a required consenting party, and the account remains part of the client's taxable estate because she still owns it outright.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-ownership-4", "subjectId": "recommendations", "componentId": "rec-ownership", "subtopic": "Beneficiary designation", "stem": "A client's will leaves 'all my property equally to my two children.' The client also owns a $500,000 IRA that names only her spouse as the primary beneficiary, and a $300,000 life insurance policy naming her spouse as beneficiary. At the client's death, how are the IRA and the life insurance proceeds distributed?", "choices": ["To the spouse, because beneficiary designations pass by contract and override the will", "Half to the spouse and half to the children, splitting between the will and the designations", "The distribution is decided by the probate court after reviewing the will and the designations", "Equally to the two children, because the will controls all of the client's assets"], "answerIndex": 0, "explanation": "IRAs and life insurance pass by contract directly to the named beneficiary, bypassing probate and overriding the terms of the will. Because the spouse is the named beneficiary on both, the spouse receives the full $500,000 IRA and $300,000 policy; the will governs only probate assets and cannot redirect these. There is no split with the children and no probate-court reallocation of contract designations.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-ownership-5", "subjectId": "recommendations", "componentId": "rec-ownership", "subtopic": "Qualified domestic relations order (QDRO)", "stem": "An investment adviser representative is meeting with a client who is finalizing a divorce and wants to give his soon-to-be ex-spouse a portion of both his 401(k) plan and his traditional IRA. Which statement about dividing these accounts is correct?", "choices": ["Neither account can be divided in divorce because retirement assets are protected from an ex-spouse", "A QDRO can divide the IRA, but the 401(k) can only be divided after the client separates from service", "A QDRO is required to divide both the 401(k) and the IRA", "A QDRO is used to divide the 401(k), but the IRA is divided through the divorce decree as a transfer incident to divorce"], "answerIndex": 3, "explanation": "A qualified domestic relations order (QDRO) is used to assign benefits from qualified ERISA plans such as a 401(k) to an alternate payee like an ex-spouse. IRAs are NOT divided by a QDRO; they are split pursuant to the divorce decree or separation agreement as a transfer incident to divorce, which avoids tax if done correctly. Retirement assets can be divided in divorce, and the 401(k) does not require separation from service to be split by a QDRO.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-trading-1", "subjectId": "recommendations", "componentId": "rec-trading", "subtopic": "Terminology (bids, offers, quotes, market/limit/stop orders, short sales, cash vs. margin accounts, principal vs. agency trades, payment for order flow)", "stem": "A stock is quoted 42.10 bid, 42.25 ask. A client enters a market order to buy 100 shares that executes immediately against the displayed quote. Ignoring commissions, what price will the client most likely pay per share, and what does the 15-cent difference represent?", "choices": ["42.10, representing the markdown the dealer earns", "42.10, representing the commission built into the quote", "42.25, representing the bid/ask spread, an implicit cost of trading", "42.25, representing payment for order flow paid to the client"], "answerIndex": 2, "explanation": "A market order to buy is filled at the ask (offer), the lowest price a seller will accept, so the client pays 42.25. The 15-cent gap between the 42.10 bid and 42.25 ask is the bid/ask spread, an implicit cost of trading. It is not a commission (an explicit agency charge), not a markdown (which applies when a dealer buys from a client), and payment for order flow is compensation the firm receives, not something paid to the client.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-trading-2", "subjectId": "recommendations", "componentId": "rec-trading", "subtopic": "Terminology (bids, offers, quotes, market/limit/stop orders, short sales, cash vs. margin accounts, principal vs. agency trades, payment for order flow)", "stem": "A client holds 500 shares of a stock currently trading at $60 and wants to limit losses if the price falls, while staying invested as long as the stock holds up. Which single order best accomplishes this?", "choices": ["A sell stop order placed at $55", "A sell limit order placed at $65", "A buy stop order placed at $65", "A buy limit order placed at $55"], "answerIndex": 0, "explanation": "To protect a long position from a decline, the client uses a sell stop placed below the current market; if the stock falls to $55 the stop triggers and the shares are sold, capping further loss. A sell limit at $65 is placed above the market to capture a higher sale price, not to limit downside. Buy orders (buy limit, buy stop) are for acquiring shares, not protecting an existing long position. Remember: buy limit and sell stop go below the market.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-trading-3", "subjectId": "recommendations", "componentId": "rec-trading", "subtopic": "Terminology (bids, offers, quotes, market/limit/stop orders, short sales, cash vs. margin accounts, principal vs. agency trades, payment for order flow)", "stem": "An IAR's client buys 200 shares through a broker-dealer that fills the order out of its own inventory at $30.00 per share and adds a $0.20 per-share charge, disclosing on the confirmation that it acted as principal. Which statement is correct?", "choices": ["The firm acted as a custodian and the $0.20 is a safekeeping fee", "The firm acted as a market maker and the $0.20 is payment for order flow", "The firm acted as a principal and the $0.20 is a markup", "The firm acted as an agent and the $0.20 is a commission"], "answerIndex": 2, "explanation": "Because the broker-dealer sold from its own inventory, it acted in a principal (dealer) capacity, and compensation on a principal sale to a customer is a markup, not a commission. A commission is charged only in an agency (broker) capacity where the firm arranges a trade between other parties. Payment for order flow is money a firm receives for routing orders elsewhere, not a per-share charge added to a principal fill, and a custodian merely safekeeps assets rather than filling trades.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-trading-4", "subjectId": "recommendations", "componentId": "rec-trading", "subtopic": "Roles of broker-dealers, custodians, market makers, exchanges", "stem": "In the structure of the securities markets, which participant continuously posts two-sided quotes and stands ready to buy and sell a security from its own inventory to provide liquidity?", "choices": ["A transfer agent", "A market maker", "A custodian", "A clearing corporation"], "answerIndex": 1, "explanation": "A market maker is a dealer that quotes both a bid and an ask and commits its own capital to buy and sell, supplying liquidity to the market. A custodian holds client cash and securities for safekeeping. A transfer agent maintains ownership records and processes issuance/cancellation of certificates. A clearing corporation handles the post-trade clearing and settlement process; none of these three provide continuous two-sided quotes.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-trading-5", "subjectId": "recommendations", "componentId": "rec-trading", "subtopic": "Costs of trading (commissions, markups, bid/ask spread, best execution)", "stem": "A broker-dealer receives compensation for routing its customers' equity orders to a particular wholesale market maker. Under the firm's obligations, which statement is most accurate?", "choices": ["The arrangement eliminates the best execution duty because the market maker guarantees the national best bid or offer", "The arrangement is prohibited because any third-party compensation voids best execution", "The arrangement is permitted, but it must be disclosed and must not compromise the duty of best execution", "The arrangement is permitted only if the firm acts as principal on every routed order"], "answerIndex": 2, "explanation": "This describes payment for order flow, which is permitted but must be disclosed and can never be allowed to override the firm's duty of best execution - the obligation to seek the most favorable terms reasonably available considering price, speed, and likelihood of execution. It is not outright prohibited, it does not eliminate or satisfy the best execution duty on its own, and it is unrelated to whether the firm trades as principal on each order.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-performance-1", "subjectId": "recommendations", "componentId": "rec-performance", "subtopic": "Returns (risk-adjusted, time-weighted, dollar-weighted, annualized, total, holding period, IRR, expected, inflation-adjusted, after-tax)", "stem": "An investment adviser representative wants to evaluate a portfolio manager's skill over the past three years. During that period, the client made several large, irregularly timed deposits and withdrawals. Which return measure should the IAR use to best isolate the manager's performance from the effect of those cash flows?", "choices": ["Time-weighted return", "Current yield", "Internal rate of return", "Dollar-weighted return"], "answerIndex": 0, "explanation": "Time-weighted return removes the distorting impact of client-controlled deposits and withdrawals, making it the standard for judging a manager's skill. Dollar-weighted return and its equivalent, the internal rate of return, are influenced by the size and timing of the client's cash flows, so they reflect the investor's experience rather than the manager's ability. Current yield only measures annual income relative to price and says nothing about overall manager performance.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-performance-2", "subjectId": "recommendations", "componentId": "rec-performance", "subtopic": "Current yield", "stem": "A bond with a 6% coupon and a $1,000 par value is currently trading at $1,200 in the secondary market. What is the bond's current yield?", "choices": ["4.8%", "7.2%", "6.0%", "5.0%"], "answerIndex": 3, "explanation": "Current yield equals annual coupon income divided by the current market price: $60 / $1,200 = 5.0%. The 6% choice is the nominal (coupon) yield based on par, which applies only when the bond trades at $1,000. Because the bond trades at a premium, its current yield falls below the coupon rate, so 7.2% (which would require a discount price) is incorrect.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-performance-3", "subjectId": "recommendations", "componentId": "rec-performance", "subtopic": "Returns (risk-adjusted, time-weighted, dollar-weighted, annualized, total, holding period, IRR, expected, inflation-adjusted, after-tax)", "stem": "A client earned a nominal return of 8% last year. Over the same period, inflation was 3% and the client paid tax equal to 25% of the nominal return. Which statement best describes why the client's inflation-adjusted, after-tax return is materially lower than 8%?", "choices": ["Inflation increases real return while taxes are ignored for individual investors", "Nominal return already excludes both taxes and inflation, so no adjustment is needed", "Real return subtracts inflation and after-tax return subtracts taxes, so both purchasing-power erosion and taxes reduce what the client actually keeps", "The 8% figure is an expected return and therefore cannot be adjusted"], "answerIndex": 2, "explanation": "Real (inflation-adjusted) return is roughly nominal return minus inflation, and after-tax return further removes taxes paid, so both forces reduce the return the client truly keeps. Nominal return does not exclude taxes or inflation, so it overstates the client's real benefit. Inflation erodes rather than increases real return, and an 8% realized figure is a historical result, not an expected (forecast) return.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-performance-4", "subjectId": "recommendations", "componentId": "rec-performance", "subtopic": "Returns (risk-adjusted, time-weighted, dollar-weighted, annualized, total, holding period, IRR, expected, inflation-adjusted, after-tax)", "stem": "Portfolio A returned 12% with a standard deviation of 20%, while Portfolio B returned 9% with a standard deviation of 10%. If the risk-free rate is 3%, which portfolio delivered the better risk-adjusted performance as measured by the Sharpe ratio, and why?", "choices": ["Both are equal because they have the same total return per dollar invested", "Portfolio A, because it produced the higher raw return", "Portfolio B, because its Sharpe ratio of 0.60 exceeds Portfolio A's 0.45", "Portfolio A, because its Sharpe ratio of 0.60 exceeds Portfolio B's 0.45"], "answerIndex": 2, "explanation": "The Sharpe ratio is (portfolio return - risk-free rate) / standard deviation. Portfolio A: (12% - 3%) / 20% = 0.45. Portfolio B: (9% - 3%) / 10% = 0.60. Portfolio B earns more return per unit of risk, so it is superior on a risk-adjusted basis even though Portfolio A has the higher raw return. Choosing by raw return alone ignores the extra risk Portfolio A took to get there.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-performance-5", "subjectId": "recommendations", "componentId": "rec-performance", "subtopic": "Relevant benchmarks", "stem": "An IAR is preparing a performance report for a client whose portfolio holds exclusively small-capitalization U.S. equities. Which benchmark is the most appropriate for evaluating this portfolio's performance?", "choices": ["The MSCI EAFE Index", "The Bloomberg U.S. Aggregate Bond Index", "The S&P 500 Index", "The Russell 2000 Index"], "answerIndex": 3, "explanation": "A relevant benchmark must match the portfolio's asset class, market capitalization, and style; the Russell 2000 tracks small-cap U.S. equities and is the correct fit. The S&P 500 measures large-cap U.S. stocks, so it would misstate performance for a small-cap portfolio. The Bloomberg U.S. Aggregate is an investment-grade bond index, and the MSCI EAFE tracks developed international equities, neither of which matches domestic small-cap stocks.", "difficulty": "easy", "source": "bank"},
  {"id": "law-ia-1", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Definitions of an investment adviser (USA § 401, IAA § 202)", "stem": "Under the Uniform Securities Act, which of the following must ALL be present for a person to meet the definition of an investment adviser?", "choices": ["Advising about securities, maintaining custody, and registering with the SEC", "Being a natural person, residing in the state, and having discretionary authority", "Holding a professional license, managing client funds, and charging a performance fee", "Receiving compensation, being in the business of advising, and giving advice about securities"], "answerIndex": 3, "explanation": "The three-prong test requires that a person, for compensation, be in the business of advising others about securities — the 'ABC' test (Advice, Business, Compensation). All three prongs must be met. A professional license, custody, discretion, residency, and performance fees are not elements of the definition itself, which is why the other choices are wrong.", "difficulty": "easy", "source": "bank"},
  {"id": "law-ia-2", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Definitions of an investment adviser (USA § 401, IAA § 202)", "stem": "A registered broker-dealer offers financial advice to its brokerage customers. Under what circumstances is the broker-dealer EXCLUDED from the definition of investment adviser?", "choices": ["Only if it manages less than $100 million in assets", "Whenever its representatives hold the Series 7 license", "Whenever it is registered as a broker-dealer in the state", "Only if the advice is solely incidental to its brokerage business and it receives no special compensation for the advice"], "answerIndex": 3, "explanation": "A broker-dealer is excluded only when its advice is solely incidental to the conduct of its brokerage business AND it receives no special compensation (such as a separate advisory fee or wrap fee) for that advice. Mere BD registration, an AUM figure, or a Series 7 license does not create or preserve the exclusion; charging a separate advisory fee destroys it.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ia-3", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Notice filing requirements", "stem": "An investment adviser is registered with the SEC as a federal-covered adviser and has clients in State X, where it also maintains a branch office. What may State X require of this adviser?", "choices": ["A notice filing, including a copy of documents filed with the SEC, fees, and consent to service of process", "Nothing; federal-covered advisers are entirely beyond state reach", "Full registration with the state securities administrator", "That the adviser reduce its AUM below $100 million to qualify for state oversight"], "answerIndex": 0, "explanation": "States cannot require a federal-covered adviser to register, but under the notice-filing regime they may require it to file copies of its SEC documents (Form ADV), pay state fees, and file a consent to service of process. States also retain anti-fraud authority. Full state registration is preempted, and there is no requirement to shrink AUM.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ia-4", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Registration and post-registration requirements (books and records, Form ADV, IAA § 203/203A, USA § 201–204, SEC Rules 203A-1/2, 204-1, 204-3, NASAA model rules)", "stem": "An advisory firm currently manages $92 million but expects steady growth. It is not eligible for any exemption and does not advise investment companies. At what level of regulatory assets under management does the firm generally become required to register with the SEC as a federal-covered adviser rather than at the state level?", "choices": ["$25 million", "$100 million", "$150 million", "$50 million"], "answerIndex": 1, "explanation": "Under IAA §203A, $100 million or more in regulatory AUM (or advising a registered investment company) generally makes an adviser federal-covered and requires SEC registration. $25 million is the lower boundary below which registration is at the state level; $150 million relates to the private-fund adviser exemption, not the general SEC threshold.", "difficulty": "easy", "source": "bank"},
  {"id": "law-ia-5", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Registration and post-registration requirements (books and records, Form ADV, IAA § 203/203A, USA § 201–204, SEC Rules 203A-1/2, 204-1, 204-3, NASAA model rules)", "stem": "Which statement most accurately describes the components of Form ADV?", "choices": ["Part 1 is the client brochure; Part 2 contains regulatory check-the-box data", "Part 1 contains regulatory data; Part 2A is the client brochure and Part 2B is the brochure supplement for individual advisory personnel", "Part 1 is filed only with the states; Part 2 is filed only with the SEC", "Part 2A is filed only by federal-covered advisers; Part 2B only by state-registered advisers"], "answerIndex": 1, "explanation": "Form ADV Part 1 captures regulatory, check-the-box information about the firm; Part 2A is the plain-English client 'brochure'; and Part 2B is the brochure supplement disclosing information about the individual advisory personnel who provide advice. Choice A reverses Parts 1 and 2, and the filing-jurisdiction distinctions in C and D are fabricated — both parts are filed via IARD regardless of jurisdiction.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ia-6", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Registration and post-registration requirements (books and records, Form ADV, IAA § 203/203A, USA § 201–204, SEC Rules 203A-1/2, 204-1, 204-3, NASAA model rules)", "stem": "A state-registered investment adviser has a fiscal year ending December 31. Regarding annual delivery of its brochure to existing clients, which requirement applies?", "choices": ["It must deliver the brochure only upon a client's written request", "It must deliver an updated brochure or a summary of material changes within 120 days of fiscal year-end", "It must deliver a full updated brochure within 30 days of fiscal year-end", "It has no annual delivery obligation once the initial brochure is delivered"], "answerIndex": 1, "explanation": "Advisers must deliver, within 120 days of the end of the fiscal year, either an updated brochure that includes a summary of material changes or a summary of material changes accompanied by an offer to provide the full brochure. The 30-day figure is wrong, and the obligation is annual and ongoing, not one-time or request-only.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ia-7", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Registration and post-registration requirements (books and records, Form ADV, IAA § 203/203A, USA § 201–204, SEC Rules 203A-1/2, 204-1, 204-3, NASAA model rules)", "stem": "An investment adviser files a complete application for registration with a state securities administrator on March 1. No stop order is issued and no proceeding is pending. When does the registration generally become effective?", "choices": ["On the first business day of the following calendar quarter", "Immediately upon filing on March 1", "Only after the administrator affirmatively approves it in writing", "At noon on the 30th day after filing"], "answerIndex": 3, "explanation": "Under the Uniform Securities Act, an application for registration becomes effective at noon on the 30th day after filing, provided no stop order is in effect and no proceeding is pending. Registration is not effective immediately, is not tied to calendar quarters, and does not require an affirmative written approval — it takes effect automatically absent administrator action.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ia-8", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Exemptions for exempt reporting advisers and private fund advisers", "stem": "An adviser manages only private funds and has $135 million of private-fund assets under management in the United States, relying on the private-fund adviser exemption. Which statement best describes its obligations?", "choices": ["It must register with each state in which a fund investor resides", "It is fully exempt and files nothing with any regulator", "As an exempt reporting adviser, it must still file specified portions of Form ADV Part 1, though it does not fully register", "It must fully register with the SEC as an investment adviser"], "answerIndex": 2, "explanation": "An adviser advising solely private funds with less than $150 million in U.S. private-fund AUM qualifies as an exempt reporting adviser (ERA). ERAs do not fully register but MUST file certain items of Form ADV Part 1 and remain subject to anti-fraud rules. Full SEC registration would be required only if AUM reached $150 million or more; the adviser is neither wholly exempt from filing nor required to register in each investor's state.", "difficulty": "hard", "source": "bank"},
  {"id": "law-ia-9", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Exemptions for exempt reporting advisers and private fund advisers", "stem": "Which of the following advisers would most likely qualify as an exempt reporting adviser rather than being required to fully register?", "choices": ["An adviser managing $500 million in separately managed accounts for retail clients", "An adviser with $60 million in AUM advising individual retirement accounts", "An adviser to a registered open-end investment company", "An adviser that acts solely as an adviser to one or more venture capital funds"], "answerIndex": 3, "explanation": "An adviser that advises solely one or more venture capital funds qualifies for the venture-capital-fund adviser exemption and is treated as an exempt reporting adviser, filing only portions of Form ADV Part 1. A $500 million retail-account adviser and an adviser to a registered investment company must register with the SEC; a $60 million retail adviser is a mid-sized/state-registered adviser, not an ERA.", "difficulty": "hard", "source": "bank"},
  {"id": "law-ia-10", "subjectId": "laws", "componentId": "law-ia", "subtopic": "IAR supervision", "stem": "Under the NASAA model rule addressing supervision, an investment adviser that employs several investment adviser representatives is required to do which of the following?", "choices": ["Establish, maintain, and enforce reasonable written supervisory procedures and designate a supervisor responsible for their enforcement", "Register each IAR directly with the SEC in addition to the state", "Personally pre-approve every securities transaction recommended by each IAR before it is executed", "Obtain a separate surety bond for each IAR regardless of the firm's net worth"], "answerIndex": 0, "explanation": "The supervision model rule requires the firm to establish, maintain, and enforce reasonable written supervisory procedures and to designate a qualified person to enforce them; failure to reasonably supervise is itself a violation. Pre-approving every trade is not required, a per-IAR surety bond is not a supervision requirement, and IARs register at the state level (with their firm's registration handled separately), not individually with the SEC.", "difficulty": "medium", "source": "bank"},
  {"id": "law-iar-1", "subjectId": "laws", "componentId": "law-iar", "subtopic": "Definition of an IAR (USA § 401, SEC Rule 203A-3)", "stem": "Which of the following individuals would MOST likely be required to register as an investment adviser representative?", "choices": ["An employee who solicits new advisory clients for the firm in exchange for compensation", "The firm's outside independent auditor who reviews the books annually", "A software vendor who licenses portfolio-accounting software to the firm", "The receptionist at an advisory firm who schedules client meetings and answers phones"], "answerIndex": 0, "explanation": "An IAR is a natural person who, among other things, solicits, offers, or negotiates for the sale of advisory services — so a paid solicitor of advisory clients must register even if he gives no specific securities advice. The receptionist performs purely clerical/administrative duties and is expressly excluded. An outside auditor and a software vendor are not associated persons providing advice, soliciting clients, or managing accounts, so neither is an IAR.", "difficulty": "easy", "source": "bank"},
  {"id": "law-iar-2", "subjectId": "laws", "componentId": "law-iar", "subtopic": "Definition of an IAR (USA § 401, SEC Rule 203A-3)", "stem": "Which statement about who can be an investment adviser representative is CORRECT?", "choices": ["Both individuals and entities may register as IARs depending on their function", "Only a natural person can be an IAR; a firm itself is never an IAR", "An IAR must personally own at least a 5% equity interest in the adviser", "Any employee of an advisory firm is automatically an IAR"], "answerIndex": 1, "explanation": "By definition an IAR is a natural person associated with an investment adviser — an entity or firm can be the adviser but can never be an IAR. Not every employee qualifies, because purely clerical and administrative staff are excluded. There is no ownership-percentage requirement to be an IAR, so the equity option is fabricated.", "difficulty": "easy", "source": "bank"},
  {"id": "law-iar-3", "subjectId": "laws", "componentId": "law-iar", "subtopic": "Definition of an IAR (USA § 401, SEC Rule 203A-3)", "stem": "An IAR works out of an office in State A for a federal-covered investment adviser that manages $600 million and is registered with the SEC. Where, if anywhere, must this individual register?", "choices": ["With the SEC only, because the employing adviser is federal-covered", "With State A, because that is where the IAR maintains a place of business", "Nowhere, because IARs of federal-covered advisers are exempt from registration", "With every state in which the adviser has any clients, regardless of office location"], "answerIndex": 1, "explanation": "Registration of an IAR is done at the state level and is triggered by maintaining a place of business in that state — even when the employing adviser is federal-covered and registered only with the SEC. The SEC does not register individual IARs, so option one is wrong. IARs of federal-covered advisers are not blanket-exempt; and the trigger is a place of business, not merely having clients in a state, so the last option is incorrect.", "difficulty": "medium", "source": "bank"},
  {"id": "law-iar-4", "subjectId": "laws", "componentId": "law-iar", "subtopic": "Post-registration: keeping Form U4 current (USA §§ 201–204; IARD/CRD amendments)", "stem": "An IAR pleads guilty to a misdemeanor involving misuse of client funds. Regarding her Form U4, which action is required?", "choices": ["The event need only be disclosed at the next annual renewal of registration", "The IAR must surrender her registration and reapply from the beginning", "The U4 must be amended to disclose the event, generally within 30 days", "No amendment is needed because only felonies are reportable on Form U4"], "answerIndex": 2, "explanation": "Material changes to information on Form U4 — including new disciplinary or criminal disclosure events — must be reported by filing an amendment, generally within 30 days. Certain misdemeanors involving investments or dishonesty (such as misuse of client funds) are reportable, so it is not true that only felonies matter. Disclosure cannot wait for the annual renewal, and there is no rule requiring the IAR to surrender the registration and reapply merely to report the event.", "difficulty": "medium", "source": "bank"},
  {"id": "law-iar-5", "subjectId": "laws", "componentId": "law-iar", "subtopic": "Post-registration: effectiveness tied to association (USA §§ 201–204; Form U4)", "stem": "An IAR leaves Firm X on the last day of the month to begin work at Firm Y. Which statement about his registration status is CORRECT?", "choices": ["The Administrator must re-test the IAR before he may associate with Firm Y", "His IAR registration continues independently and can be carried to Firm Y automatically", "His registration effectively lapses when he leaves Firm X, and a new/transfer U4 must be filed to associate with Firm Y", "Once granted, an IAR registration is permanent and never needs to be re-established"], "answerIndex": 2, "explanation": "An IAR's registration is effective only while the person is associated with a registered or federal-covered adviser; it is not portable and effectively lapses when the association with Firm X ends. To work for Firm Y, a Form U4 must be filed to establish the new association. Registration is therefore not permanent and standalone, and there is no automatic requirement to re-take the qualifying exam simply because of a firm change (exam waivers/two-year windows aside).", "difficulty": "medium", "source": "bank"},
  {"id": "law-iar-6", "subjectId": "laws", "componentId": "law-iar", "subtopic": "Prohibited representations concerning registration (USA § 206)", "stem": "In discussing his qualifications with a prospect, a state-registered IAR says, 'The fact that the Administrator has registered me means the state has approved my abilities and verified everything on my record.' Under the Uniform Securities Act, this statement is:", "choices": ["Prohibited only if the IAR charges performance-based fees", "Permitted, provided the IAR also gives the prospect a copy of the Form U4", "Permitted, because registration does constitute an official endorsement of the IAR's competence", "Prohibited, because it is unlawful to represent that registration implies the Administrator's approval or a finding as to the accuracy of the disclosures"], "answerIndex": 3, "explanation": "USA § 206 expressly makes it unlawful to represent that registration means the Administrator has approved or passed on the merits, qualifications, or the accuracy of any statement in the filing. Registration is a licensing/disclosure requirement, not an endorsement, so it is never a permitted representation regardless of whether a U4 copy is provided. The prohibition applies to all registrants and has nothing to do with whether performance-based fees are charged.", "difficulty": "hard", "source": "bank"},
  {"id": "law-bd-1", "subjectId": "laws", "componentId": "law-bd", "subtopic": "Definition of a broker-dealer (USA § 401)", "stem": "Under the Uniform Securities Act, which of the following is specifically EXCLUDED from the definition of a broker-dealer?", "choices": ["A firm that maintains an office in the state and effects securities transactions for retail customers", "A person effecting transactions in securities for the accounts of others as a business", "A market maker quoting securities for its own account", "A bank or trust company effecting securities transactions"], "answerIndex": 3, "explanation": "USA § 401 expressly excludes agents, issuers, and banks/savings institutions/trust companies from the broker-dealer definition. A bank is therefore not a broker-dealer under the USA. The other choices describe persons who ARE broker-dealers: effecting transactions for others' accounts as a business is the core definition, a firm with an in-state office serving retail customers must register, and a market maker acts as a dealer for its own account.", "difficulty": "easy", "source": "bank"},
  {"id": "law-bd-2", "subjectId": "laws", "componentId": "law-bd", "subtopic": "Registration and post-registration requirements", "stem": "A broker-dealer with no place of business in State X has clients who are longtime residents of State Y. Several of those existing clients travel to State X for a two-week vacation, during which the firm continues to service their accounts. With respect to State X, the broker-dealer:", "choices": ["Is exempt only if State X and State Y share a reciprocal registration agreement", "Must register in State X only if it executed more than a de minimis number of trades", "Must register in State X because it transacted business with persons physically present there", "Is not a broker-dealer in State X because it has no place of business there and dealt only with existing customers temporarily present"], "answerIndex": 3, "explanation": "This is the classic 'snowbird' exclusion: a person with no place of business in a state is not a broker-dealer there if its only clients are existing customers who are not residents but are temporarily present in the state. Because the firm has no office in State X and served only pre-existing, non-resident clients, it is excluded and need not register. There is no de minimis trade count or reciprocal-agreement requirement driving this exclusion.", "difficulty": "medium", "source": "bank"},
  {"id": "law-bd-3", "subjectId": "laws", "componentId": "law-bd", "subtopic": "Definition of an underwriter (SA § 2)", "stem": "Which of the following persons would be considered an underwriter under Section 2(a)(11) of the Securities Act of 1933?", "choices": ["An investor who buys registered shares in the secondary market and later resells them at a profit", "A dealer that resells outstanding securities and earns only the usual and customary dealer's commission", "A firm that purchases newly issued securities directly from the issuer with a view to distributing them to the public", "A transfer agent that records changes in the ownership of an issuer's securities"], "answerIndex": 2, "explanation": "Under SA § 2(a)(11), an underwriter is a person who purchases from an issuer with a view to distribution, or who offers or sells for an issuer in connection with a distribution. Buying newly issued securities from the issuer to distribute them to the public fits squarely. A person earning only the usual and customary seller's or dealer's commission is expressly excluded, which eliminates the reselling dealer and the ordinary secondary-market investor. A transfer agent performs recordkeeping and is not participating in a distribution for the issuer.", "difficulty": "medium", "source": "bank"},
  {"id": "law-bd-4", "subjectId": "laws", "componentId": "law-bd", "subtopic": "Definition of a market maker, associated person (SEA § 3)", "stem": "Which statement best distinguishes a market maker from an associated person of a broker-dealer as those terms are used under the Securities Exchange Act of 1934?", "choices": ["A market maker holds itself out as buying and selling a security for its own account on a continuous basis, while an associated person is generally a partner, officer, director, or employee of the broker-dealer", "A market maker is always an individual, while an associated person is always an entity", "A market maker never takes principal positions, while an associated person always trades as principal", "A market maker is exempt from all registration, while an associated person can never be registered"], "answerIndex": 0, "explanation": "A market maker stands ready to buy and sell a particular security for its own (dealer/principal) account on a regular and continuous basis at quoted prices, providing liquidity. An associated person under SEA § 3(a)(18) is broadly any partner, officer, director, branch manager, or employee of a BD (plus controlling/controlled persons). The other options invert the facts: a market maker takes principal positions rather than avoiding them, is typically a firm not necessarily an individual, and is not simply 'exempt from all registration.'", "difficulty": "medium", "source": "bank"},
  {"id": "law-bd-5", "subjectId": "laws", "componentId": "law-bd", "subtopic": "Registration and post-registration requirements", "stem": "A broker-dealer's state registration became effective on March 1. Absent any withdrawal, revocation, or change in status, when does that registration expire, and what is the effect on the firm's agents if the firm's registration is later revoked?", "choices": ["It expires on the following March 1 (its one-year anniversary), and the firm's agents may continue to transact business independently", "It never expires once effective, and its agents automatically become registered broker-dealers upon revocation", "It expires on December 31 of that same year, and the firm's agents may no longer transact business while the firm's registration is not effective", "It expires only when the firm files a Form BDW, and revocation of the firm has no effect on its agents"], "answerIndex": 2, "explanation": "Under the USA, broker-dealer registrations expire on December 31 each year and must be renewed, regardless of the original effective date, so a March 1 effective date still expires that December 31. An agent's registration is tied to an effective broker-dealer; if the firm's registration is revoked (or otherwise not effective), its agents cannot transact business. The distractors misstate both the fixed year-end expiration and the dependency of agents on the firm's active registration.", "difficulty": "hard", "source": "bank"},
  {"id": "law-bda-1", "subjectId": "laws", "componentId": "law-bda", "subtopic": "Definition of a broker-dealer agent (USA § 401)", "stem": "Which of the following persons would MOST likely fall within the definition of an \"agent\" under Section 401 of the Uniform Securities Act?", "choices": ["An individual representing an issuer solely in an exempt transaction with an institutional buyer", "A receptionist at a broker-dealer who greets clients and schedules appointments", "A broker-dealer organized as a corporation that executes trades for retail customers", "An individual who represents a broker-dealer in soliciting the sale of securities to the public"], "answerIndex": 3, "explanation": "Under § 401, an agent is an individual (natural person) who represents a broker-dealer or issuer in effecting or attempting to effect securities transactions, so the individual soliciting sales for a broker-dealer is an agent. A broker-dealer organized as a corporation is an entity, and an entity is never an agent. A receptionist who does not solicit or effect transactions is excluded from the definition. An individual representing an issuer solely in an exempt transaction is specifically excluded from the agent definition.", "difficulty": "easy", "source": "bank"},
  {"id": "law-bda-2", "subjectId": "laws", "componentId": "law-bda", "subtopic": "Definition of a broker-dealer agent (USA § 401)", "stem": "An individual is registered as an agent of Firm A in State X. She resigns and, one week later, begins soliciting the same securities on behalf of Firm B in State X. Under the Uniform Securities Act, what is required for her to lawfully transact business for Firm B?", "choices": ["She may continue transacting business for up to 90 days under her prior registration before any filing is required", "Only Firm A must file a notice; her registration continues uninterrupted at Firm B", "Nothing further, because her existing registration transfers automatically with her to Firm B", "She, Firm A, and Firm B must all notify the Administrator, and she must be registered as an agent of Firm B"], "answerIndex": 3, "explanation": "An agent's registration is tied to a specific employing broker-dealer and is not effective during any period the agent is not associated with a registered broker-dealer; it does not transfer automatically. When an agent changes firms, the agent, the former employer, and the new employer must all promptly notify the Administrator, and the agent must be registered as an agent of the new firm before transacting business. There is no automatic transfer and no 90-day grace period permitting solicitation under the old registration.", "difficulty": "medium", "source": "bank"},
  {"id": "law-bda-3", "subjectId": "laws", "componentId": "law-bda", "subtopic": "Registration and post-registration (Form U4)", "stem": "An agent registered on Form U4 is arrested and charged with a felony involving theft. Regarding the agent's post-registration obligations, which statement is correct?", "choices": ["The charge need only be disclosed at the agent's next annual registration renewal", "No disclosure is required unless and until the agent is actually convicted", "The agent must file an amended Form U4 to report the charge, generally within 30 days", "Only the employing broker-dealer, not the agent, has any duty to update the record"], "answerIndex": 2, "explanation": "Form U4 must be kept current through prompt amendments, generally within 30 days, whenever the information becomes materially inaccurate - and a felony charge is a reportable disclosure event, not just a conviction. Waiting for a conviction, waiting for annual renewal, or assuming only the firm is responsible all violate the ongoing duty to keep the U4 accurate. The disclosure obligation is triggered by the charge itself.", "difficulty": "medium", "source": "bank"},
  {"id": "law-bda-4", "subjectId": "laws", "componentId": "law-bda", "subtopic": "Registration and post-registration (Form U4)", "stem": "Which of the following is an accurate statement about registering as a broker-dealer agent and the Form U4 under the Uniform Securities Act?", "choices": ["An agent may lawfully continue transacting business after the employing broker-dealer's registration is revoked, provided the agent's own U4 remains active", "The Form U4 application includes the applicant's consent to service of process and requires disclosure of criminal, regulatory, and financial history", "Filing Form U4 automatically makes the agent's registration effective the moment it is submitted to CRD, regardless of exam status", "Passing a qualification examination permanently satisfies the requirement, so no U4 disclosures need to be maintained afterward"], "answerIndex": 1, "explanation": "The Form U4 application includes the applicant's consent to service of process and requires disclosure of criminal, regulatory, civil-judicial, financial, and customer-complaint history. Registration is not automatically effective on submission - it requires the application, fees, and passing the appropriate exam(s), and the Administrator makes it effective. An agent cannot transact business for a broker-dealer whose registration has been revoked, because an agent's registration is not effective absent association with a registered broker-dealer. Passing an exam does not eliminate the ongoing duty to keep U4 disclosures current.", "difficulty": "hard", "source": "bank"},
  {"id": "law-securities-1", "subjectId": "laws", "componentId": "law-securities", "subtopic": "Definitions of security and issuer (USA § 401)", "stem": "A promoter sells interests in a citrus grove development. Buyers purchase individual plots but simultaneously sign a service contract under which the promoter's affiliated company cultivates, harvests, and markets the fruit, then distributes the net proceeds to the plot owners, who take no active role. Under the Uniform Securities Act, these arrangements are MOST likely to be treated as:", "choices": ["Real estate interests outside the Administrator's jurisdiction", "Exempt transactions not subject to antifraud rules", "Investment contracts, and therefore securities", "Commodity contracts exempt from the Act"], "answerIndex": 2, "explanation": "This is the classic Howey fact pattern: an investment of money in a common enterprise with profits expected solely from the efforts of a third party makes the arrangement an investment contract, which USA § 401 includes within the definition of 'security.' It is not merely passive real estate because the profit depends on the promoter's managerial efforts, not the buyer's. Commodity contracts on the fruit itself would be different, and even an exempt transaction would still be subject to antifraud provisions.", "difficulty": "medium", "source": "bank"},
  {"id": "law-securities-2", "subjectId": "laws", "componentId": "law-securities", "subtopic": "Definitions of security and issuer (USA § 401)", "stem": "Which of the following is NOT included within the definition of a 'security' under Uniform Securities Act § 401?", "choices": ["A note evidencing a corporate debt", "An interest in an oil and gas drilling program", "A collateral trust certificate", "A fixed, guaranteed annuity contract issued by an insurance company"], "answerIndex": 3, "explanation": "A fixed annuity that guarantees a stated dollar payout places the investment risk on the insurer, not the purchaser, so it is treated as an insurance product and is excluded from the definition of a security (a variable annuity, by contrast, IS a security). Oil and gas program interests, collateral trust certificates, and corporate notes are all expressly within the § 401 definition. The tempting trap is assuming anything sold by an insurance company is insurance, but variable products carrying investment risk are securities.", "difficulty": "easy", "source": "bank"},
  {"id": "law-securities-3", "subjectId": "laws", "componentId": "law-securities", "subtopic": "Securities registration process (SA § 5, § 18, Reg D, USA § 301-305, § 402)", "stem": "A company's securities are listed on the New York Stock Exchange. The issuer plans to sell additional shares of the same class to the public in several states. Regarding state-level registration of these shares, which statement is correct?", "choices": ["The shares are federal covered securities, so the states are preempted from requiring them to be registered", "The issuer must register by coordination in each state where sales are made", "Because the shares are exchange-listed, no federal or state filing of any kind is required", "The states may require full registration by qualification before any sales occur"], "answerIndex": 0, "explanation": "Securities listed on the NYSE (and other qualifying national exchanges), together with securities of the same issuer that are equal or senior to them, are 'federal covered securities' under Securities Act § 18 / NSMIA. States are preempted from requiring their registration, so both full registration by qualification and registration by coordination are prohibited state demands. 'No filing of any kind' is also wrong: the additional shares are being sold to the public and must still be registered federally under the Securities Act of 1933. (Unlike mutual fund shares or Rule 506 offerings, exchange-listed securities are generally not even subject to a state notice filing.) The Administrator does, however, retain antifraud authority.", "difficulty": "medium", "source": "bank"},
  {"id": "law-securities-4", "subjectId": "laws", "componentId": "law-securities", "subtopic": "Securities registration process (SA § 5, § 18, Reg D, USA § 301-305, § 402)", "stem": "An issuer is registering a new securities offering with the SEC under the Securities Act of 1933 and wants the state registration to become effective at the same time the federal registration statement is declared effective. Which state registration method should the issuer use?", "choices": ["Registration by notification", "Registration by qualification", "Registration by coordination", "Notice filing under NSMIA"], "answerIndex": 2, "explanation": "Registration by coordination (USA § 303) is designed for offerings simultaneously registered under the Securities Act of 1933; it generally becomes effective at the same moment the federal registration becomes effective, provided state conditions are met. Qualification (§ 304) is used when there is no federal registration and becomes effective only when the Administrator orders. Notification is for certain established issuers, and a notice filing applies to federal covered securities that are not being state-registered at all.", "difficulty": "medium", "source": "bank"},
  {"id": "law-securities-5", "subjectId": "laws", "componentId": "law-securities", "subtopic": "Definitions of investment companies (ICA §§ 3-5)", "stem": "An investment company continuously offers new redeemable shares to the public and stands ready to redeem outstanding shares at net asset value. Under the Investment Company Act of 1940, this entity is classified as a:", "choices": ["Face-amount certificate company", "Open-end management company", "Unit investment trust", "Closed-end management company"], "answerIndex": 1, "explanation": "An open-end management company (a mutual fund) continuously issues new shares and redeems them at NAV, which is the defining feature described. A closed-end fund issues a fixed number of shares that then trade in the secondary market, often at a premium or discount to NAV, and does not continuously redeem. A UIT holds a fixed portfolio and issues redeemable units but is not a 'management' company, and a face-amount certificate company sells certificates promising a fixed sum at a future date.", "difficulty": "easy", "source": "bank"},
  {"id": "law-securities-6", "subjectId": "laws", "componentId": "law-securities", "subtopic": "State antifraud authority", "stem": "A security was sold in a transaction that was properly exempt from state registration. An investor later discovers that the seller knowingly made materially false statements about the issuer's financial condition to induce the purchase. Which of the following BEST describes the state Administrator's authority?", "choices": ["The Administrator may act only if the security was also a federal covered security", "The Administrator must refer the matter exclusively to the SEC because no state registration applied", "The Administrator has no jurisdiction because the transaction was exempt from registration", "The Administrator retains full antifraud authority and may investigate and sanction the seller"], "answerIndex": 3, "explanation": "An exemption from registration never exempts a person from the antifraud provisions of the Uniform Securities Act; the Administrator retains authority over fraud in connection with the offer or sale of ANY security, exempt or not, federal covered or not. Thus jurisdiction does not disappear because the transaction was exempt, is not limited to federal covered securities, and need not be handed off to the SEC. This preservation of antifraud power is a core USA principle that survives even NSMIA preemption of registration.", "difficulty": "hard", "source": "bank"},
  {"id": "law-remedies-1", "subjectId": "laws", "componentId": "law-remedies", "subtopic": "Authority of the state securities administrator (USA § 204, § 306, § 406, § 407, § 412)", "stem": "A state Administrator is investigating suspected fraudulent advisory practices that appear to have involved conduct occurring partly in a neighboring state. Under the investigative authority granted by the Uniform Securities Act, the Administrator may:", "choices": ["Conduct investigations within or outside the state, subpoena witnesses, books, and records, and administer oaths", "Investigate only the conduct that physically occurred within the Administrator's own state", "Compel testimony only after first obtaining written authorization from the SEC", "Require witnesses to testify but not compel the production of documents without a separate court order"], "answerIndex": 0, "explanation": "Under its investigative powers, the Administrator may conduct investigations inside or outside its state, subpoena witnesses and records, administer oaths, and require sworn statements. Limiting investigations to conduct physically within the state is wrong because jurisdiction reaches conduct with an in-state nexus and investigations may occur anywhere. SEC pre-authorization is not required for a state investigation, and the subpoena power itself compels documents—no separate court order is needed to obtain them.", "difficulty": "easy", "source": "bank"},
  {"id": "law-remedies-2", "subjectId": "laws", "componentId": "law-remedies", "subtopic": "Authority of the state securities administrator (USA § 204, § 306, § 406, § 407, § 412)", "stem": "A state Administrator has summarily suspended an investment adviser's registration, effective immediately, pending a final determination in a fraud investigation. Which statement correctly describes the adviser's procedural rights?", "choices": ["The adviser is entitled to a hearing if it requests one in writing, and the Administrator must hold that hearing within 15 days of receiving the request", "The adviser's only recourse is to appeal the suspension to the SEC within 60 days", "The summary suspension is invalid because the Administrator must always hold a hearing before any suspension can take effect", "The adviser must file suit in federal court within 30 days or the suspension becomes permanent"], "answerIndex": 0, "explanation": "The Administrator may issue a summary order that takes effect immediately, but the affected person is entitled to a hearing, which the Administrator must convene within 15 days after receiving a written request. The claim that a hearing must always precede a suspension is wrong—summary (immediate) orders are expressly permitted. Review of state Administrator orders is not an SEC appeal, and judicial review is sought in the appropriate state court (within 60 days of a final order), not a 30-day federal filing.", "difficulty": "medium", "source": "bank"},
  {"id": "law-remedies-3", "subjectId": "laws", "componentId": "law-remedies", "subtopic": "Administrative actions (USA § 408)", "stem": "Which statement about a state Administrator's cease and desist authority under the Uniform Securities Act is correct?", "choices": ["The Administrator may issue a cease and desist order with or without a prior hearing", "A cease and desist order may be issued only after a court has formally found a violation", "The Administrator must first obtain an injunction from a court before ordering a person to stop a violation", "A cease and desist order automatically carries a prison sentence if it is disobeyed"], "answerIndex": 0, "explanation": "The Administrator has statutory power to issue cease and desist orders on its own authority, and it may do so with or without a prior hearing. It does not need a prior court finding or an injunction—the injunction is a separate, court-issued remedy the Administrator may pursue in addition to a cease and desist order. Disobeying the order does not trigger an automatic prison sentence; the Administrator would seek enforcement through the courts, and criminal penalties require a separate willful-violation prosecution.", "difficulty": "medium", "source": "bank"},
  {"id": "law-remedies-4", "subjectId": "laws", "componentId": "law-remedies", "subtopic": "Other penalties and liabilities (USA § 409, § 410, § 411)", "stem": "An investor purchased securities for $20,000 in a transaction that violated the Uniform Securities Act. Over the following year the investor received $600 in dividends and still owns the securities. The Administrator's stated interest rate is 8%, or $1,600 for the year. Ignoring court costs and attorney's fees, how much may the investor recover upon tendering the securities back to the seller?", "choices": ["$19,000", "$22,200", "$20,000", "$21,000"], "answerIndex": 3, "explanation": "Civil recovery for a buyer who still owns the security equals consideration paid plus interest, minus income received on the security: $20,000 + $1,600 − $600 = $21,000 (plus costs and attorney's fees, upon tender). $22,200 incorrectly ADDS the $600 of income instead of subtracting it. $19,000 wrongly subtracts the interest and adds the income. $20,000 ignores both the interest owed and the income received, capturing only the principal.", "difficulty": "hard", "source": "bank"},
  {"id": "law-remedies-5", "subjectId": "laws", "componentId": "law-remedies", "subtopic": "Other penalties and liabilities (USA § 409, § 410, § 411)", "stem": "Under the Uniform Securities Act, a person convicted of a willful violation of the Act is subject to which maximum criminal penalty?", "choices": ["A $10,000 fine and/or 5 years imprisonment", "A $5,000 fine and/or 5 years imprisonment", "A $5,000 fine and/or 3 years imprisonment", "A $10,000 fine and/or 3 years imprisonment"], "answerIndex": 2, "explanation": "The USA sets the maximum criminal penalty for a willful violation at a $5,000 fine and/or 3 years in prison (the '5 and 3' rule). The options citing a $10,000 fine overstate the fine, and the options citing 5 years of imprisonment confuse the 5-year criminal statute of limitations with the maximum prison term. Note also that no imprisonment is imposed if the defendant proves he had no knowledge of the rule or order.", "difficulty": "easy", "source": "bank"},
  {"id": "law-comms-1", "subjectId": "laws", "componentId": "law-comms", "subtopic": "Disclosures", "stem": "A federal-covered investment adviser is onboarding a new retail client. Under the SEC brochure rule, when must the adviser deliver its Form ADV Part 2A brochure?", "choices": ["Within 48 hours after the first trade in the account", "Only upon the client's written request", "Within 120 days after the client's account is opened", "At or before the time the client enters into the advisory contract"], "answerIndex": 3, "explanation": "The brochure rule requires the initial brochure to be delivered no later than the time the client enters into the advisory contract (earlier delivery is fine). The 120-day period is the annual delivery obligation measured from the adviser's fiscal year-end, not from account opening. Delivery is not triggered by a trade, and it is required proactively, not merely on the client's request.", "difficulty": "medium", "source": "bank"},
  {"id": "law-comms-2", "subjectId": "laws", "componentId": "law-comms", "subtopic": "Unlawful representations concerning registrations", "stem": "Which statement by a state-registered investment adviser to a prospect violates the Uniform Securities Act's prohibition on representations concerning registration?", "choices": ["\"I am currently registered as an investment adviser in this state.\"", "\"My registration means the Administrator has reviewed and approved the merits and quality of my advisory services.\"", "\"You are welcome to review my Form ADV before deciding to hire me.\"", "\"Registration does not imply that the Administrator has approved or endorsed my services.\""], "answerIndex": 1, "explanation": "It is unlawful to represent that registration means the Administrator (or SEC) has approved, endorsed, or passed upon the merits or qualifications of the adviser. Truthfully stating that one is registered, disclaiming that registration implies approval, and offering the Form ADV are all permissible. The violation is equating registration with a government seal of approval.", "difficulty": "easy", "source": "bank"},
  {"id": "law-comms-3", "subjectId": "laws", "componentId": "law-comms", "subtopic": "Performance guarantees", "stem": "An IAR tells a prospective client, \"Based on my proprietary model, I guarantee your portfolio will not lose money next year and will earn at least 8%.\" This statement is best characterized as:", "choices": ["Permitted, as long as the client qualifies as an accredited investor", "A prohibited and unethical business practice, because an adviser may not guarantee returns or guarantee against loss", "Permitted, because the IAR reasonably believes the projection based on backtested data", "Permitted, provided the guarantee is put in writing and signed by both parties"], "answerIndex": 1, "explanation": "Guaranteeing a specific return or guaranteeing against loss is a prohibited/unethical practice for investment advisers, no matter how the adviser justifies it. Putting the guarantee in writing, relying on backtesting, or the client's accredited status does not cure the violation — client consent cannot authorize a prohibited practice. The core problem is the guarantee itself.", "difficulty": "medium", "source": "bank"},
  {"id": "law-comms-4", "subjectId": "laws", "componentId": "law-comms", "subtopic": "Client contracts (USA § 102, IAA § 205, NASAA model rule)", "stem": "Under Investment Advisers Act § 205 and SEC Rule 205-3, an adviser may charge a performance-based fee (a share of capital gains or appreciation) only to a \"qualified client.\" A natural person generally meets that definition if they:", "choices": ["Have at least approximately $1.1 million in assets under management with the adviser or a net worth exceeding approximately $2.2 million", "Have annual income exceeding $200,000 in each of the last two years", "Have been advised by the firm for at least five continuous years", "Sign a written waiver acknowledging the added risk of a performance fee"], "answerIndex": 0, "explanation": "A qualified client is generally one with roughly $1.1 million under management with the adviser or a net worth over roughly $2.2 million (thresholds are periodically inflation-adjusted). The $200,000 income figure is the accredited-investor test, which does not by itself make someone a qualified client. Length of the advisory relationship is irrelevant, and a client cannot simply waive into eligibility.", "difficulty": "hard", "source": "bank"},
  {"id": "law-comms-5", "subjectId": "laws", "componentId": "law-comms", "subtopic": "Correspondence and advertising (social media, email, website, USA §§ 102 and 403, SEC Rules 206(4)-1, 204-2)", "stem": "Under the amended SEC Marketing Rule (Rule 206(4)-1), which statement about using client testimonials in an adviser's advertising — including on its website and social media — is correct?", "choices": ["Testimonials are permitted if the advertisement clearly and prominently discloses whether the person was compensated and any material conflicts of interest", "Testimonials are strictly prohibited in all investment adviser advertising", "Testimonials are permitted only in one-on-one oral conversations, never in writing or online", "Testimonials may be used only after the SEC pre-approves each advertisement"], "answerIndex": 0, "explanation": "The amended Marketing Rule permits testimonials and endorsements provided the ad clearly and prominently discloses whether the promoter was compensated and any material conflicts, with required oversight and written agreements. This reversed the old blanket prohibition, so 'strictly prohibited' is outdated. The rule is not limited to oral communications, and the SEC does not pre-approve advertisements.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ethics-1", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Compensation (fees, commissions, performance-based fees, pay-to-play, soft dollars, SEA § 28(e), SEC Rule 206(4)-5, MSRB Rule G-37)", "stem": "An investment adviser wants to charge a client a fee equal to 20% of any capital gains above a benchmark. Under the Investment Advisers Act, this performance-based fee arrangement is generally permitted only if the client is a:", "choices": ["Accredited investor with $200,000 in annual income", "Qualified client meeting the required assets-under-management or net-worth thresholds", "Client who signs a written waiver of the adviser's fiduciary duty", "Non-U.S. resident exempt from SEC jurisdiction"], "answerIndex": 1, "explanation": "Performance-based fees are generally prohibited unless the client is a 'qualified client' (roughly $1.1M managed by the adviser or $2.2M net worth excluding primary residence). Accredited-investor status (choice A) uses lower thresholds and is not the test for performance fees. A fiduciary duty cannot be waived (choice C), and residency (choice D) does not create the exemption.", "difficulty": "easy", "source": "bank"},
  {"id": "law-ethics-2", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Compensation (fees, commissions, performance-based fees, pay-to-play, soft dollars, SEA § 28(e), SEC Rule 206(4)-5, MSRB Rule G-37)", "stem": "An adviser directs client brokerage to a firm that charges slightly higher commissions in exchange for products and services. Which of the following would fall OUTSIDE the soft-dollar safe harbor of Section 28(e) of the Securities Exchange Act of 1934?", "choices": ["Third-party research reports on specific issuers", "Software that analyzes portfolio attribution and securities", "Payment of the adviser's office rent and employee salaries", "Seminars on trading strategy that assist investment decisions"], "answerIndex": 2, "explanation": "The Section 28(e) safe harbor covers only brokerage and research that lawfully and appropriately assist the adviser in making investment decisions. Research reports, analytical software, and educational seminars used in the decision process (A, B, D) can qualify. Overhead such as office rent and salaries (C) is a general operating expense and is never eligible, so it falls outside the safe harbor.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ethics-3", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Compensation (fees, commissions, performance-based fees, pay-to-play, soft dollars, SEA § 28(e), SEC Rule 206(4)-5, MSRB Rule G-37)", "stem": "A covered associate of a registered investment adviser makes a $1,000 political contribution to a state treasurer who oversees the awarding of state pension advisory contracts, and the associate is not entitled to vote for that official. Under SEC Rule 206(4)-5, the most likely consequence is that the adviser:", "choices": ["May continue receiving fees because contributions are protected speech", "Is barred for two years from receiving compensation for advisory services to that government client", "Must simply disclose the contribution in its Form ADV Part 2", "Faces no consequence because the amount is under $2,500"], "answerIndex": 1, "explanation": "Rule 206(4)-5 imposes a two-year 'time out' on compensation for advising a government entity when a covered associate makes a contribution above the de minimis ($150 where the contributor cannot vote for the official). The $1,000 contribution far exceeds $150, triggering the time out (B). The rule is not cured by disclosure alone (C), the contribution is not simply exempt (A), and $2,500 is not the threshold (D).", "difficulty": "hard", "source": "bank"},
  {"id": "law-ethics-4", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Client funds and securities (custody, discretion, prudent investor, suitability, AML, Uniform Prudent Investor Act)", "stem": "Under the Uniform Prudent Investor Act, a trustee's investment decisions are evaluated based on:", "choices": ["Each individual security in isolation to ensure no single holding loses value", "The performance of the portfolio as a whole in the context of an overall investment strategy", "Whether the trust avoided all speculative asset classes entirely", "A guarantee that the portfolio outperforms a relevant market index"], "answerIndex": 1, "explanation": "The Uniform Prudent Investor Act incorporates modern portfolio theory: prudence is judged at the whole-portfolio level within the trust's overall risk/return strategy, not security-by-security (A). No asset class is categorically forbidden (C); even risky assets can be prudent in a diversified portfolio. The standard is one of conduct and process, not a guaranteed result or index outperformance (D).", "difficulty": "medium", "source": "bank"},
  {"id": "law-ethics-5", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Client funds and securities (custody, discretion, prudent investor, suitability, AML, Uniform Prudent Investor Act)", "stem": "An IAR has full discretionary authority over a client's account but the client's securities and cash are held at an unaffiliated qualified custodian, and the adviser cannot withdraw assets except to deduct its agreed advisory fee by invoice. In this arrangement, the adviser most accurately:", "choices": ["Has custody solely because it exercises investment discretion", "Does not necessarily have custody merely by having discretion, though fee deduction is a custody consideration", "Is exempt from all NASAA recordkeeping because a qualified custodian is used", "Must obtain the client's written consent before every individual trade"], "answerIndex": 1, "explanation": "Discretion (deciding what and how much to trade) is distinct from custody (authority to possess assets), so discretion alone does not create custody (A is wrong). Automatic fee deduction is itself a form of custody, though safeguards can provide relief, which is why B is the best statement. Using a qualified custodian does not eliminate recordkeeping duties (C). Discretionary authority means the client need not approve each trade (D is wrong).", "difficulty": "hard", "source": "bank"},
  {"id": "law-ethics-6", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Custody conditions (SEC Rule 206(4)-2, NASAA model rules)", "stem": "Under the NASAA model custody rule and SEC Rule 206(4)-2, an investment adviser that is deemed to have custody of client funds and securities generally must do all of the following EXCEPT:", "choices": ["Maintain client assets with a qualified custodian", "Ensure clients receive account statements at least quarterly", "Guarantee clients against any investment losses in the account", "Undergo an annual surprise examination by an independent accountant"], "answerIndex": 2, "explanation": "Advisers with custody must use a qualified custodian, arrange for at least quarterly account statements, and (under the NASAA model) submit to an annual surprise examination (A, B, D are required). Guaranteeing a client against investment loss (C) is never required and is in fact a prohibited/unethical practice, making it the correct exception.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ethics-7", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Conflicts of interest and prohibited conduct (insider trading, selling away, market manipulation, personal trades, SEC Rule 204A-1, NASAA Unethical Business Practices rules)", "stem": "An IAR learns through a golfing friend, who is a company's CFO, that the company will miss earnings badly next week, and the IAR sells the stock out of client and personal accounts before the news is public. This conduct is best characterized as:", "choices": ["Permissible use of independent research", "Insider trading based on material nonpublic information", "A legitimate exercise of investment discretion", "Selling away requiring only firm notification"], "answerIndex": 1, "explanation": "Trading on material nonpublic information obtained from a corporate insider in breach of a duty is prohibited insider trading (B). It is not independent research (A) because the information was confidential and not public. Discretion (C) authorizes trade timing and selection but never authorizes trading on inside information. Selling away (D) refers to private securities transactions outside one's firm, a different violation entirely.", "difficulty": "easy", "source": "bank"},
  {"id": "law-ethics-8", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Conflicts of interest and prohibited conduct (insider trading, selling away, market manipulation, personal trades, SEC Rule 204A-1, NASAA Unethical Business Practices rules)", "stem": "Under SEC Rule 204A-1, an adviser's code of ethics must, among other things, require its 'access persons' to:", "choices": ["Refrain from owning any individual securities at all times", "Report personal securities holdings and transactions and pre-clear IPOs and limited offerings", "Obtain client approval before the firm hires any new employee", "Publicly disclose their personal brokerage passwords to compliance"], "answerIndex": 1, "explanation": "Rule 204A-1 requires a code of ethics under which access persons submit periodic holdings and transaction reports and pre-clear participation in IPOs and private (limited) offerings (B). Access persons are not barred from all personal investing (A); they must simply report and pre-clear as required. Client approval of hiring (C) and disclosing account passwords (D) are not requirements of the rule.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ethics-9", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Cybersecurity, privacy, data protection (SEC Regulation S-P)", "stem": "A newly registered investment adviser is establishing its data-protection program. Under SEC Regulation S-P, the adviser must:", "choices": ["Provide an initial and annual privacy notice and adopt safeguards for nonpublic personal information", "Share client information freely with any affiliate without any notice", "Delete all client records within 30 days of account closing", "Register its cybersecurity program with FINRA before opening"], "answerIndex": 0, "explanation": "Regulation S-P requires firms to adopt written policies to safeguard customer records and information and to deliver initial and annual privacy notices describing information-sharing practices and opt-out rights (A). It does not permit unrestricted sharing (B), does not mandate deleting records shortly after closing (records must be retained under other rules) (C), and does not require FINRA cybersecurity registration (D).", "difficulty": "medium", "source": "bank"},
  {"id": "law-ethics-10", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Business continuity and succession planning (NASAA model rule)", "stem": "Under the NASAA model rule on business continuity and succession planning, every investment adviser is required to:", "choices": ["Purchase key-person life insurance on each of its principals", "Maintain a written plan addressing protection of records, alternate communications, and orderly transition on loss of key personnel", "Guarantee uninterrupted portfolio management during any disaster", "Merge with a larger firm before it may register with the state"], "answerIndex": 1, "explanation": "The NASAA model rule requires each adviser to create and maintain a written business continuity and succession plan that provides for safeguarding and recovery of records, alternate means of communicating with clients and staff, and an orderly transition if key personnel die or become incapacitated (B). The rule does not mandate specific key-person insurance (A), cannot guarantee zero interruption (C), and does not require merging with a larger firm (D).", "difficulty": "easy", "source": "bank"},
  {"id": "econ-analytical-add-fv", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Time value of money (internal rate of return, net present value)", "stem": "A client invests $10,000 today in an account earning 8% compounded annually. Ignoring taxes and additional contributions, what is the future value of the account at the end of two years?", "choices": ["$11,600","$11,664","$10,800","$12,597"], "answerIndex": 1, "explanation": "Future value with annual compounding is FV = PV x (1 + r)^n = 10,000 x (1.08)^2 = 10,000 x 1.1664 = $11,664, because the second year's interest is earned on the first year's interest as well as the principal. $11,600 results from using simple interest (10,000 + 2 x 800), which ignores compounding. $10,800 is the value after only one year, and $12,597 applies three years of compounding (1.08^3) rather than two.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-basic-add-gdp", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Economic indicators (GDP, employment indicators, trade deficit, balance of payments, CPI)", "stem": "An investment adviser representative is reviewing economic indicators with a client. Which statement about Gross Domestic Product (GDP) is correct?", "choices": ["GDP is a leading indicator that anticipates turns in future economic activity.","GDP is the total market value of all final goods and services produced within a country's borders.","Real GDP is output measured in current-year dollars, unadjusted for inflation.","GDP counts intermediate goods separately so that total output is not understated."], "answerIndex": 1, "explanation": "GDP is defined as the total market value of all final goods and services produced within a country during a period, making choice B correct. It is a coincident/lagging measure reported after the fact, not a leading indicator, so A is wrong. Real GDP is adjusted for inflation, while it is nominal GDP that uses current (unadjusted) dollars, so C reverses the two. Intermediate goods are excluded to avoid double-counting; only final goods and services are counted, so D is wrong.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-analytical-add-range", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Descriptive statistics (mean, median, mode, range, standard deviation, alpha, beta, Sharpe ratio, correlation)", "stem": "Over the past five years, a mutual fund posted annual returns of -8%, 4%, 11%, 6%, and 15%. If an adviser wants to describe the fund's dispersion using the statistical range, what value should she report?", "choices": ["7%","11.6%","23%","15%"], "answerIndex": 2, "explanation": "The statistical range is simply the highest value minus the lowest value: 15% - (-8%) = 23%, so that is correct. 7% is wrong because it treats the -8% low as +8% and subtracts it from the high (15% - 8%), ignoring that the true minimum is negative. 11.6% does not correspond to any correct calculation here (the arithmetic mean is actually 28/5 = 5.6%, and neither the standard deviation nor any other standard statistic equals 11.6%). 15% is merely the single highest return, not the spread between the extremes.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-basic-add-disinflation", "subjectId": "econ", "componentId": "econ-basic", "subtopic": "Inflation/deflation", "stem": "The Consumer Price Index rose 6% one year, 4% the next year, and 2% the year after that, yet the overall price level increased in every one of those years. Which term best describes this economic condition?", "choices": ["Deflation","Disinflation","Stagflation","Hyperinflation"], "answerIndex": 1, "explanation": "This is disinflation: the inflation rate is still positive (prices keep rising), but the rate of increase is slowing from year to year. Deflation is wrong because it means a negative inflation rate—the general price level actually falls—which did not happen here since prices rose every year. Stagflation is wrong because it describes high inflation combined with high unemployment and stagnant growth, not a decelerating price level. Hyperinflation is wrong because it refers to extremely rapid, accelerating inflation, the opposite of the slowing trend shown.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-types-add-marketcap", "subjectId": "vehicles", "componentId": "veh-equity-types", "subtopic": "Common stock, domestic and foreign", "stem": "A company's common stock trades at $25 per share, and the company has 30 million shares outstanding. What is the company's market capitalization, and how is a company of this size most commonly classified?", "choices": ["$750 million, generally classified as small-cap","$750 million, generally classified as large-cap","$30 million, generally classified as small-cap","$1.25 billion, generally classified as mid-cap"], "answerIndex": 0, "explanation": "Market capitalization equals share price times shares outstanding: $25 x 30 million = $750 million, which falls within the small-cap range (commonly roughly $300 million to $2 billion). Choice 2 uses the same $750 million figure but misclassifies it as large-cap, a label typically reserved for companies above about $10 billion. Choice 3 ignores the share price and just counts the 30 million shares, which is not how capitalization is measured. Choice 4 reports a dollar amount the numbers do not produce and mislabels the size class.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-deriv-char-add-coveredcall", "subjectId": "vehicles", "componentId": "veh-deriv-char", "subtopic": "Costs, benefits, and risks of derivative securities", "stem": "A client owns 1,000 shares of a stock trading at $50 and writes 10 covered calls with a $55 strike, collecting a premium. The stock then rallies to $70 before expiration. Which statement best describes the outcome and the primary risk the client accepted?", "choices": ["The client keeps the premium and retains unlimited upside because the shares are owned outright","The client keeps the premium and the shares' downside is fully protected against any decline","The client's upside is capped near $55 plus the premium because the calls will be exercised, obligating delivery of the shares","The client faces theoretically unlimited loss, the same profile as an uncovered call writer"], "answerIndex": 2, "explanation": "A covered call writer collects premium income and a small downside cushion equal to that premium, but in exchange gives up gains above the strike: once the stock trades above $55 the calls are exercised and the writer is obligated to deliver (sell) the shares at $55, forfeiting the rally to $70. Choice A is wrong because writing the call caps, rather than preserves, upside. Choice B overstates the cushion, which only offsets a decline by the premium amount, not any full decline. Choice D confuses the covered writer with a naked writer, whose unlimited risk comes precisely from not owning the underlying shares.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-performance-add-sp500", "subjectId": "recommendations", "componentId": "rec-performance", "subtopic": "Relevant benchmarks", "stem": "An investment adviser wants to recommend a benchmark that reflects the performance of large-capitalization U.S. equities. Which statement BEST describes the S&P 500 index?", "choices": ["It is a price-weighted average of 30 large U.S. industrial stocks","It is a market-capitalization-weighted index of approximately 500 large-cap U.S. companies","It is an equal-weighted index that tracks small-cap U.S. companies","It is a broad benchmark of the U.S. investment-grade bond market"], "answerIndex": 1, "explanation": "The S&P 500 is a market-capitalization-weighted index of roughly 500 leading large-cap U.S. companies, so larger firms exert greater influence on the index's value, making it the standard large-cap equity benchmark. Choice A describes the Dow Jones Industrial Average, which is price-weighted and holds only 30 stocks. Choice C is wrong because the S&P 500 is cap-weighted (not equal-weighted) and measures large-cap, not small-cap, companies. Choice D is wrong because the S&P 500 tracks equities, not bonds; a bond benchmark such as a Bloomberg U.S. Aggregate index would cover investment-grade debt.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-equity-char-add-recorddate", "subjectId": "vehicles", "componentId": "veh-equity-char", "subtopic": "Dividends", "stem": "A corporation's board declares a cash dividend payable to shareholders of record on Thursday. An investor wants to be entitled to this dividend. By the latest, when must the investor purchase the shares to receive it?", "choices": ["Before the ex-dividend date","On the record date","On the ex-dividend date","On the payable date"], "answerIndex": 0, "explanation": "To receive a dividend, an investor must be an owner of record on the record date, and to settle in time to be on the books they must buy before the ex-dividend date (the first day the stock trades without the right to the declared dividend). Buying 'on the record date' is too late because the trade will not have settled, so ownership is not yet recorded. Buying 'on the ex-dividend date' means the purchase carries no right to the dividend by definition. The 'payable date' is simply when the dividend is paid out to those already entitled and has nothing to do with qualifying for it.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-ownership-add-daf", "subjectId": "recommendations", "componentId": "rec-ownership", "subtopic": "Donor advised funds", "stem": "An investment adviser is discussing a donor-advised fund (DAF) with a charitably inclined client who plans to contribute highly appreciated stock. Which statement about the DAF is CORRECT?", "choices": ["The contribution is revocable, so the client may reclaim the assets from the fund if a financial need later arises","The client receives an immediate income tax deduction in the year of contribution, even though grants to charities may be recommended in later years","The client must begin taking required minimum distributions from the DAF after reaching age 73","The client retains legal control over how the sponsoring organization ultimately invests and distributes the assets"], "answerIndex": 1, "explanation": "A gift to a DAF is an irrevocable charitable contribution, so the donor gets an immediate income tax deduction in the year of the gift even though the sponsoring charity may make grants to end charities in later years, making the second choice correct. The first choice is wrong because the contribution is irrevocable and cannot be reclaimed. The third choice is wrong because a DAF is a charitable vehicle, not a retirement account, so it is never subject to required minimum distributions. The fourth choice is wrong because the donor holds only advisory (recommendation) privileges over grants and investments, while legal control rests with the sponsoring organization.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ia-add-late", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Definitions of an investment adviser (USA § 401, IAA § 202)", "stem": "Four professionals each provide some investment advice. Which one is MOST likely EXCLUDED from the definition of investment adviser under the so-called LATE exclusion?", "choices": ["An accountant who, as an integral part of preparing a client's tax return, notes that municipal bond interest would be tax-advantaged and charges only her normal accounting fee","A lawyer who advertises himself as offering securities portfolio management for a separate 1% annual fee","An engineer who leaves his firm to open a business selling written market-timing reports to subscribers","A finance teacher who is separately compensated for managing a wealthy family's stock portfolio on the side"], "answerIndex": 0, "explanation": "The LATE exclusion (Lawyer, Accountant, Teacher, Engineer) applies only when the advice is solely incidental to the practice of the profession AND no special compensation is received for it; the accountant meets both conditions because the advice arises within tax preparation and she charges only her usual accounting fee. The lawyer charging a separate 1% advisory fee and the teacher separately compensated for portfolio management both receive special compensation for advice that is not incidental, so they are advisers. The engineer selling market-timing reports is in the business of advising for compensation and no longer acts incidental to engineering, so he is an investment adviser (indeed a publisher outside any bona fide exclusion).", "difficulty": "medium", "source": "bank"},
  {"id": "law-ia-add-recordkeeping", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Registration and post-registration requirements (books and records, Form ADV, IAA § 203/203A, USA § 201–204, SEC Rules 203A-1/2, 204-1, 204-3, NASAA model rules)", "stem": "A state-registered investment adviser makes its final ledger entry for a client transaction in fiscal year 2023. Under the NASAA model recordkeeping rule (which mirrors SEC Rule 204-2), for how long must the adviser keep that record, and where must it be maintained during the earliest part of that period?", "choices": ["3 years total, with the first year kept at the adviser's principal office","5 years from the end of the fiscal year of the last entry, with the first 2 years in an easily accessible place at the principal office","5 years from the date the account is opened, with all 5 years kept off-site in secure storage","6 years total, with the first 3 years kept at the adviser's principal office"], "answerIndex": 1, "explanation": "Both SEC Rule 204-2 and the parallel NASAA model rule require investment advisers to preserve most books and records for 5 years from the end of the fiscal year in which the last entry was made, with the first 2 of those years kept in an easily accessible place at the adviser's principal office. The 3-year and 6-year options state the wrong retention periods (6 years is the broker-dealer benchmark under SEA Rule 17a-4, not the adviser standard). The '5 years from the date the account is opened' choice uses the wrong trigger date (retention runs from the last entry/fiscal year-end, not account opening) and wrongly bars keeping the recent records readily accessible.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ethics-add-splitcommissions", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Compensation (fees, commissions, performance-based fees, pay-to-play, soft dollars, SEA § 28(e), SEC Rule 206(4)-5, MSRB Rule G-37)", "stem": "Dana is an agent registered with Alpha Securities. She wants to split the commission earned on a customer trade with another individual. With which of the following may Dana lawfully share this commission?", "choices": ["A friend who is a CPA but holds no securities registration, in exchange for the client referral","Any agent registered in the same state, regardless of which broker-dealer employs them","An agent registered with Beta Brokerage, a firm under common control with Alpha Securities","The client, as a rebate to reduce the overall cost of the transaction"], "answerIndex": 2, "explanation": "Commissions may be split only between agents who are registered with the same broker-dealer or with a broker-dealer that is affiliated (under common control) with it; Beta Brokerage being under common control with Alpha makes that split permissible. Sharing with an unregistered CPA is prohibited because splitting commissions with an unregistered person constitutes unlawfully aiding unregistered activity. Being registered in the same state is not enough—the agents must share the same or an affiliated broker-dealer, not merely a common state. Rebating a commission to the client is not a permitted commission split and can be a prohibited practice.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ethics-add-loansclients", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Conflicts of interest and prohibited conduct (insider trading, selling away, market manipulation, personal trades, SEC Rule 204A-1, NASAA Unethical Business Practices rules)", "stem": "An investment adviser representative is short of cash before payday and wants to borrow $5,000 from one of the accounts she manages. Under the NASAA Unethical Business Practices rules, from which of the following clients could she permissibly borrow the money?", "choices": ["A retired schoolteacher who is a long-standing advisory client and has more than enough cash to spare","A commercial bank that is in the business of loaning money and is the source of the loan","A close personal friend who happens to also be an advisory client and has agreed in writing","Any client, provided the loan terms are disclosed in the adviser's Form ADV and the client signs a promissory note"], "answerIndex": 1, "explanation": "Under the NASAA Unethical Business Practices rules, borrowing money from (or lending money to) a client is prohibited unless the client is a broker-dealer, an affiliate of the adviser, or a financial institution in the business of lending money, such as a bank. The commercial bank in the business of loaning money is exactly the permitted exception, so it is correct. The retired teacher and the personal friend are ordinary retail clients not in the lending business, so borrowing from them is prohibited regardless of how much cash they have or that they consented. Disclosure on Form ADV plus a signed note does not cure the violation, because the practice is prohibited for non-lending clients no matter what documentation is provided.", "difficulty": "medium", "source": "bank"},
  {"id": "law-iar-add-iarce", "subjectId": "laws", "componentId": "law-iar", "subtopic": "Registration and post-registration (USA § 201–204, Form U4, NASAA model rules 202(a)-1, 204(b)(6)-1)", "stem": "Under the NASAA Model Rule on investment adviser representative continuing education (204(b)(6)-1), an IAR in a state that has adopted the rule must complete a required number of CE credits each reporting period. How many credits are required annually, and how are they allocated?", "choices": ["12 credits total: 6 Ethics and Professional Responsibility plus 6 Products and Practice","10 credits total: 5 Ethics and Professional Responsibility plus 5 Products and Practice","12 credits total, all of which may be earned in Products and Practice","6 credits total: 3 Ethics and Professional Responsibility plus 3 Products and Practice"], "answerIndex": 0, "explanation": "NASAA Model Rule 204(b)(6)-1 requires an IAR to complete 12 CE credits per year, split into 6 credits of Ethics and Professional Responsibility and 6 credits of Products and Practice. The 10-credit and 6-credit totals are simply the wrong numbers. The choice allowing all 12 credits in Products and Practice is wrong because the rule mandates a fixed split, with 6 credits that must be Ethics and Professional Responsibility.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-tax-add-irmaa", "subjectId": "recommendations", "componentId": "rec-tax", "subtopic": "Government benefit implications (income-related monthly adjustment amounts, IRMAA)", "stem": "A married couple, both age 68 and enrolled in Medicare, ask their adviser about a large Roth conversion this year. Both are already receiving Social Security and have modest wages. Which of the following is the MOST accurate statement about how a spike in their modified adjusted gross income (MAGI) could affect their Medicare costs?", "choices": ["It would raise their Medicare Part A hospital premium, which is income-adjusted for all enrollees","It would trigger an income-related monthly adjustment amount (IRMAA) that increases their Part B and Part D premiums","It would have no effect on Medicare because premiums are the same for every enrollee regardless of income","It would reduce their premiums because higher earners qualify for a Medicare high-income rebate"], "answerIndex": 1, "explanation": "IRMAA is a high-income surcharge that raises the monthly premiums for Medicare Part B (medical) and Part D (drug) once MAGI exceeds set thresholds, so a large Roth conversion that spikes MAGI can push the couple into a higher premium tier, making the second choice correct. Part A is premium-free for most enrollees (those with sufficient work history) and is not income-adjusted, so the first choice is wrong. Premiums are not flat for everyone, which defeats the third choice, and there is no high-income rebate that lowers premiums, so the fourth choice is backwards.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-tax-add-rmd", "subjectId": "recommendations", "componentId": "rec-tax", "subtopic": "Pension and retirement plan distributions (required minimum distributions, RMD)", "stem": "A 73-year-old client holds a traditional IRA and a Roth IRA, both of which she owns and funded herself. Under current federal rules (SECURE 2.0), which statement about her required minimum distributions (RMDs) is correct?", "choices": ["She must take RMDs from both the traditional IRA and the Roth IRA this year","She must take an RMD from the traditional IRA, but no RMD is required from the Roth IRA during her lifetime","Neither account requires an RMD until she reaches age 75","She must take an RMD from the Roth IRA but not from the traditional IRA"], "answerIndex": 1, "explanation": "RMDs from traditional IRAs and qualified plans must begin at age 73 under SECURE 2.0, so at 73 she must take an RMD from her traditional IRA. Roth IRAs require NO RMDs during the original owner's lifetime because contributions were made with after-tax dollars, so the Roth is not subject to lifetime distributions. Age 75 is not the current beginning age (it is scheduled to rise to 75 only in 2033), and the traditional-IRA RMD cannot be waived, so the other choices are wrong. A shortfall in a required distribution triggers a 25% penalty on the amount not taken (reducible to 10% if timely corrected).", "difficulty": "medium", "source": "bank"},
  {"id": "law-ethics-add-vulnerable", "subjectId": "laws", "componentId": "law-ethics", "subtopic": "Conflicts of interest and prohibited conduct (insider trading, selling away, market manipulation, personal trades, SEC Rule 204A-1, NASAA Unethical Business Practices rules)", "stem": "A 79-year-old advisory client suddenly instructs her investment adviser to wire $60,000 to a new overseas account she cannot clearly explain, and the adviser reasonably believes she is the victim of financial exploitation. Under the NASAA Model Act to Protect Vulnerable Adults from Financial Exploitation, what is the adviser permitted to do?", "choices": ["Execute the wire immediately because a competent adult's instructions must always be followed without delay","Delay the disbursement for up to 15 business days and notify the state securities regulator and Adult Protective Services of the suspected exploitation","Permanently freeze all of the client's accounts until she proves the transfer is legitimate","Refuse the transaction and, without notifying any regulator, quietly report the client to local police as the only required step"], "answerIndex": 1, "explanation": "Under the NASAA Model Act, when a qualified adviser reasonably believes financial exploitation of an eligible adult (age 65+ or otherwise vulnerable) has been or may be attempted, the firm may place a temporary hold on the disbursement for up to 15 business days (extendable) and must promptly notify the state securities commissioner and the state's Adult Protective Services, with immunity for good-faith action. Choice A is wrong because the Act specifically authorizes a delay despite the client's instructions. Choice C is wrong because the hold is temporary and applies to the suspicious disbursement, not a permanent freeze of all accounts. Choice D is wrong because mandated notification runs to the securities regulator and APS, not merely local police, and reporting to those agencies is required.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-types-add-floatpfd", "subjectId": "vehicles", "componentId": "veh-equity-types", "subtopic": "Preferred and convertible preferred stock", "stem": "An IAR is comparing two preferred stock issues from the same high-quality corporation for an income-oriented client who is worried that rising interest rates will erode the market value of a fixed-income position. One issue is a traditional fixed-rate preferred; the other is an adjustable-rate (floating-rate) preferred whose dividend resets periodically to a benchmark such as a Treasury bill rate. Which statement about the adjustable-rate preferred is MOST accurate?", "choices": ["Its market price tends to be more stable than the fixed-rate preferred because the dividend resets to a benchmark as rates change","Its dividend is fixed for the life of the issue, so it carries more interest-rate (price) risk than the fixed-rate preferred","It is safer than the fixed-rate preferred because floating-rate preferred holders rank ahead of bondholders in a liquidation","It guarantees a rising dividend each period regardless of what the benchmark rate does"], "answerIndex": 0, "explanation": "Because an adjustable-rate preferred's dividend resets to a benchmark (e.g., a T-bill or other reference rate), the payout rises and falls with market rates, so the stock does not need a large price change to keep its yield competitive; its market price is therefore more stable than a fixed-rate preferred when rates move. The second choice is wrong because a floating-rate preferred's dividend is NOT fixed and it carries LESS price/interest-rate risk than fixed-rate preferred. The third choice is wrong because all preferred stock (fixed or floating) is equity that ranks BEHIND all creditors and bondholders in liquidation, not ahead of them. The fourth choice is wrong because the dividend follows the benchmark and can fall as well as rise; nothing about floating-rate preferred guarantees an increasing dividend.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-ownership-add-cpwros", "subjectId": "recommendations", "componentId": "rec-ownership", "subtopic": "Types of ownership (JTWROS, tenants in common, tenancy by the entirety, community property with rights of survivorship (CPWROS))", "stem": "A married couple living in a community-property state holds their brokerage account as community property with right of survivorship (CPWROS). One spouse dies. Which statement best describes a feature of this ownership form that distinguishes it from joint tenancy with right of survivorship (JTWROS)?", "choices": ["The decedent's one-half interest passes to the probate estate rather than to the surviving spouse","The entire account receives a stepped-up cost basis at the first spouse's death, and the survivor takes the whole account outside probate","Only the decedent's one-half interest receives a stepped-up cost basis, and the survivor's half retains its original basis","The account is automatically split into unequal fractional shares that each spouse may bequeath separately"], "answerIndex": 1, "explanation": "CPWROS combines two benefits: like JTWROS, the right of survivorship passes the whole account to the surviving spouse outside probate, and because it is community property, BOTH halves of the account receive a step-up to fair market value at the first spouse's death (a 'double step-up'). Choice A describes tenancy in common, where a decedent's share passes to their estate, not a survivorship form. Choice C describes the JTWROS/common-law result, where only the decedent's half is stepped up, so it is exactly the feature that distinguishes CPWROS from JTWROS rather than a shared feature. Choice D describes tenancy in common with divisible, separately devisable interests, which contradicts the equal, survivorship nature of CPWROS.", "difficulty": "hard", "source": "bank"},
  {"id": "rec-ownership-add-perstirpes", "subjectId": "recommendations", "componentId": "rec-ownership", "subtopic": "Beneficiary designation (including per stirpes)", "stem": "A client names her three children as equal primary beneficiaries of her IRA, designated per stirpes. Before the client dies, one child predeceases her, leaving two children (the client's grandchildren) of his own. When the client dies, how are the IRA assets distributed?", "choices": ["The two surviving children split the entire account equally, and the grandchildren receive nothing","Each surviving child receives one-third, and the deceased child's one-third share is divided equally between his two children (the grandchildren)","All assets are divided equally among the two surviving children and the two grandchildren, one-fourth each","The deceased child's share reverts to the client's estate and passes under her will"], "answerIndex": 1, "explanation": "Per stirpes means a deceased beneficiary's share passes down that beneficiary's line of descendants, so the predeceased child's one-third is split between his two children (one-sixth each) while each surviving child keeps a full one-third. Choice A describes a per capita result, where a deceased beneficiary's share is redistributed only among the surviving named beneficiaries, so it is wrong here. Choice C treats all descendants equally (per capita at each generation / one-fourth each), which is not how per stirpes divides by branch. Choice D is wrong because a valid beneficiary designation controls the account and bypasses probate, so the share does not revert to the estate.", "difficulty": "medium", "source": "bank"},
  {"id": "law-securities-add-finders", "subjectId": "laws", "componentId": "law-securities", "subtopic": "Definitions of security and issuer (USA § 401)", "stem": "An individual is paid a flat fee by a broker-dealer each time she introduces a prospective client who later opens an account. She never discusses specific securities, quotes prices, or takes orders — she only makes the introductions. Under the Uniform Securities Act, which statement best describes her status?", "choices": ["Because she is compensated for referring investors, she is acting as a finder and a state may require her to register, typically as an agent","She is exempt from all registration because she never recommends or sells specific securities","Finders are regulated exclusively by the SEC, so no state registration can apply to her","She is automatically an investment adviser because she is paid in connection with securities business"], "answerIndex": 0, "explanation": "A 'finder' who is paid to introduce or refer prospective investors is receiving transaction-related compensation, and states retain authority to require such persons to register (commonly as agents/broker-dealer agents). Choice B is wrong because compensation for referrals — not whether she names specific securities — is what triggers registration. Choice C is wrong because states have clear authority over finders under the USA; it is not solely an SEC matter. Choice D is wrong because being paid for referrals does not make someone an investment adviser, which requires giving advice about securities for compensation.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-analytical-add-empirical", "subjectId": "econ", "componentId": "econ-analytical", "subtopic": "Descriptive statistics (mean, median, mode, range, standard deviation, alpha, beta, Sharpe ratio, correlation)", "stem": "A mutual fund has an expected annual return of 8% with a standard deviation of 12%. Assuming returns are normally distributed, approximately 95% of the fund's annual returns should fall within which range?", "choices": ["-16% to +32%","-4% to +20%","-28% to +44%","+8% to +20%"], "answerIndex": 0, "explanation": "In a normal distribution, the empirical rule states that about 95% of outcomes fall within plus or minus 2 standard deviations of the mean. Here that is 8% ± (2 × 12%) = 8% ± 24%, giving a range of -16% to +32%, so that choice is correct. -4% to +20% is only ±1 SD, which captures about 68% (not 95%) of returns. -28% to +44% is ±3 SD, which captures about 99.7%. +8% to +20% spans only the mean up to +1 SD and is neither centered on the mean nor a full 2-SD band, so it does not reflect the empirical rule.", "difficulty": "medium", "source": "bank"},
  {"id": "econ-risk-add-callrisk", "subjectId": "econ", "componentId": "econ-risk", "subtopic": "Unsystematic risks", "stem": "A client owns a 20-year, 7% callable corporate bond that has been trading at a premium because market interest rates have fallen sharply since issuance. The client is concerned about what happens if the issuer exercises the call. Which risk is the client MOST directly exposed to, and what is its practical consequence?", "choices": ["Default (credit) risk, because a call means the issuer can no longer make its coupon payments","Interest-rate risk, because the bond's price will fall as rates decline","Call risk, because the bond is likely to be redeemed early and the proceeds must be reinvested at today's lower prevailing yields","Purchasing-power risk, because inflation will erode the value of the called principal"], "answerIndex": 2, "explanation": "Call risk is the risk that an issuer redeems a bond early - typically after rates have fallen and the bond trades at a premium - forcing the investor to reinvest the returned principal at the now-lower prevailing yields and capping the bond's price appreciation near the call price. That is exactly the client's situation, so choice C is correct. A call is triggered by the issuer's option, not by an inability to pay, so it is not default risk (A). Interest-rate risk works in the opposite direction described - falling rates raise a bond's price, not lower it (B). Purchasing-power (inflation) risk is a systematic, market-wide risk unrelated to the issuer's call decision (D). Call/prepayment risk is distinguished from generic reinvestment risk precisely because it is set in motion by the issuer's or borrower's redemption option.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-cash-add-inflationrisk", "subjectId": "vehicles", "componentId": "veh-cash", "subtopic": "Insured deposits (demand deposits, certificates of deposit)", "stem": "A retired client keeps the large majority of her portfolio in bank savings accounts, short-term CDs, and a money-market deposit account because she wants to avoid losing money. Over a multi-decade retirement, which risk is she MOST exposed to by holding this much cash and cash equivalents?", "choices": ["Purchasing-power (inflation) risk, because the low yields may not keep pace with inflation and erode the real value of her money","Credit (default) risk, because bank deposits and CDs are unsecured obligations with no principal protection","Market (price) risk, because the principal value of insured deposits and CDs fluctuates daily with interest rates","Liquidity risk, because CDs and money-market deposits cannot be converted to cash without a lengthy holding period"], "answerIndex": 0, "explanation": "Cash and cash equivalents preserve nominal principal and are highly liquid, but their low yields often fail to keep pace with inflation, so the real (inflation-adjusted) value of the money erodes over a long time horizon; this purchasing-power risk is the key drawback of holding too much cash, making choice A correct. Credit risk is minimal here because bank deposits and CDs up to applicable limits are FDIC-insured, so B is wrong. These instruments preserve nominal principal and do not fluctuate in price like bonds or stocks, so B and C misstate the nature of the risk. Cash equivalents are among the most liquid holdings a client can own, so D is incorrect.", "difficulty": "easy", "source": "bank"},
  {"id": "veh-fixed-char-add-fixedliquidity", "subjectId": "vehicles", "componentId": "veh-fixed-char", "subtopic": "Characteristics (tax implications, liquidity, liquidation preference, call features, coupon vs. zero coupon, duration, premium)", "stem": "An adviser is explaining liquidity (marketability) risk to a client who holds several fixed-income securities. Which statement is MOST accurate?", "choices": ["U.S. Treasury securities are the most liquid fixed-income instruments and trade with the narrowest bid-ask spreads","A bond's credit rating fully determines its liquidity, so any highly rated bond is necessarily easy to sell quickly at a fair price","Liquidity risk describes a creditor's ranking in the priority of claims if the issuer enters bankruptcy","Thinly traded small municipal issues generally trade with narrower bid-ask spreads and lower yields than comparable Treasuries"], "answerIndex": 0, "explanation": "U.S. Treasuries have the deepest, most active market of any fixed-income class, so they trade with the narrowest bid-ask spreads and are the benchmark for liquidity, making the first choice correct. The second choice confuses liquidity with credit risk: a bond can be high credit quality yet illiquid (for example, a small, thinly traded high-grade municipal issue), so a strong rating does not guarantee marketability. The third choice describes liquidation preference (creditor seniority in bankruptcy), not liquidity, which concerns how quickly and cheaply a security can be sold. The fourth choice is backwards: thinly traded small munis carry liquidity risk, trade with WIDER spreads, and must offer a liquidity premium (higher yield) to attract buyers.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-char-add-cumvoting", "subjectId": "vehicles", "componentId": "veh-equity-char", "subtopic": "Shareholder rights (voting rights, antidilution, liquidation preferences)", "stem": "A shareholder owns 1,000 shares of common stock in a corporation that is electing four directors, with one open seat per candidate. Under which voting method may the shareholder cast all 4,000 votes for a single candidate, and why does that method matter?", "choices": ["Cumulative voting, because the shareholder multiplies shares by open seats and may concentrate those votes on one nominee, improving minority shareholders' chances of winning a board seat","Statutory (straight) voting, because it lets a shareholder pool votes across candidates and therefore favors minority shareholders","Cumulative voting, because it caps each shareholder at 1,000 votes per candidate regardless of the number of open seats","Statutory (straight) voting, because the shareholder may cast up to 4,000 votes for any one candidate on each ballot line"], "answerIndex": 0, "explanation": "Under cumulative voting a shareholder multiplies shares owned by the number of open seats (1,000 x 4 = 4,000) and may concentrate all of those votes on one candidate, which is precisely why the method helps minority shareholders gain board representation. Statutory (straight) voting instead lets a shareholder cast up to the number of shares owned (1,000) for each seat separately, so it favors large or majority holders and is why choices B and D are wrong. Choice C misstates cumulative voting by ignoring the multiplication by open seats; the whole point is that votes are aggregated, not capped at the share count per candidate.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-equity-types-add-pfdfeatures", "subjectId": "vehicles", "componentId": "veh-equity-types", "subtopic": "Preferred and convertible preferred stock", "stem": "An investor buys preferred stock specifically because she wants to profit if the issuer's common stock appreciates substantially over the years. Which preferred-stock feature directly serves this goal?", "choices": ["Convertible","Callable","Participating","Cumulative"], "answerIndex": 0, "explanation": "Convertible preferred lets the holder exchange each share for a fixed number of common shares, so if the common stock rises well above the conversion price the holder can convert and capture that appreciation. Callable is wrong because the call feature is the issuer's right to redeem the shares (typically at par plus a small premium when rates fall), which benefits the issuer, not the holder's upside. Participating preferred pays extra dividends beyond the stated rate when the company is profitable, but that is added income, not participation in common-share price appreciation. Cumulative preferred only guarantees that any dividends in arrears are paid before common dividends; it protects income but does not tie the investor to common-stock growth.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-pooled-char-add-roc", "subjectId": "vehicles", "componentId": "veh-pooled-char", "subtopic": "Tax implications", "stem": "An investor buys mutual fund shares for $10,000. Over several years the fund pays her $1,500 in distributions that the fund classifies as a return of capital, and she reinvests nothing. Which statement about the tax treatment of these return-of-capital distributions is correct?", "choices": ["They are taxed as ordinary dividend income in the year received and do not affect her cost basis","They are not taxed when received but reduce her cost basis to $8,500, increasing her taxable gain when she sells","They are taxed as long-term capital gains when received and raise her cost basis to $11,500","They are permanently tax-free and have no effect on her cost basis at any point"], "answerIndex": 1, "explanation": "A return of capital (ROC) is not paid out of the fund's income or realized gains, so it is treated as the investor getting her own money back; it is not taxed when received but instead reduces her cost basis (here from $10,000 to $8,500), which increases the taxable capital gain (or reduces the loss) she reports on eventual sale. The first and third choices are wrong because ROC is not current dividend or capital-gain income and it lowers, not raises, basis. The fourth choice is wrong because ROC is not permanently tax-free and does affect basis; the tax is deferred and effectively collected as a larger gain at sale, not eliminated.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-pooled-char-add-buyingdividend", "subjectId": "vehicles", "componentId": "veh-pooled-char", "subtopic": "Tax implications", "stem": "A client with $50,000 to invest tells her adviser she wants to buy shares of a mutual fund next week, three days before the fund's ex-distribution date, specifically so she can \"capture\" the upcoming distribution. Which of the following best describes the adviser's most appropriate response?", "choices": ["She should wait until after the ex-distribution date, because buying just before it forces her to pay tax on a distribution that is effectively a return of her own principal with no economic gain","She should buy immediately, because receiving the distribution increases the total value of her investment","She should buy immediately, because the distribution will be treated as a nontaxable return of capital","She should wait, because federal law prohibits purchasing fund shares within 30 days of a distribution"], "answerIndex": 0, "explanation": "This is the classic \"buying a dividend\" problem: on the ex-distribution date the fund's NAV drops by the amount of the distribution, so the investor's total value is unchanged, yet she immediately owes tax on the distribution even though it is really a return of the money she just invested, making the timing disadvantageous. Choice B is wrong because the distribution does not add value - the NAV falls by the same amount, so her position is a wash before taxes and worse after. Choice C is wrong because a normal dividend or capital-gains distribution is taxable when received, not a nontaxable return of capital. Choice D is wrong because no federal law bans buying near a distribution date; the concern is purely tax efficiency, not legality.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-pooled-char-add-exchangepriv", "subjectId": "vehicles", "componentId": "veh-pooled-char", "subtopic": "Share classes", "stem": "An investor owns Class A shares of a growth fund within the XYZ fund family and uses the family's exchange (conversion) privilege to move the money into Class A shares of a bond fund in the same family. Which statement about this transaction is CORRECT?", "choices": ["The exchange is a taxable event that may realize a capital gain or loss, even though no new sales charge is imposed","Because it occurs within the same fund family, the exchange is tax-deferred until the bond-fund shares are ultimately redeemed","The exchange triggers a new front-end sales charge but is not a taxable event","The privilege lets the investor exchange into a different share class of any fund in the family free of both tax and sales charges"], "answerIndex": 0, "explanation": "An exchange privilege lets a shareholder move from one fund to another in the same family, usually at net asset value with no new sales charge, but the IRS treats the swap as a sale of the old shares and a purchase of the new ones, so any gain or loss is realized and currently taxable. That makes the first choice correct and the tax-deferred choice wrong. It is the absence, not the imposition, of a new sales charge that is the typical benefit, so the choice claiming a new front-end charge is wrong. Exchange privileges apply to the same share class within the family, not any share class free of everything, so the last choice overstates the benefit and ignores the tax consequence.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-insurance-add-payoutoptions", "subjectId": "vehicles", "componentId": "veh-insurance", "subtopic": "Annuities (fixed, variable, equity indexed)", "stem": "A 66-year-old client is annuitizing a nonqualified annuity. She is single, has no dependents, and her chief concern is maximizing the size of each monthly payment she receives for as long as she lives. Which settlement (payout) option best fits her stated objective?", "choices": ["Life with 20-year period certain","Joint-and-survivor annuity","Straight (pure) life annuity","Unit (cash) refund annuity"], "answerIndex": 2, "explanation": "A straight (pure) life annuity pays only over the annuitant's life and provides no death benefit or refund to any beneficiary, so it produces the largest monthly payment of the available options and matches a client who wants the maximum income and has no heirs to protect. Life with period certain guarantees payments to a beneficiary for a minimum number of years if she dies early, and a unit/cash refund returns the unpaid balance to a beneficiary; both trade income away for that protection, so each pays less per month. A joint-and-survivor option spreads payments over two lives and pays the least, and it is pointless here because she has no second life to cover.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-insurance-add-immediatedeferred", "subjectId": "vehicles", "componentId": "veh-insurance", "subtopic": "Annuities (fixed, variable, equity indexed)", "stem": "A 68-year-old client has just received a $250,000 lump sum and wants to convert it into a stream of monthly income that begins next month, with no interest in an accumulation period. Which annuity best fits this objective?", "choices": ["A single-premium immediate annuity (SPIA), which begins payouts almost right away and has no accumulation phase","A single-premium deferred annuity, which accumulates value tax-deferred before any payout begins","A periodic-premium deferred annuity, which the client funds with monthly contributions over many years","A flexible-premium deferred variable annuity, which invests contributions in subaccounts during a long accumulation phase"], "answerIndex": 0, "explanation": "A single-premium immediate annuity (SPIA) is funded with one lump-sum payment and begins the payout (annuitization) phase almost immediately, skipping any accumulation period, which exactly matches the client's goal of income starting next month. Choice 2 is wrong because a deferred annuity, even one funded with a single premium, holds and grows the money tax-deferred during an accumulation phase and does not begin payouts right away. Choice 3 is wrong because periodic-premium contracts are inherently deferred (you cannot fund an immediate payout with future installments) and are used to build value over time, not to start income now. Choice 4 is likewise a deferred product with a long accumulation phase in variable subaccounts, the opposite of the client's stated objective.", "difficulty": "medium", "source": "bank"},
  {"id": "veh-other-add-futuresleverage", "subjectId": "vehicles", "componentId": "veh-other", "subtopic": "Commodities and precious metals", "stem": "An IAR is explaining to a client how buying a commodity futures contract differs from simply buying and holding the physical commodity. Which statement BEST describes the effect of leverage on a long futures position?", "choices": ["The client deposits only a small good-faith margin that controls a much larger notional value, so both gains and losses are magnified and losses can exceed the amount originally deposited","Because futures require the full contract value to be paid up front, leverage eliminates the possibility of losing more than the client invests","Futures margin is a partial down payment that is amortized like a loan, so the client can never be required to add funds before expiration","The client's maximum possible loss on a long futures position is limited to the good-faith margin deposited, just as with owning the physical commodity"], "answerIndex": 0, "explanation": "A futures position requires only a small good-faith deposit (performance bond, or 'margin') that controls a much larger notional contract value, so percentage price moves translate into magnified gains and losses; because losses are not capped at the deposit, the client can be required to meet variation margin calls and can lose MORE than the amount originally deposited. The second choice is wrong because futures do NOT require paying the full contract value up front - that is the whole source of the leverage. The third is wrong because futures margin is a performance bond, not an amortizing loan, and adverse moves trigger maintenance/variation margin calls before expiration. The fourth is wrong because, unlike owning the physical commodity outright (where loss is limited to what you paid), a leveraged futures loss can exceed the initial margin.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-tax-add-bondinteresttax", "subjectId": "recommendations", "componentId": "rec-tax", "subtopic": "Individual income tax (capital gains, qualified dividends, tax basis, marginal bracket, AMT)", "stem": "An investor in a high state-income-tax state holds three bonds of comparable stated yield: an in-state municipal bond, a U.S. Treasury bond, and a corporate bond. Which statement correctly describes the taxation of the interest each pays?", "choices": ["Municipal interest is exempt from federal tax and typically from the investor's state tax; Treasury interest is federally taxable but state-tax exempt; corporate interest is fully taxable at both levels","All three bonds' interest is exempt from federal tax but fully taxable at the state level","Treasury interest is exempt from federal tax, while municipal and corporate interest are taxable at both the federal and state levels","Municipal and Treasury interest are both fully taxable at the federal level, while only corporate interest escapes state tax"], "answerIndex": 0, "explanation": "Municipal bond interest is exempt from federal income tax and is usually also exempt from state income tax for a resident holding an in-state issue, making choice A correct. U.S. Treasury interest is taxable at the federal level but exempt from state and local income tax, and corporate bond interest is fully taxable at both the federal and state levels. Choice B is wrong because Treasury and corporate interest are not federally exempt. Choice C reverses the treatment, wrongly making Treasuries federally exempt while taxing municipals. Choice D is wrong because municipal interest is federally exempt and Treasury interest is federally taxable, the opposite of what it states.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-retirement-add-rollovers", "subjectId": "recommendations", "componentId": "rec-retirement", "subtopic": "IRAs (traditional, Roth)", "stem": "A client is leaving her employer and wants to move the full balance of her qualified 401(k) plan into a traditional IRA without triggering current tax or any mandatory withholding. Which method should the agent recommend?", "choices": ["A direct trustee-to-trustee transfer from the plan custodian to the IRA custodian","A 60-day indirect rollover, with the check made payable to the client","Taking a full distribution and repurchasing the same securities inside the IRA within 60 days","Rolling the funds to an IRA now and completing a second IRA-to-IRA indirect rollover next month"], "answerIndex": 0, "explanation": "A direct (trustee-to-trustee) transfer moves the funds custodian-to-custodian, so the owner never takes possession; there is no current tax, no mandatory 20% withholding, and such transfers are unlimited in frequency. An indirect 60-day rollover from an employer qualified plan pays the owner and is subject to a mandatory 20% withholding, so the client would have to make up that withheld amount from other funds to avoid tax on it, defeating her goal. Taking a full distribution likewise triggers the 20% withholding and only allows redeposit within 60 days. Chaining IRA-to-IRA indirect rollovers is both unnecessary and limited to once per 12 months, so it is the wrong recommendation.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-retirement-add-sepsimple", "subjectId": "recommendations", "componentId": "rec-retirement", "subtopic": "Qualified retirement plans", "stem": "A business owner with 40 employees wants to sponsor an IRA-based retirement plan in which the employees can make their own pre-tax salary-deferral contributions and the employer is required to contribute as well. Which plan best meets these requirements?", "choices": ["A SIMPLE IRA","A SEP-IRA","A traditional IRA funded solely by the individual","A SEP-IRA converted to a Roth IRA"], "answerIndex": 0, "explanation": "A SIMPLE IRA is the correct choice because it is designed for small employers (generally 100 or fewer employees) and is the only IRA-based plan that permits employee salary-deferral contributions combined with a mandatory employer match or nonelective contribution. A SEP-IRA is funded by employer contributions only, so employees cannot make salary-deferral contributions, which fails the owner's requirement. A traditional IRA funded solely by the individual involves no employer contribution at all and is not an employer-sponsored plan. Converting a SEP-IRA to a Roth is merely a taxable conversion and still would not allow employee deferrals or a required employer match.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-accounts-add-529types", "subjectId": "recommendations", "componentId": "rec-accounts", "subtopic": "Education accounts (529 plans, Coverdell)", "stem": "A client wants to save for her newborn's college education. She wants the account's value to have the potential to grow with the markets and wants the flexibility to use the money for tuition, room and board, and books at a wide range of colleges. Which 529 option best fits these goals?", "choices": ["A prepaid tuition plan, because it locks in future tuition at today's rates","A college savings plan, because contributions are invested in market-based options and can cover a broad range of qualified higher-education expenses at most schools","A prepaid tuition plan, because its account value fluctuates with the markets","A college savings plan, but the funds may only be used to pay tuition"], "answerIndex": 1, "explanation": "A college savings plan is an investment account whose value rises and falls with the markets and whose proceeds can be used for a broad range of qualified higher-education expenses (tuition, room and board, books, etc.) at most accredited schools, which matches the client's desire for market growth and flexibility. A prepaid tuition plan (choices 1 and 3) does the opposite: it lets a saver lock in and prepay future tuition at today's rates, is typically limited to tuition at in-state public colleges, and does not fluctuate with the markets or grow with investment performance, so choice 3 is also factually wrong about how prepaid plans work. Choice 4 correctly names the college savings plan but wrongly restricts its use to tuition; the college savings plan's key advantage is its broad range of eligible qualified expenses.", "difficulty": "easy", "source": "bank"},
  {"id": "rec-ownership-add-trusttypes", "subjectId": "recommendations", "componentId": "rec-ownership", "subtopic": "Trusts and wills", "stem": "A client wants to transfer assets to her heirs at death while keeping those assets out of the probate process, and she wants to be able to amend or cancel the arrangement during her lifetime. Which arrangement best meets all of these goals?", "choices": ["A testamentary trust created under the terms of her will","A funded revocable inter vivos (living) trust","An irrevocable inter vivos trust","A pour-over will directing assets into a testamentary trust"], "answerIndex": 1, "explanation": "A funded revocable inter vivos (living) trust is created and funded during the grantor's lifetime, so at death the trust assets pass to beneficiaries outside probate, and because it is revocable the grantor may amend or revoke it at any time -- meeting every stated goal. A testamentary trust is created by the will and springs into existence only at death, so the assets first pass through probate, which the client wants to avoid; a pour-over will likewise moves assets through the will and probate before funding a testamentary trust. An irrevocable trust can avoid probate if funded during life, but by definition it generally cannot be amended or revoked, so it fails the client's control requirement.", "difficulty": "medium", "source": "bank"},
  {"id": "rec-performance-add-alpha", "subjectId": "recommendations", "componentId": "rec-performance", "subtopic": "Returns (risk-adjusted, time-weighted, dollar-weighted, annualized, total, holding period, IRR, expected, inflation-adjusted, after-tax)", "stem": "A portfolio has a beta of 1.2. Over the past year the risk-free rate was 2%, the market returned 10%, and the portfolio actually returned 15%. Using the capital asset pricing model, what was the portfolio's alpha, and what does it indicate?", "choices": ["+3.4%, indicating the manager added value beyond what the systematic risk taken would justify","+5.0%, indicating the portfolio simply outperformed the market on a raw-return basis","-3.4%, indicating the manager underperformed the return predicted by the portfolio's beta","0%, indicating the portfolio's return exactly matched its CAPM-expected return"], "answerIndex": 0, "explanation": "CAPM predicts an expected return of 2% + 1.2 x (10% - 2%) = 11.6%; alpha is the actual return minus this expected return, or 15% - 11.6% = +3.4%. A positive alpha means the manager earned more than the systematic (beta) risk taken would justify, signaling value added through skill. Choice B (+5.0%) is just the raw excess over the market (15% - 10%) and ignores the extra risk the higher beta required, so it is not alpha. Choice C has the correct magnitude but the wrong sign, and choice D is wrong because the actual return exceeded the CAPM-predicted return rather than matching it.", "difficulty": "hard", "source": "bank"},
  {"id": "law-ia-add-deminimis", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Definitions of an investment adviser (USA § 401, IAA § 202)", "stem": "An investment adviser has its only office in State A and no place of business in State B. During the preceding 12 months its only State B contacts were 5 individual (retail) clients who reside in State B and 8 banks and insurance companies that reside in State B. Must the adviser register as an investment adviser in State B?", "choices": ["Yes, because it had a total of 13 clients residing in State B, which exceeds the de minimis limit","No, because it has no place of business in State B and had no more than 5 non-institutional clients there, and institutional clients are not counted","Yes, because the de minimis exemption is available only to federal-covered advisers","No, because an adviser with no place of business in a state is never required to register there"], "answerIndex": 1, "explanation": "Under the Uniform Securities Act's de minimis exemption, an adviser with no place of business in a state need not register there if, during the preceding 12 months, it had no more than 5 non-institutional (retail) clients who are residents of that state. Institutional clients such as banks and insurance companies are excluded from the count, so the 8 institutions are irrelevant and the 5 retail residents are within the limit, making choice B correct and choice A wrong for lumping in institutional clients. Choice C is wrong because this is a state-law exemption for advisers lacking a place of business, not something limited to federal-covered advisers (who never register with states in the first place). Choice D is wrong because 'no place of business' alone is not enough — the exemption also requires 5 or fewer retail state residents, so a sixth retail client would force registration.", "difficulty": "medium", "source": "bank"},
  {"id": "law-ia-add-brochure48", "subjectId": "laws", "componentId": "law-ia", "subtopic": "Registration and post-registration requirements (books and records, Form ADV, IAA § 203/203A, USA § 201–204, SEC Rules 203A-1/2, 204-1, 204-3, NASAA model rules)", "stem": "An investment adviser hands its Form ADV Part 2A brochure to a prospective client at the very moment the client signs the advisory contract, rather than at least 48 hours beforehand. Under the NASAA model brochure rule (which parallels SEC Rule 204-3), this delivery timing is permissible only if the adviser also:", "choices": ["files a copy of the executed contract with the state securities administrator within 48 hours of signing","obtains the client's written acknowledgment that the brochure was received before any advisory fee is charged","gives the client the right to terminate the advisory contract without penalty within five business days of entering into it","limits the arrangement to clients whose regulatory assets under management exceed $100 million"], "answerIndex": 2, "explanation": "The brochure must be delivered either at least 48 hours before entering the advisory contract OR at the time of entering the contract, provided the client then has a five-business-day right to terminate the contract without penalty. Because this adviser delivered at signing rather than 48 hours in advance, it must grant that five-business-day penalty-free termination window, so the third choice is correct. There is no rule requiring the executed contract to be filed with the administrator within 48 hours (the '48 hours' figure describes advance brochure delivery, not a filing deadline), so the first choice is wrong. A written receipt acknowledgment is a good practice but is not the condition that cures at-signing delivery, making the second choice wrong. The five-business-day alternative applies to all advisory clients regardless of size, so the AUM threshold in the fourth choice is irrelevant.", "difficulty": "medium", "source": "bank"},
  {"id": "law-bd-add-consentservice", "subjectId": "laws", "componentId": "law-bd", "subtopic": "Registration and post-registration requirements", "stem": "Under Section 414 of the Uniform Securities Act, an applicant for registration as a broker-dealer must file a consent to service of process. Which statement about this consent is correct?", "choices": ["It irrevocably appoints the state Administrator as the applicant's attorney to receive legal process, with such service having the same force as personal service on the applicant","It must be renewed and re-filed with the Administrator each year at registration renewal","It authorizes the Administrator to receive service only in criminal matters, not civil suits or administrative notices","It may be revoked by the registrant at any time upon 30 days' written notice to the Administrator"], "answerIndex": 0, "explanation": "The consent to service of process is an irrevocable appointment of the Administrator as the applicant's attorney (agent) to receive noncriminal legal papers, and service on the Administrator is legally equivalent to personal service on the applicant. It is filed once and remains permanently on file, so it is not re-filed annually with each renewal, making that choice wrong. It covers civil lawsuits and administrative notices arising under the Act - not exclusively criminal matters. Because the consent is expressly irrevocable, it cannot be withdrawn on notice by the registrant.", "difficulty": "medium", "source": "bank"},
  {"id": "law-bd-add-bdeffective", "subjectId": "laws", "componentId": "law-bd", "subtopic": "Registration and post-registration requirements", "stem": "A broker-dealer files a complete application to register in a state. No stop order is entered and no proceeding is pending against the applicant. The applicant files its last required amendment on the morning of March 1. Absent any action by the Administrator, when does the registration become effective under the Uniform Securities Act?", "choices": ["Immediately upon filing of the last required amendment","At noon of the 30th day after the last required amendment is filed","45 days after the initial application was filed","At the close of business on the 30th day after the initial application was filed"], "answerIndex": 1, "explanation": "Under the Uniform Securities Act, if no stop order is in effect and no proceeding is pending, a registration becomes effective at noon of the 30th day after the last required amendment is filed. Effectiveness is measured from the last required amendment, not the initial application, which makes the '45 days' and '30th day after the initial application' choices wrong, and effectiveness is not immediate upon filing. The Administrator may by rule or order specify an earlier effective date, but absent such action the statutory noon-of-the-30th-day rule controls.", "difficulty": "medium", "source": "bank"},
  {"id": "law-securities-add-exempttxn", "subjectId": "laws", "componentId": "law-securities", "subtopic": "Securities registration process (SA § 5, § 18, Reg D, USA § 301–305, § 402)", "stem": "The executor of a deceased investor's estate liquidates a block of non-registered, non-exempt common stock through a broker-dealer to raise cash for the heirs. Under the Uniform Securities Act, which statement BEST describes the status of this sale?", "choices": ["It is an exempt transaction because it is effected by a fiduciary, even though the stock itself is neither registered nor an exempt security","It is prohibited because non-exempt securities may never be sold unless they are first registered in the state","The stock becomes an exempt security once it is held by an estate, so no further analysis is required","It qualifies only if the executor also files a registration statement by qualification before the sale"], "answerIndex": 0, "explanation": "USA § 402(b) lists transactions by a fiduciary such as an executor, administrator, trustee, guardian, or bankruptcy trustee among the exempt transactions, so the executor's sale is exempt from the registration and advertising-filing requirements regardless of whether the underlying stock is registered or an exempt security. The key principle is that the exemption attaches to the transaction, not to the security, which is why the choice claiming the security itself becomes exempt is wrong and why no registration by qualification is needed. The choice stating non-exempt securities can never be sold without registration ignores the entire category of exempt transactions in § 402(b).", "difficulty": "medium", "source": "bank"},
  {"id": "law-remedies-add-jointliability", "subjectId": "laws", "componentId": "law-remedies", "subtopic": "Other penalties and liabilities (USA § 409, § 410, § 411)", "stem": "An agent of a broker-dealer made an unlawful sale of securities to a customer, and the customer has sued the agent for civil liability under the Uniform Securities Act. The agent's branch sales manager, who directly supervised the agent, materially aided the transaction. Which statement about the sales manager's liability is correct?", "choices": ["The sales manager is jointly and severally liable to the same extent as the agent, unless he proves he did not know and, in the exercise of reasonable care, could not have known of the facts giving rise to the liability","The sales manager has no civil liability because only the person who actually made the sale can be held liable to the buyer","The customer must prove the sales manager knew of the facts giving rise to the liability before the manager can be held liable","The sales manager is liable only for the commissions he personally earned on the transaction, not the full amount recoverable from the agent"], "answerIndex": 0, "explanation": "Under USA Section 410, persons who directly or indirectly control the seller, and partners, officers, directors, and agents who materially aid in the sale, are jointly and severally liable to the same extent as the seller—so the supervising manager who materially aided is liable for the full recovery, not just his commissions (making the fourth choice wrong). The statute does provide a defense, but the burden is on the control/aiding person to prove he did not know and could not have known of the facts through reasonable care; the plaintiff does not have to prove the manager's knowledge (making the third choice wrong). The claim that only the actual seller can be liable ignores the joint-and-several liability the statute expressly imposes on controlling and materially-aiding persons.", "difficulty": "medium", "source": "bank"},
  {"id": "law-remedies-add-cancellation", "subjectId": "laws", "componentId": "law-remedies", "subtopic": "Administrative actions (USA § 408)", "stem": "An investment adviser representative who has been properly registered in a state dies unexpectedly. The Administrator wishes to remove the deceased representative's registration from its records. Which action will the Administrator take, and what must it establish first?", "choices": ["Cancel the registration; because the registrant has died, cancellation requires no finding of wrongdoing and no public-interest determination","Revoke the registration, but only after finding that revocation is in the public interest and that a statutory cause exists","Suspend the registration pending a hearing to determine whether cause for disciplinary action exists","Deny the registration for failure to remain in compliance with the statutory qualification requirements"], "answerIndex": 0, "explanation": "Cancellation is a non-punitive, administrative housekeeping action: the Administrator cancels a registration when the registrant has died, been dissolved, ceased doing business, cannot be located, or has been declared mentally incompetent, and it need not find any wrongdoing, enumerated cause, or public interest. Revocation and suspension are punitive disciplinary actions that require both a statutory cause and a finding that the action is in the public interest (with an opportunity for a hearing), so B and C misapply those standards to a mere death. Denial applies only to a pending application for registration, not to a registration already in effect, so D is inapposite here.", "difficulty": "medium", "source": "bank"},
];
